function H.new(class, props, parent)
local o = Instance.new(class)
for k,v in pairs(props or {}) do o[k] = v end
o.Parent = parent
return o
end
function H.con(signal,fn)
local c = signal:Connect(fn)
table.insert(connections,c)
return c
end
H.con(UIS.WindowFocused,function() robloxHasFocus=true end)
H.con(UIS.WindowFocusReleased,function() robloxHasFocus=false end)
function H.round(o,r) H.new("UICorner",{CornerRadius=UDim.new(0,r)},o) end
function H.stroke(o,color,w)
return H.new("UIStroke",{Color=color,Thickness=w or 2},o)
end
function H.label(p,t,size,color,pos,sz)
if type(t)=='string' then
    t=t:gsub('🎀','♡'):gsub('✧','*'):gsub('✦','*')
        :gsub('✿','*'):gsub('❣','♡'):gsub('⋆','*')
end
return H.new("TextLabel",{BackgroundTransparency=1,Text=t,
TextColor3=color,TextSize=size,Font=Enum.Font.GothamBold,
TextXAlignment=Enum.TextXAlignment.Center,Position=pos,Size=sz},p)
end
function H.makeBow(parent,x,y,z)
    local holder=H.new('Frame',{
        Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(36,30),
        BackgroundTransparency=1,ZIndex=z or 12
    },parent)
    for _,spec in ipairs({{0,-27},{18,27}}) do
        local wing=H.new('Frame',{
            Position=UDim2.fromOffset(spec[1],4),Size=UDim2.fromOffset(20,19),
            Rotation=spec[2],BackgroundColor3=C.pink,
            BorderSizePixel=0,ZIndex=(z or 12)+1
        },holder)
        H.round(wing,8)
        H.new('UIStroke',{Color=C.white,Thickness=.75,Transparency=.25},wing)
    end
    for _,spec in ipairs({{10,-13},{19,13}}) do
        local tail=H.new('Frame',{
            Position=UDim2.fromOffset(spec[1],15),Size=UDim2.fromOffset(7,14),
            Rotation=spec[2],BackgroundColor3=C.hot,
            BorderSizePixel=0,ZIndex=z or 12
        },holder)
        H.round(tail,3)
    end
    local jewel=H.new('Frame',{
        Position=UDim2.fromOffset(14,10),Size=UDim2.fromOffset(9,9),
        BackgroundColor3=C.white,BorderSizePixel=0,ZIndex=(z or 12)+2
    },holder)
    H.round(jewel,6)
    return holder
end
function H.tween(o,props,duration)
local t=TS:Create(o,TweenInfo.new(duration or .2,
Enum.EasingStyle.Sine,Enum.EasingDirection.InOut),props)
t:Play()
return t
end
function H.contains(s,word)
return s:lower():find(word,1,true) ~= nil
end
function H.physical(o) return o:IsA("Model") or o:IsA("BasePart") end
function H.anyPart(o)
if o:IsA("BasePart") then return o end
if o:IsA("Model") then
return o.PrimaryPart or o:FindFirstChildWhichIsA("BasePart",true)
end
end
-- V48 small distance-fading objective captions.  One Billboard per active object.
function H.objectiveCaption(target,word,offset)
    local part=H.anyPart(target)
    if not part then return nil end
    local tag=H.new('BillboardGui',{
        Name='OronaSmall'..word:gsub('%s','')..'Label',Adornee=part,
        Size=UDim2.fromOffset(84,17),
        StudsOffsetWorldSpace=Vector3.new(0,offset or 1.45,0),
        AlwaysOnTop=true,LightInfluence=0,MaxDistance=0,Enabled=true
    },PG)
    local txt=H.new('TextLabel',{
        Size=UDim2.fromScale(1,1),BackgroundTransparency=1,
        Text=word,TextSize=10,Font=Enum.Font.GothamSemibold,
        TextColor3=Color3.fromRGB(255,208,233),
        TextStrokeColor3=Color3.fromRGB(98,31,70),TextStrokeTransparency=.28,
        TextXAlignment=Enum.TextXAlignment.Center,TextYAlignment=Enum.TextYAlignment.Center
    },tag)
    return tag
end
