local root = H.new("Frame",{BackgroundTransparency=1,
Position=pos,Size=UDim2.fromOffset(size,size)},parent)
local fur = evil and C.black or C.white
local eyeColor = evil and C.red or C.black
for _,x in ipairs({.12,.62}) do
