H.new("Frame",{Size=UDim2.fromScale(.17,.017),
Position=UDim2.fromScale(side==-1 and .015 or .815,
.47+(i-2)*.11),Rotation=(i-2)*side*12,
BackgroundColor3=eyeColor,BorderSizePixel=0},face)
end
end
local bow=H.new("Frame",{Size=UDim2.fromScale(.4,.28),
Position=UDim2.fromScale(.63,.08),BackgroundTransparency=1},root)
for _,x in ipairs({0,.48}) do
