    H.label(face,mood=='down' and '︵' or '﹏',size*.21,C.dark,
        UDim2.fromScale(.29,.67),UDim2.fromScale(.42,.26))
    if mood=='down' then
        for _,x in ipairs({.28,.73}) do
            local tear=H.new('Frame',{
                BackgroundColor3=Color3.fromRGB(104,194,249),
