        H.label(root,'💧',size*.22,C.white,
            UDim2.fromScale(.03,.65),UDim2.fromScale(.30,.30))
    end
end
if blink and (evil or not mood or mood=='normal') then
task.spawn(function()
while not unloaded and root.Parent do
task.wait(RNG:NextNumber(2.5,5))
if unloaded or not root.Parent then break end
for i,e in ipairs(eyes) do
e.Size=UDim2.fromScale(.075,.025)
e.Position=UDim2.fromScale(i==1 and .27 or .70,.54)
end
task.wait(.14)
