-- Do not render unassigned pooled highlights. Some graphics setups
-- briefly draw a nil-Adornee Highlight against unintended geometry.
function H.addHighlight(target,fill,edge)
    local h=Instance.new("Highlight")
    h.Name="OronaESP"
    h.Enabled=false
    h.Adornee=target
    h.FillColor=fill
    h.OutlineColor=edge
    h.FillTransparency=.58
    h.OutlineTransparency=0
    h.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
    -- Player highlights should be parented to their character so swapping
    -- CurrentCamera cannot destroy them. All other objectives live in Workspace.
    local owner=target and target:IsA('Model')
        and Players:GetPlayerFromCharacter(target)
    h.Parent=owner and target or workspace
    if target then h.Enabled=true end
    return h
end

-- Reject anything connected to a character, camera, or moving physics
-- object. These transient parts can sweep across the center of view.
function H.safeObjectiveTarget(root,target,kind)
    if not root or not target or not root:IsDescendantOf(workspace)
        or not target:IsDescendantOf(workspace) then return false end
    local camera=workspace.CurrentCamera
    if camera and (root:IsDescendantOf(camera)
        or target:IsDescendantOf(camera)) then return false end
    -- Cache the character list briefly; hundreds of objectives can be
    -- checked together during a refresh but players rarely respawn mid-pass.
    local now=os.clock()
    if not H.characterCache or now-(H.characterCacheAt or 0)>.75 then
        H.characterCache={}
        for _,p in ipairs(Players:GetPlayers()) do
            if p.Character then H.characterCache[#H.characterCache+1]=p.Character end
        end
        H.characterCacheAt=now
    end
    for _,char in ipairs(H.characterCache) do
        if root:IsDescendantOf(char) or target:IsDescendantOf(char) then
            return false
        end
    end
    local base=H.anyPart(target)
    if not base then return false end
    if not base.Anchored and kind~='Pallets'
        and not (kind=='Generators' and H.generatorKnownMap(root)) then
        local speed=base.AssemblyLinearVelocity.Magnitude
        local maximum=(kind=="Traps" and 9 or 16)
        if speed>maximum then return false end
    end
    return true
end
function H.isKiller(p)
if p.Team and H.contains(p.Team.Name,"killer") then return true end
local role=p:GetAttribute("Role")
return type(role)=="string" and role:lower()=="killer"
or p:GetAttribute("IsKiller")==true
end
-- Prefer explicit game state, then humanoid health. A zero-health
-- Humanoid is treated as downed, but games with separate downed
-- attributes should use those for a reliable distinction.
function H.survivorMood(p,char)
    if H.isKiller(p) then return 'normal' end
    for _,o in ipairs({p,char}) do
        for _,attr in ipairs({'Downed','IsDowned','Knocked','KnockedDown',
            'Incapacitated','InDyingState','IsDying','Crawling'}) do
            if o:GetAttribute(attr)==true then return 'down' end
        end
        local status=o:GetAttribute('HealthState') or o:GetAttribute('State')
        if type(status)=='string' then
            status=status:lower()
            if status:find('down',1,true) or status:find('dying',1,true)
                or status:find('crawl',1,true) or status:find('knock',1,true) then
                return 'down'
            end
            if status:find('injur',1,true) or status:find('wound',1,true) then
                return 'injured'
            end
        end
    end
    local hum=char:FindFirstChildOfClass('Humanoid')
    if hum then
        if hum.Health<=0 then return 'down' end
        if hum.Health<hum.MaxHealth then return 'injured' end
    end
    for _,o in ipairs({char,p}) do
        local h=o:GetAttribute('Health') or o:GetAttribute('CurrentHealth')
        local mh=o:GetAttribute('MaxHealth') or o:GetAttribute('MaximumHealth')
        if type(h)=='number' then
            if h<=0 then return 'down' end
            if type(mh)=='number' and mh>0 and h<mh then return 'injured' end
        end
        if o:GetAttribute('Injured')==true or o:GetAttribute('IsInjured')==true then
            return 'injured'
        end
    end
    return 'normal'
end
function H.clearPlayer(p)
local r=playerFX[p]
if r then
if r.aura then r.aura:Destroy() end
if r.tag then r.tag:Destroy() end
playerFX[p]=nil
end
end
function H.updatePlayer(p)
if unloaded or p==Me or S.Streamer then return end
if not H.vaultRoundActive() then
    H.clearPlayer(p)
    return
end
local char=p.Character
local evil=H.isKiller(p)
local mood=(not evil and char) and H.survivorMood(p,char) or 'normal'
local record=playerFX[p]
if record and (record.char~=char or record.evil~=evil) then
H.clearPlayer(p)
record=nil
end
if not char then return end
if record and record.mood~=mood and record.tag then
    record.tag:Destroy()
    record.tag=nil
end
if record then record.mood=mood end
if not S.Players and not S.Kitties then
if record then H.clearPlayer(p) end
return
end
if not record then
record={char=char,evil=evil,mood=mood}
playerFX[p]=record
end
-- Repair character highlights removed by camera/map changes, engine
-- highlight recycling, or external character cleanup. Do NOT require
-- toggling the UI to rebuild them.
if S.Players and record.aura and (
    not record.aura.Parent or record.aura.Adornee~=char
    or not record.aura:IsDescendantOf(game)) then
    pcall(function() record.aura:Destroy() end)
    record.aura=nil
end
if S.Players and not record.aura then
    record.aura=H.addHighlight(char,
        evil and C.killerPink or C.light,
        evil and C.killerPink or C.lightEdge)
elseif S.Players and record.aura then
    -- Enabled can be changed when graphics / camera state changes.
    record.aura.Enabled=true
    if record.aura.Parent~=char then record.aura.Parent=char end
elseif not S.Players and record.aura then
record.aura:Destroy()
record.aura=nil
end
if S.Kitties and not record.tag then
local head=char:FindFirstChild('Head')
if head then
local tag=H.new('BillboardGui',{
Name='OronaKittyIcon',Adornee=head,
Size=UDim2.fromOffset(58,58),
StudsOffsetWorldSpace=Vector3.new(0,2.65,0),
AlwaysOnTop=true,MaxDistance=850,LightInfluence=0,
Enabled=true},head)
record.tag=tag
local holder=H.new('Frame',{
Size=UDim2.fromScale(1,1),
BackgroundTransparency=1},tag)
H.kitty(holder,36,UDim2.new(.5,-18,.5,-18),evil,true,mood)
for i,sym in ipairs({'✦','✧','♡'}) do
H.label(holder,sym,11,evil and C.red or C.hot,
UDim2.fromScale(i%2==0 and .8 or .03,
i==3 and .73 or .1),UDim2.fromOffset(14,14))
end
end
elseif not S.Kitties and record.tag then
record.tag:Destroy()
record.tag=nil
end
end
-- V77: Zombies and servants belong to the Player ESP switch. The NPC index
-- runs once when enabled, is time-budgeted, and new models arrive via events.
-- It never touches Roblox player models or scenery without a Humanoid.
H.npcFX = {}
H.npcCandidates = setmetatable({}, {__mode='k'})
H.npcScanToken = 0
H.npcLimit = 42 -- preserve Roblox Highlight slots for pallets and objectives
H.npcLastIndexAt = 0
function H.npcClass(model)
    if not model or not model:IsA('Model')
        or not model:IsDescendantOf(workspace)
        or Players:GetPlayerFromCharacter(model)
        or model==Me.Character then return nil end
    local n=model.Name:lower()
    local role=model:GetAttribute('Role') or model:GetAttribute('NPCType')
        or model:GetAttribute('Type') or model:GetAttribute('Faction')
    if type(role)=='string' then role=role:lower() else role='' end
    local par=model.Parent and model.Parent.Name:lower() or ''
    local class=nil
    if n:find('zombie',1,true) or role:find('zombie',1,true)
        or CollectionService:HasTag(model,'Zombie')
        or par=='zombies' or par=='zombie' then class='zombie'
    elseif n:find('servant',1,true) or role:find('servant',1,true)
        or CollectionService:HasTag(model,'Servant')
        or par=='servants' or par=='servant' then class='servant' end
    if not class then return nil end
    local hum=model:FindFirstChildOfClass('Humanoid')
    if not hum or hum.Health<=0 then return nil end
    return class
end
function H.clearNPC(model)
    local effect=H.npcFX[model]
    if effect then effect:Destroy();H.npcFX[model]=nil end
end
function H.clearAllNPCs()
    for model in pairs(H.npcFX) do H.clearNPC(model) end
    H.npcCandidates=setmetatable({}, {__mode='k'})
    H.npcScanToken+=1
end
function H.considerNPC(model)
    if unloaded or S.Streamer or not S.Players or not H.vaultRoundActive() then return end
    local class=H.npcClass(model)
    if class then
        H.npcCandidates[model]=class
        if not H.npcRefreshQueued then
            H.npcRefreshQueued=true
            task.defer(function()
                H.npcRefreshQueued=false
                if not unloaded then H.updateNPCs() end
            end)
        end
    end
end
function H.updateNPCs()
    if unloaded or S.Streamer or not S.Players or not H.vaultRoundActive() then
        for model in pairs(H.npcFX) do H.clearNPC(model) end
        return
    end
    local active=0
    for model,effect in pairs(H.npcFX) do
        local class=H.npcClass(model)
        if not class or not effect.Parent or effect.Adornee~=model then
            H.clearNPC(model)
            if not class then H.npcCandidates[model]=nil end
        else
            active+=1
            effect.Enabled=true
        end
    end
    for model,class in pairs(H.npcCandidates) do
        if active>=H.npcLimit then break end
        if not H.npcFX[model] then
            class=H.npcClass(model)
            if class then
                local color=class=='zombie' and C.killerPink or C.light
                H.npcFX[model]=H.addHighlight(model,color,
                    class=='zombie' and C.hot or C.lightEdge)
                H.npcFX[model].Name='OronaPlayerNPCESP'
                active+=1
            else
                H.npcCandidates[model]=nil
            end
        end
    end
end
function H.indexNPCs()
    if unloaded or S.Streamer or not S.Players or not H.vaultRoundActive() then return end
    H.npcScanToken+=1
    local token=H.npcScanToken
    H.npcLastIndexAt=os.clock()
    task.spawn(function()
        local queue={workspace}
        local head=1
        while head<=#queue and not unloaded and S.Players
            and token==H.npcScanToken do
            local deadline=os.clock()+.0018
            local count=0
            while head<=#queue and count<170 and os.clock()<deadline do
                local node=queue[head]
                queue[head]=false
                head+=1
                count+=1
                local isPlayerModel=node:IsA('Model')
                    and Players:GetPlayerFromCharacter(node)~=nil
                if not isPlayerModel then
                    if node:IsA('Model') then H.considerNPC(node) end
                    for _,child in ipairs(node:GetChildren()) do
                        if child:IsA('Folder') or child:IsA('Model') then
                            queue[#queue+1]=child
                        end
                    end
                end
            end
            task.wait()
        end
        if token==H.npcScanToken then H.updateNPCs() end
    end)
end
function H.onPlayerESPToggled()
    if S.Players then H.indexNPCs() else H.clearAllNPCs() end
end
function H.namedRoot(obj,word)
local result=nil
local cur=obj
while cur and cur~=workspace do
if H.physical(cur) and H.contains(cur.Name,word) then result=cur end
cur=cur.Parent
end
return result
end
-- ====== V40: IDENTIFY THE ACTUAL OBJECT, NOT A DECORATIVE NAMESAKE ======
function H.excludedObjectiveName(name)
    local n=name:lower()
    for _,word in ipairs({'decor','display','fake','dummy','prop','preview','sample',
        'broken','destroyed','disabled','spawnpoint','placeholder'}) do
        if n:find(word,1,true) then return true end
    end
    return false
end

function H.isHookName(name)
    local n=name:lower():gsub('^%s+',''):gsub('%s+$','')
    if H.excludedObjectiveName(n) then return false end
    -- "Hook" is the usual gameplay model. Also support numbered hook
    -- variants, but not "HookDecoration", "HookChain", "FishHook" etc.
    return n=='hook' or n=='meathook' or n=='sacrificehook'
        or n:match('^hook[%s_%-%d]+$')~=nil
end

function H.hookRoot(obj)
    local partCandidate=nil
    local cur=obj
    while cur and cur~=workspace do
        if cur:IsA('Model') and H.isHookName(cur.Name) and H.anyPart(cur) then
            return cur -- Nearest hook model, NOT the entire Hooks folder.
        elseif cur:IsA('BasePart') and H.isHookName(cur.Name) and not partCandidate then
            partCandidate=cur
        end
        cur=cur.Parent
    end
    return partCandidate
end

-- V58: directly match the active map hierarchy seen in Studio.
-- V57 required an absent "defaultMaterial" part, so real Generator models
-- under newGenerators were silently rejected despite having GeneratorBody.
-- V65: the screenshots show both Map.newGenerators.Generator and
-- Map.resources.Generators.Generator. Neither requires defaultMaterial,
-- and the grouping can be a Model OR Folder.
function H.generatorKnownMap(root)
    if not root or not root:IsA('Model') or not H.anyPart(root) then return false end
    local map=workspace:FindFirstChild('Map')
    if not map or not root:IsDescendantOf(map) then return false end
    local parent=root.Parent
    if not parent or (parent.Name~='newGenerators' and parent.Name~='Generators') then
        return false
    end
    local resources=map:FindFirstChild('resources')
    if parent.Parent~=map and (not resources or parent.Parent~=resources) then
        return false
    end
    local name=root.Name:lower()
    if name~='generator' and not name:match('^generator[%s_%-%d]+$') then return false end
    -- Signature parts in both map variants: GeneratorBody, Machines, RootPart, HitBox.
    -- A known Generator model is valid even if one of these is streamed in late.
    return true
end

function H.isGenerator(o)
    if not o:IsA('Model') then return false end
    local n=o.Name:lower()
    if n=='generators' or n=='generatorpoints' or H.excludedObjectiveName(n) then
        return false
    end
    return H.generatorKnownMap(o) or H.contains(n,'generator') or n=='gen' or
        n:match('^gen[%d_%-]')~=nil or
        o:GetAttribute('RepairProgress')~=nil or
        o:GetAttribute('PlayersRepairingCount')~=nil
end

function H.generatorRoot(o)
    local cur=o
    while cur and cur~=workspace do
        if H.isGenerator(cur) and H.anyPart(cur) then
            return cur -- Prefer the closest named generator over a map grouping.
        end
        cur=cur.Parent
    end
    return nil
end

-- V42: actual map models can have suffixes such as Pallet_01,
-- PalletBlue, StandingPallet, etc. Older patterns missed those entirely.
-- Reject clearly non-gameplay objects and the explicitly unwanted Palletwrong.
-- Some VD maps contain models with the pallet word in the *middle* of
-- the name (e.g. WoodenPallet). Public VD ESPs scan any Model whose name
-- includes "pallet". Keep the obvious scenery variants excluded.
function H.palletModelName(name)
    local n=name:lower():gsub('^%s+',''):gsub('%s+$','')
    if not n:find('pallet',1,true) then return false end
    if n=='pallets' or n=='palletspawns' or n=='palletwrong' then return false end
    for _,bad in ipairs({'palletwrong','decor','display','fake','broken',
        'destroy','placeholder','preview','sample',
        'spawn','dummy','fragment','debris','particle','piece',
        'trigger','indicator','marker','effect','stack','pile','scrap',
        'loose','unused','unusable','prop','scenery',
        'junk','shelf','static'}) do
        if n:find(bad,1,true) then return false end
    end
    return true
end

-- Native prompts are positive evidence when map parts aren't consistently named.
function H.palletPromptActive(root)
    if not root then return false end
    for _,obj in ipairs(root:GetDescendants()) do
        if obj:IsA('ProximityPrompt') and obj.Enabled then
            local txt=(obj.Name..' '..obj.ActionText..' '..obj.ObjectText):lower()
            local hasPallet=txt:find('pallet',1,true)
                or txt:find('drop',1,true) or txt:find('throw',1,true)
                or txt:find('pull down',1,true)
            local bad=txt:find('break',1,true) or txt:find('destroy',1,true)
                or txt:find('reset',1,true) or txt:find('repair',1,true)
            if hasPallet and not bad then return true end
        end
    end
    return false
end

local palletPromptRoots={}
function H.mapPalletRoot(obj)
    local map=workspace:FindFirstChild('Map')
    if not map or not obj or not obj:IsDescendantOf(map) then return nil end
    local resources=map:FindFirstChild('resources')
    local folders={map:FindFirstChild('Pallets') or map:FindFirstChild('pallets')}
    if resources then folders[#folders+1]=resources:FindFirstChild('Pallets') or resources:FindFirstChild('pallets') end
    for _,folder in ipairs(folders) do
        if folder and obj:IsDescendantOf(folder) then
            -- In some maps each upright pallet is nested below a set/area.
            -- Prefer a real named model over an enclosing grouping model.
            local direct=obj
            local named=nil
            while direct and direct~=folder do
                if direct:IsA('Model') and H.anyPart(direct) then
                    -- A prefab with an Intact child is the actual playable
                    -- assembly, even when nested under a map decoration set.
                    if direct:FindFirstChild('Intact') then return direct end
                    if not named and H.palletModelName(direct.Name) then
                        named=direct
                    end
                end
                direct=direct.Parent
            end
            if named then return named end
            local cur=obj
            while cur and cur~=folder do
                if cur.Parent==folder and H.physical(cur) and H.anyPart(cur) then
                    local n=cur.Name:lower()
                    if not H.excludedObjectiveName(n)
                        and not n:find('palletwrong',1,true)
                        and not n:find('debris',1,true)
                        and not n:find('scrap',1,true)
                        and not n:find('spawn',1,true)
                        and not n:find('trigger',1,true)
                        and not n:find('marker',1,true)
                        and not n:find('pile',1,true) then
                        return cur
                    end
                end
                cur=cur.Parent
            end
        end
    end
    return nil
end
function H.getPalletModel(obj)
    local folderRoot=H.mapPalletRoot(obj)
    if folderRoot then return folderRoot end
    local cur=obj
    local nearest=nil
    local preferredAssembly=nil
    local partCandidate=nil
    while cur and cur~=workspace do
        local n=cur.Name:lower()
        if cur:IsA('Model') and n:find('pallet',1,true) then
            if H.palletModelName(cur.Name) and H.anyPart(cur) then
                nearest=nearest or cur
                -- Prefer the gameplay assembly (NewPallet, Pallet, etc.),
                -- not an inner cosmetic/standing submodel with a similar name.
                for _,branchName in ipairs({'Intact','Standing','Upright',
                    'Undropped','Unfallen','PalletStanding','Dropped'}) do
                    if cur:FindFirstChild(branchName) then
                        preferredAssembly=cur
                        break
                    end
                end
            elseif (n=='palletwrong'  or n:find('palletwrong',1,true))
                and H.anyPart(cur) and H.palletPromptActive(cur) then
                -- Palletwrong is usually scenery, but a REAL enabled drop
                -- prompt can take precedence over that misleading name.
                nearest=nearest or cur
                palletPromptRoots[cur]=true
            elseif n:find('wrong',1,true) or n:find('fake',1,true)
                or n:find('decor',1,true) or n:find('broken',1,true) then
                -- Don't allow a valid-looking child to escape a fake parent.
                return nil
            end
        elseif cur:IsA('BasePart') and H.palletModelName(cur.Name) then
            partCandidate=partCandidate or cur
        end
        cur=cur.Parent
    end
    if preferredAssembly then return preferredAssembly end
    if nearest then return nearest end
    -- A map variant has named upper models but the standing prefab can be
    -- called "Barricade" and identified by Intact + a pallet/state parent.
    local ancestor=obj
    while ancestor and ancestor~=workspace do
        if ancestor:IsA('Model') and ancestor:FindFirstChild('Intact')
            and H.anyPart(ancestor) then
            local parent=ancestor.Parent
            local par=parent and parent.Name:lower() or ''
            local attrs=ancestor:GetAttribute('PalletState')~=nil
                or ancestor:GetAttribute('CanDrop')~=nil
                or ancestor:GetAttribute('IsPallet')==true
            if attrs or par:find('pallet',1,true) then
                return ancestor
            end
        end
        ancestor=ancestor.Parent
    end
    if partCandidate and (H.palletPromptActive(partCandidate)
        or partCandidate:GetAttribute('PalletState')~=nil
        or partCandidate:GetAttribute('CanDrop')~=nil) then
        palletPromptRoots[partCandidate]=true
        return partCandidate
    end
    return nil
end

-- V57: scene props can be named Pallet too. Prefer playable state,
-- explicit interactive metadata, or an upright gameplay-sized Pallet model.
-- Keep a remembered playable pallet when it falls over; remove only on break.
H.palletEverValid=setmetatable({}, {__mode='k'})
H.palletEvidenceCache=setmetatable({}, {__mode='k'})
function H.palletGameplayEvidence(root)
    if not root or not H.anyPart(root) then return false end
    if H.palletEverValid[root] then return true end
    local now=os.clock()
    local cached=H.palletEvidenceCache[root]
    -- Negative evidence expires quickly: StreamingEnabled may add a standing
    -- branch after the initial map scan without recreating the root model.
    if cached and now-cached.at<(cached.valid and 4 or .7) then return cached.valid end
    local valid=H.hasObjectiveTag and H.hasObjectiveTag(root,'Pallets') or false
    -- A direct model inside Map.Pallets is authoritative map grouping,
    -- unlike incidental props called "Pallet" elsewhere.
    if not valid and H.mapPalletRoot(root)==root then valid=true end
    -- Intact at spawn is positive evidence (not the Broken dormant variant).
    -- This helps maps whose standing pieces use a differently named container.
    if not valid and root:IsA('Model') and (
        root:FindFirstChild('Intact') or root:FindFirstChild('Standing')
        or root:FindFirstChild('Upright') or root:FindFirstChild('Undropped')
        or root:FindFirstChild('Unfallen') or root:FindFirstChild('PalletStanding'))
        and (H.palletModelName(root.Name)
            or (root.Parent and root.Parent.Name:lower():find('pallet',1,true))) then
        valid=true
    end
    if not valid then
        for _,key in ipairs({'CanDrop','CanBeDropped','Droppable','IsPallet',
            'PalletState','CanVaultPallet','PalletUsable','CanPullDown',
            'Standing','IsStanding','IsDropped','Dropped','Used'}) do
            local v=root:GetAttribute(key)
            if v~=nil and v~=false then valid=true;break end
        end
    end
    if not valid then valid=H.palletPromptActive(root) end
    if not valid and root:IsA('Model') then
        -- Only names known to represent playable pallets qualify for the
        -- geometry fallback; a WoodenPallet or pallet pile never qualifies.
        local n=root.Name:lower():gsub('[%s_%-]','')
        local known=n=='pallet' or n:match('^pallet[%w]*$')~=nil
            or n:match('^newpallet[%w]*$')~=nil
            or n:match('^standingpallet%d*$')~=nil
            or n:match('^droppablepallet%d*$')~=nil
        if known then
            local parent=root.Parent
            local scenery=false
            while parent and parent~=workspace do
                local pn=parent.Name:lower()
                for _,bad in ipairs({'decor','scenery','prop','junk','pile',
                    'unused','lobby','display','template','storage'}) do
                    if pn:find(bad,1,true) then scenery=true;break end
                end
                if scenery then break end
                parent=parent.Parent
            end
            if not scenery then
                local ok,_,boxSize=pcall(function()
                    local cf,size=root:GetBoundingBox()
                    return cf,size
                end)
                -- A standing usable pallet is visibly tall. This minimum
                -- height is intentionally permissive across map variants.
                if ok and boxSize and boxSize.Y>=1.15
                    and math.max(boxSize.X,boxSize.Z)>=1.2 then valid=true end
            end
        end
    end
    H.palletEvidenceCache[root]={valid=not not valid,at=now}
    if valid then H.palletEverValid[root]=true end
    return valid
end

-- V77: Certain maps store upright geometry in Standing/Upright instead of
-- Intact. Test active visual branches, never the dormant Broken branch.
function H.palletLiveTarget(root)
    if not root or not root:IsA('Model') then return root end
    -- Some map variants put the *standing* geometry outside Intact. Looking
    -- at Intact first made those maps show nothing until the pallet dropped.
    local function visible(group)
        if group:IsA('BasePart') then
            return group.Transparency<.98 and group.Size.Magnitude>.18
        end
        for _,part in ipairs(group:GetDescendants()) do
            if part:IsA('BasePart') and part.Transparency<.98
                and part.Size.Magnitude>.18 then return true end
        end
        return false
    end
    local standingNames={
        standing=true,upright=true,undropped=true,unfallen=true,
        palletstanding=true,standingpallet=true,newpallet=true,
        ready=true,unbroken=true,unused=true
    }
    local intact=nil
    for _,branch in ipairs(root:GetChildren()) do
        local key=branch.Name:lower():gsub('[%s_%-]','')
        if (branch:IsA('Model') or branch:IsA('BasePart'))
            and standingNames[key] and visible(branch) then
            return branch
        end
        if key=='intact' then intact=branch end
    end
    -- Don't let the dropped Intact template override actual upright planks.
    -- A valid root with active direct geometry is outlined as one assembly.
    local directVisible=false
    for _,child in ipairs(root:GetChildren()) do
        if child:IsA('BasePart') then
            local name=child.Name:lower()
            if child.Transparency<.98 and child.Size.Magnitude>.18
                and not name:find('trigger',1,true)
                and not name:find('hitbox',1,true)
                and not name:find('collision',1,true) then
                directVisible=true
                break
            end
        end
    end
    if directVisible then return root end
    if intact and (intact:IsA('Model') or intact:IsA('BasePart'))
        and visible(intact) then return intact end
    -- Other prefabs store standing planks in unnamed nested models.
    -- Ignore dormant Broken templates, decorative parts and hitboxes.
    for _,part in ipairs(root:GetDescendants()) do
        if part:IsA('BasePart') and part.Transparency<.98
            and part.Size.Magnitude>.18 then
            local cur=part
            local excluded=false
            while cur and cur~=root do
                local name=cur.Name:lower()
                if name=='broken' or name=='destroyed' or name=='debris'
                    or name:find('hitbox',1,true)
                    or name:find('trigger',1,true)
                    or name:find('collision',1,true) then
                    excluded=true
                    break
                end
                cur=cur.Parent
            end
            if not excluded then return root end
        end
    end
    return nil
end
-- Pallets are useful ESP targets while upright or after dropping, but never
-- once destroyed. Invisible dormant Broken prefab is not a break indication.
function H.palletDestroyed(inst)
    if not inst or not inst.Parent then return true end
    local map=workspace:FindFirstChild('Map')
    if not map or not inst:IsDescendantOf(map) then return true end
    local flags={'Destroyed','IsDestroyed','Broken','IsBroken','Shattered',
        'IsShattered','Dismantled','Smashed','Removed','IsRemoved'}
    local function explicitBreak(obj)
        if not obj then return false end
        for _,flag in ipairs(flags) do
            if obj:GetAttribute(flag)==true then return true end
            local child=obj:FindFirstChild(flag)
            if child and child:IsA('BoolValue') and child.Value then return true end
        end
        local status=obj:GetAttribute('PalletState')
            or obj:GetAttribute('ObjectiveState') or obj:GetAttribute('State')
        if type(status)=='string' then
            local t=status:lower()
            for _,word in ipairs({'broken','destroy','shatter','removed','smashed'}) do
                if t:find(word,1,true) then return true end
            end
        end
        return false
    end
    if explicitBreak(inst) or (inst:IsA('Model') and explicitBreak(inst.PrimaryPart)) then
        return true
    end
    if not inst:IsA('Model') then return false end
    -- On a streaming map, Intact may initially be invisible even though the
    -- active Standing model is visible. Evaluate all playable visual branches.
    return H.palletLiveTarget(inst)==nil
end

function H.trackablePallet(o)
    if not o or not H.physical(o)
        or not (H.palletModelName(o.Name) or palletPromptRoots[o]
            or H.mapPalletRoot(o)==o
            or (o:IsA('Model') and o:FindFirstChild('Intact')
                and o.Parent and o.Parent.Name:lower():find('pallet',1,true)))
        or not H.anyPart(o) then return false end
    if H.palletDestroyed(o) then return false end
    if o:IsA('Model') and o.PrimaryPart and H.palletDestroyed(o.PrimaryPart) then
        return false
    end
    return H.palletGameplayEvidence(o)
end
-- ====== V41: HYBRID OBJECTIVE VALIDATION ======
-- Some Violence District maps use a custom player UI (NOT a native
-- ProximityPrompt), so V40 prompt-only validation falsely rejected real
-- hooks/pallets/gens. Prefer native prompt / tag evidence when available,
-- then use game-specific model + state signatures as a fallback.
-- We never increase prompt activation distance or modify game objects.
local OBJECTIVE_TAGS={
    Hooks={'UsableHook','SacrificeHook','MeatHook','HookInteractable'},
    Generators={'RepairableGenerator','ActiveGenerator','UsableGenerator'},
    Pallets={'UsablePallet','StandingPallet','DroppablePallet'}
}
function H.hasObjectiveTag(root,kind)
    local list=OBJECTIVE_TAGS[kind]
    if not list then return false end
    for _,tag in ipairs(list) do
        if CollectionService:HasTag(root,tag) then return true end
    end
    return false
end

function H.objectiveDisabled(root,kind)
    if not root or not root:IsDescendantOf(workspace) then return true end
    local targets={root}
    if root:IsA('Model') and root.PrimaryPart then
        targets[#targets+1]=root.PrimaryPart
    end
    for _,o in ipairs(targets) do
        -- A dropped pallet may be marked Disabled/Used because the survivor
        -- can no longer drop it.  The KILLER can still break it; keep its ESP.
        if kind=='Pallets' then
            if H.palletDestroyed(o) then return true end
        else
            for _,a in ipairs({'Destroyed','IsDestroyed','IsBroken','Broken',
                'Disabled','IsDisabled'}) do
                if o:GetAttribute(a)==true then return true end
            end
            for _,a in ipairs({'Usable','IsUsable'}) do
                if o:GetAttribute(a)==false then return true end
            end
            if kind=='Hooks' then
                for _,a in ipairs({'Occupied','IsOccupied','HookOccupied',
                    'Sabotaged','IsSabotaged'}) do
                    if o:GetAttribute(a)==true then return true end
                end
            elseif kind=='Generators' then
                for _,a in ipairs({'Completed','IsCompleted','Repaired',
                    'IsRepaired','IsFinished'}) do
                    if o:GetAttribute(a)==true then return true end
                end
                local progress=o:GetAttribute('RepairProgress')
                if type(progress)=='number' and progress>=100 then return true end
            end
            local state=o:GetAttribute('State') or o:GetAttribute('ObjectiveState')
            if type(state)=='string' then
                local v=state:lower()
                for _,bad in ipairs({'destroy','broken','disabled','removed'}) do
                    if v:find(bad,1,true) then return true end
                end
                if kind=='Generators' then
                    if v:find('complet',1,true) or v:find('repairdone',1,true)
                        or v:find('finished',1,true) then return true end
                elseif kind=='Hooks' then
                    if v:find('occupied',1,true) or v:find('sabotag',1,true) then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function H.promptLooksRelevant(prompt,kind)
    local action=(prompt.ActionText or ''):lower()
    local object=(prompt.ObjectText or ''):lower()
    local name=prompt.Name:lower()
    local s=action..' '..object..' '..name
    for _,bad in ipairs({'vault','window','open door','close door',
        'search','pickup','pick up','loot','collect','exit gate',
        'inspect','repair hook','unhook','rescue','save survivor',
        'break pallet','destroy pallet','reset pallet','lift pallet'}) do
        if s:find(bad,1,true) then return false end
    end
    local hasHook=s:find('hook',1,true) or s:find('sacrific',1,true)
        or s:find('hang survivor',1,true)
    local hasGen=s:find('generator',1,true) or s:find('repair',1,true)
        or s:find('gen ',1,true)
    local hasPallet=s:find('pallet',1,true) or s:find('drop',1,true)
        or s:find('throw',1,true)
    if kind=='Hooks' then
        return not (hasGen or hasPallet) or hasHook
    elseif kind=='Generators' then
        return not (hasHook or hasPallet) or hasGen
    elseif kind=='Pallets' then
        return not (hasHook or hasGen) or hasPallet
    end
    return false
end

function H.interactPrompt(root,kind)
    if not root or not H.physical(root) or H.objectiveDisabled(root,kind) then
        return nil,false
    end
    local hasRelevant=false
    for _,desc in ipairs(root:GetDescendants()) do
        if desc:IsA('ProximityPrompt') and H.promptLooksRelevant(desc,kind) then
            hasRelevant=true
            if desc.Enabled then return desc,true end
        end
    end
    return nil,hasRelevant
end

function H.mapModelEvidence(root,kind)
    if not root or not H.anyPart(root) then return false end
    if kind=='Generators' then
        if not root:IsA('Model') or not H.isGenerator(root) then
            return false
        end
        if H.generatorKnownMap(root) then return true end
        -- Violence District exposes repair state on gameplay generators.
        -- Also support map versions with a defaultMaterial mesh but without
        -- a replicated progress attribute (legacy / streaming variants).
        local progress=root:GetAttribute('RepairProgress')
        if type(progress)=='number' then return progress<100 end
        if root:GetAttribute('PlayersRepairingCount')~=nil then return true end
        local name=root.Name:lower()
        local material=root:FindFirstChild('defaultMaterial',true)
        return (H.contains(name,'generator') or name=='gen')
            and material~=nil and H.physical(material)
    elseif kind=='Hooks' then
        -- The playable hook is normally a *Model* named Hook; decorative
        -- models often just contain "hook" somewhere in a part name.
        if not root:IsA('Model') or not H.isHookName(root.Name) then
            return false
        end
        return H.anyPart(root)~=nil
    elseif kind=='Pallets' then
        -- Actual map pallets are models, not arbitrary mesh parts named
        -- "pallet". Unusable variants (e.g. Palletwrong) are excluded by
        -- H.getPalletModel/H.palletModelName and state checks.
        return H.trackablePallet(root)
    end
    return false
end

function H.confirmedObjective(root,kind)
    if not root then return false end
    -- Known generator assemblies are authoritative. Generic Disabled/Usable
    -- attributes can describe the interaction, not the generator's existence.
    if kind=='Generators' and H.generatorKnownMap(root) then
        local progress=root:GetAttribute('RepairProgress')
        if type(progress)=='number' and progress>=100 then return false end
        for _,flag in ipairs({'Completed','IsCompleted','Repaired','IsRepaired','IsFinished'}) do
            if root:GetAttribute(flag)==true then return false end
        end
        return true
    end
    if H.objectiveDisabled(root,kind) then return false end
    if kind=='Pallets' then return H.trackablePallet(root) end
    if kind=='Generators' and not H.isGenerator(root) then return false end
    if kind=='Hooks' and not H.isHookName(root.Name) then return false end

    local prompt=H.interactPrompt(root,kind)
    if prompt then return true end
    if H.hasObjectiveTag(root,kind) then return true end
    -- A native prompt may be role-gated or range-gated, or there may be no
    -- native prompts at all. Never interpret prompt.Enabled=false by itself
    -- as evidence that the WORLD OBJECT has been consumed. State flags above
    -- reject objects confirmed to be spent; model signatures handle the rest.
    return H.mapModelEvidence(root,kind)
end

function H.inspectObjectivePrompt(prompt)
    if not prompt:IsA('ProximityPrompt') then return end
    H.sawNativePrompt=true
    local hook=H.hookRoot(prompt)
    if S.Hooks and hook then objectiveCandidates.Hooks[hook]=true end
    local gen=H.generatorRoot(prompt)
    if S.Generators and gen then objectiveCandidates.Generators[gen]=true end
    local pallet=H.getPalletModel(prompt)
    if S.Pallets and pallet then palletCandidates[pallet]=true end
end

-- V44: ESP highlights only, no overhead PALLET text or UI counters.
-- Maintain outlines while pallets are dropped; clear only on break/remove.
local function removePalletMarker(root)
    local h=palletHighlights[root]
    if h then h:Destroy();palletHighlights[root]=nil end
end
local function setPalletPoolVisible(visible)
    for root,highlight in pairs(palletHighlights) do
        if not root:IsDescendantOf(workspace) then
            removePalletMarker(root)
        else
            highlight.Enabled=visible
        end
    end
end

-- V63: real pallet-mesh outlines, not the BoxHandleAdornment added in V62.
-- Select the closest intact objects and reuse a model Highlight. Only the
-- playable Intact geometry is adorned; the dormant Broken variant is excluded.
local function updatePallets()
    if unloaded or S.Streamer or not S.Pallets or not H.vaultRoundActive() then
        setPalletPoolVisible(false)
        return
    end
    local map=workspace:FindFirstChild('Map')
    local cam=workspace.CurrentCamera
    local character=Me.Character
    local hrp=character and character:FindFirstChild('HumanoidRootPart')
    local pos=hrp and hrp.Position or (cam and cam.CFrame.Position)
    local eligible={}
    for root in pairs(palletCandidates) do
        if not map or not root:IsDescendantOf(map) then
            palletCandidates[root]=nil
            palletPromptRoots[root]=nil
            removePalletMarker(root)
        elseif H.trackablePallet(root) then
            local target=H.palletLiveTarget(root)
            local anchor=target and H.anyPart(target)
            -- Never highlight a broken pallet: state and visible Intact geometry
            -- are tested by trackablePallet/palletDestroyed before this point.
            if anchor then
                eligible[#eligible+1]={root=root,target=target,
                    distance=pos and (anchor.Position-pos).Magnitude or 0}
            end
        end
    end
    -- Stable order independent of distance; no near-object rotation.
    table.sort(eligible,function(a,b)
        local mapA=a.root:GetFullName()
        local mapB=b.root:GetFullName()
        if mapA==mapB then return a.root.Name<b.root.Name end
        return mapA<mapB
    end)
    -- Full-map, stable membership: never remove a pallet simply because the
    -- camera approaches a different object. Roblox supports up to 255
    -- Highlights; leave headroom for players, hooks, gens and other scripts.
    local otherCount=objectCount
    for _,record in pairs(playerFX) do
        if record.aura and record.aura.Parent and record.aura.Enabled then
            otherCount+=1
        end
    end
    -- Count zombie/servant Highlights in the same headroom calculation.
    for _,effect in pairs(H.npcFX) do
        if effect.Parent and effect.Enabled then otherCount+=1 end
    end
    local maxShown=math.min(MAX_VISIBLE_PALLETS,math.max(0,225-otherCount))
    local chosen={}
    for i=1,math.min(#eligible,maxShown) do
        local item=eligible[i]
        local root,target=item.root,item.target
        chosen[root]=true
        local effect=palletHighlights[root]
        if not effect or not effect.Parent or not effect:IsA('Highlight') then
            if effect then effect:Destroy() end
            effect=H.addHighlight(target,C.light,C.lightEdge)
            effect.Name='OronaPalletESP'
            effect.FillTransparency=.58
            effect.OutlineTransparency=0
            effect.Parent=workspace
            palletHighlights[root]=effect
        end
        if effect.Adornee~=target then effect.Adornee=target end
        effect.Enabled=true
    end
    local stale={}
    for root in pairs(palletHighlights) do
        if not chosen[root] then stale[#stale+1]=root end
    end
    for _,root in ipairs(stale) do removePalletMarker(root) end
    palletLastVisible=math.min(#eligible,maxShown)
end

-- A separate scan runs on toggle, and again after new map objects stream in.
local function discoverPallets()
    if not H.vaultRoundActive() then return end
    palletScanToken+=1
    palletLastScan=os.clock()
    -- Tagged objects can be ready immediately, even with StreamingEnabled.
    for _,tag in ipairs({'UsablePallet','StandingPallet','DroppablePallet'}) do
        for _,o in ipairs(CollectionService:GetTagged(tag)) do
            if o:IsDescendantOf(workspace) then
                local root=H.getPalletModel(o)
                if root then palletCandidates[root]=true end
            end
        end
    end
    -- The SHARED budgeted scanner handles all other model names. This avoids
    -- GetDescendants() + a second full traversal on every toggle.
    if H.scheduleFullScan then H.scheduleFullScan() end
    updatePallets()
end

-- ========= V45: VAULT ESP / REAL WINDOW ASSEMBLIES =========
-- A Vault HUD prompt can be custom UI, not a Workspace ProximityPrompt.
-- In VD, real vault openings often use Window assemblies with a Bottom
-- sill piece; prefer those structural roots instead of every decorative window.
function H.vaultName(name)
    local n=name:lower():gsub('^%s+',''):gsub('%s+$','')
    for _,bad in ipairs({'decor','decoration','display','fake','dummy','broken',
        'destroyed','particle','debris','effect','preview','thumbnail',
        'picture','texture','glass','glasspane','spawn','marker','indicator',
        'windowpane','windowglass','windowsilldecor','vaultdoor',
        'vaulted','windowframeprop'}) do
        if n:find(bad,1,true) then return false end
    end
    if n=='windows' or n=='vaults' or n=='windowspawns' or n=='vaultspawns' then
        return false
    end
    if n=='window' or n=='vault' or n=='vaultwindow'
        or n=='windowvault' or n=='vaultpoint' or n=='vaultspot'
        or n=='vaultablewindow' or n=='vaultable'
        or n=='vaulttrigger' or n=='vaultcollider' or n=='vaultzone'
        or n=='windowtrigger' or n=='windowhitbox'
        or n=='jumpwindow' or n=='vaultframe' then return true end
    if n:match('^window[%s_%-%(%)%d]+$')
        or n:match('^vault[%s_%-%(%)%d]+$')
        or n:match('^vaultwindow[%s_%-%(%)%d]+$') then return true end
    if n:find('window',1,true) and not n:find('windows',1,true) then
        return true
    end
    if n:find('vault',1,true) and not n:find('vaults',1,true) then
        return true
    end
    return false
end
function H.vaultPrompt(prompt)
    if not prompt or not prompt:IsA('ProximityPrompt') then return false end
    local text=(prompt.ActionText or '')..' '..(prompt.ObjectText or '')..' '..prompt.Name
    text=text:lower()
    return text:find('vault',1,true)~=nil
        or text:find('jump through',1,true)~=nil
        or text:find('leap',1,true)~=nil
        or text:find('climb through',1,true)~=nil
end
function H.vaultTagged(root)
    if not root then return false end
    for _,tag in ipairs({'Vault','Vaultable','VaultWindow','VaultPoint',
        'UsableVault','UsableWindow','VaultableWindow','VaultOpening',
        'VaultInteractable','WindowVault','CanVault','VDVault'}) do
        if CollectionService:HasTag(root,tag) then return true end
    end
    local interact=root:GetAttribute('InteractType') or root:GetAttribute('InteractionType')
    return root:GetAttribute('CanVault')==true
        or root:GetAttribute('Vaultable')==true
        or root:GetAttribute('IsVault')==true
        or root:GetAttribute('IsVaultable')==true
        or root:GetAttribute('CanUseVault')==true
        or (type(interact)=='string' and interact:lower()=='vault')
end
function H.vaultHasBottom(root)
    if not root:IsA('Model') then return false end
    local cache=H.vaultState.geometryCache
    local entry=cache[root]
    if entry and os.clock()-entry.at<(entry.ok and 40 or 6) then return entry.ok end
    -- Some map authors use Window/Bottom, others use a named window frame
    -- without Bottom. Support full opening outlines, but do NOT flag bare
    -- glass panes or generic large buildings as vaults.
    local bottom,upper,side,parts,transparent,openings=false,false,0,0,0,0
    local hasPrompt=false
    for _,node in ipairs(root:GetDescendants()) do
        if node:IsA('ProximityPrompt') and H.vaultPrompt(node) then
            hasPrompt=true
        elseif node:IsA('BasePart') then
            parts+=1
            local name=node.Name:lower():gsub('[%s_%-]','')
            if name=='bottom' or name=='bottompart' or name=='bottomframe'
                or name=='windowbottom' or name=='vaultbottom' or name=='sill'
                or name=='windowsill' or name=='vaulttrigger' or name=='vaultpart'
                or name=='vaultcollider' or name=='vaultzone' or name=='windowtrigger'
                or name=='windowhitbox' or name=='lowframe' then bottom=true end
            if name=='top' or name=='topframe' or name=='windowtop'
                or name=='upper' or name=='lintel' then upper=true end
            if name=='left' or name=='right' or name=='leftframe'
                or name=='rightframe' or name=='post' or name=='support'
                or name=='side' or name=='frame' or name=='border' then side+=1 end
            if name=='opening' or name=='entry' or name=='interact'
                or name=='trigger' or name=='collision' or name=='hitbox' then
                openings+=1
            end
            if node.Transparency>.85 and not node.CanCollide then
                transparent+=1
            end
        end
    end
    local accepted=hasPrompt or bottom or openings>0
        or (upper and side>0)
        or (side>=2 and parts>=3 and transparent>0)
    -- In places with single Window Model and two pieces, a marker/tag
    -- gives unambiguous proof. Preserve tagged objects regardless of shape.
    if H.vaultTagged(root) then accepted=true end
    cache[root]={ok=accepted,at=os.clock()}
    return accepted
end

-- Locate the nearest playable opening before any broad map/building model.
-- Vault assemblies have many naming variations across VD maps.
-- V60: Recognize the full active Window model by its interaction geometry.
-- VaultTrigger and inviswall are authoritative markers alongside Bottom.
function H.vaultBottomPart(root)
    if not root or not root:IsA('Model') then return nil end
    local bottom=root:FindFirstChild('Bottom') or root:FindFirstChild('Bottom',true)
    if bottom and bottom:IsA('BasePart') then return bottom end
    if bottom and bottom:IsA('Model') then return H.anyPart(bottom) end
    return nil
end

-- V73: the screenshot confirms Window > Bottom, VaultTrigger (x2), inviswall.
-- Use VaultTrigger/inviswall to VERIFY the opening but NEVER attach ESP to them.
-- The only rendered target is the exact Bottom part of that Window model.
function H.windowInteractionPart(root)
    if not root or not root:IsA('Model') then return nil end
    local bottom=H.vaultBottomPart(root)
    if not bottom then return nil end
    local trigger=root:FindFirstChild('VaultTrigger',true)
        or root:FindFirstChild('WindowTrigger',true)
    local wall=root:FindFirstChild('inviswall',true)
        or root:FindFirstChild('InvisWall',true)
    if trigger or wall or H.vaultTagged(root) then
        return bottom
    end
    -- Do not draw an ESP on an ordinary decorative window sill.
    return nil
end

function H.mapWindowRoot(obj)
    local map=workspace:FindFirstChild('Map')
    if not map or not obj or not obj:IsDescendantOf(map) then return nil end
    local resources=map:FindFirstChild('resources')
    local folders={}
    for _,container in ipairs({map,resources or map}) do
        if container then
            for _,name in ipairs({'Windows','Vaults'}) do
                local folder=container:FindFirstChild(name)
                if folder then folders[#folders+1]=folder end
            end
        end
    end
    for _,folder in ipairs(folders) do
        if folder and obj:IsDescendantOf(folder) then
            local cur=obj
            while cur and cur~=folder do
                if cur:IsA('Model') and cur.Parent==folder
                    and H.vaultName(cur.Name) and H.anyPart(cur)
                    and (H.windowInteractionPart(cur) or H.vaultTagged(cur)) then
                    return cur
                end
                cur=cur.Parent
            end
        end
    end
    return nil
end

function H.vaultRoot(obj)
    if not obj or not obj:IsDescendantOf(workspace) then return nil end
    -- V73: prioritize the containing Window model BEFORE a child VaultTrigger
    -- BasePart; otherwise each of the two triggers can create its own ESP.
    local map=workspace:FindFirstChild('Map')
    if map and obj:IsDescendantOf(map) then
        local parent=obj
        while parent and parent~=map do
            if parent:IsA('Model') and parent.Name:lower()=='window'
                and H.windowInteractionPart(parent) then
                return parent
            end
            parent=parent.Parent
        end
    end
    local officialWindow=H.mapWindowRoot(obj)
    if officialWindow then return officialWindow end
    local hadPrompt=H.vaultPrompt(obj)
    local nearestPart,nearestModel=nil,nil
    local cursor=obj
    while cursor and cursor~=workspace do
        if cursor:IsA('Tool') or cursor:IsA('Accessory') then return nil end
        if cursor:IsA('Model') and Players:GetPlayerFromCharacter(cursor) then
            return nil
        end
        if H.physical(cursor) and H.vaultTagged(cursor) and H.anyPart(cursor) then
            return cursor
        end
        if cursor:IsA('Model') and H.vaultName(cursor.Name) and H.anyPart(cursor) then
            return cursor
        end
        if cursor:IsA('BasePart') then
            if not nearestPart then nearestPart=cursor end
            if H.vaultName(cursor.Name) then return cursor end
            local parent=cursor.Parent
            if parent and H.vaultName(parent.Name) then
                if parent:IsA('Model') then return parent end
                -- Window can be a Folder that owns loose frame parts.
                return cursor
            end
        end
        if cursor:IsA('Model') and not nearestModel and H.anyPart(cursor) then
            -- Don't select a whole Map or house just because a prompt is inside.
            local name=cursor.Name:lower()
            if name~='map' and name~='level' and name~='building'
                and name~='house' and name~='environment' then
                nearestModel=cursor
            end
        end
        cursor=cursor.Parent
    end
    if hadPrompt then return nearestModel or nearestPart end
    return nil
end
function H.vaultDisabled(root)
    if not root or not root:IsDescendantOf(workspace) or not H.anyPart(root) then
        return true
    end
    if H.excludedObjectiveName(root.Name) then return true end
    local checks={root}
    if root:IsA('Model') and root.PrimaryPart then
        checks[#checks+1]=root.PrimaryPart
    end
    for _,o in ipairs(checks) do
        for _,name in ipairs({'Destroyed','IsDestroyed','Broken','IsBroken',
            'Disabled','IsDisabled','Blocked','IsBlocked'}) do
            if o:GetAttribute(name)==true then return true end
        end
        for _,name in ipairs({'CanVault','IsVaultable','Vaultable','IsUsable'}) do
            if o:GetAttribute(name)==false then return true end
        end
        local state=o:GetAttribute('VaultState') or o:GetAttribute('State')
        if type(state)=='string' then
            local n=state:lower()
            for _,bad in ipairs({'destroy','broken','blocked','disabled',
                'removed'}) do
                if n:find(bad,1,true) then return true end
            end
        end
    end
    return false
end
-- V55: a Window NAME alone is not proof of a usable vault.
-- In your own game, set Vaultable=true or tag the real vault assembly Vaultable.
-- Legacy map fallback accepts a true Window/Bottom assembly ONLY when its
-- actual geometry resembles a vaultable opening. Completely decorative
-- windows no longer qualify just because they share the name.
function H.vaultUsable(root)
    if not H.vaultInsideMap(root) then return false end
    if H.mapWindowRoot(root)==root then
        -- A reusable opening can temporarily have CanVault=false while
        -- occupied; the opening itself is still a useful ESP location.
        if root:GetAttribute('Destroyed')==true or root:GetAttribute('IsDestroyed')==true then
            return false
        end
        return H.windowInteractionPart(root)~=nil or H.vaultTagged(root)
    end
    if H.vaultDisabled(root) then return false end
    -- Legacy variants (without a dedicated Windows folder) still work.
    if H.vaultTagged(root) then return H.anyPart(root)~=nil end
    if root:IsA('Model') and H.vaultName(root.Name) then
        return H.windowInteractionPart(root)~=nil
            or H.vaultHasBottom(root)
    end
    return root:IsA('BasePart') and H.vaultName(root.Name)
end
function H.vaultTarget(root)
    if not root then return nil end
    if root:IsA('BasePart') then return root end
    if root:IsA('Model') then
        return H.windowInteractionPart(root) or H.anyPart(root)
    end
    return nil
end
-- V73: ONE subtle Bottom-part outline per real Window model.
-- Keep the cute VaultTrigger-era pink label, but anchor it to Bottom.
-- No extra squares on either VaultTrigger or inviswall.
-- V75: put the SelectionBox directly under the real Bottom BasePart.
-- The label is a separate GUI effect, rather than trying to render a
-- SelectionBox as a child of BillboardGui. Both are cached by Window root.
function H.createWindowMarker(root,part)
    local marker=H.new('BillboardGui',{
        Name='OronaCuteVaultESP',Adornee=part,AlwaysOnTop=true,
        Size=UDim2.fromOffset(82,24),
        StudsOffsetWorldSpace=Vector3.new(0,math.max(.7,part.Size.Y*.5+.25),0),
        MaxDistance=0,LightInfluence=0,Enabled=true
    },PG)
    local outline=H.new('SelectionBox',{
        Name='BottomOnlyOutline',Adornee=part,
        Color3=C.hot,Transparency=.06,
        LineThickness=.055,SurfaceColor3=C.pink,
        SurfaceTransparency=.89,Visible=true
    },part)
    pcall(function() outline.AlwaysOnTop=true end)
    H.vaultState.outlines=H.vaultState.outlines or {}
    H.vaultState.outlines[root]=outline
    local tag=H.label(marker,'♡ VAULT ♡',12,C.hot,
        UDim2.fromOffset(0,0),UDim2.fromScale(1,1))
    tag.ZIndex=6
    tag.TextStrokeColor3=C.white
    tag.TextStrokeTransparency=.25
    return marker
end

function H.removeVaultMarker(root)
    local state=H.vaultState
    local h=state.highlights[root]
    if h then h:Destroy();state.highlights[root]=nil end
    local o=state.outlines and state.outlines[root]
    if o then o:Destroy();state.outlines[root]=nil end
end
-- V64: A preloaded Map alone is NOT a reliable active-round signal.
-- Prefer an explicit server-replicated attribute / state Value; if the game
-- exposes neither, only a live survivor/killer role counts as a fallback.
-- For your own place: set workspace:SetAttribute('RoundActive', true/false)
-- from the SERVER at round start/end for authoritative detection.
H.repStorage=game:GetService('ReplicatedStorage')
H.roundCacheValue=false
H.roundCacheAt=-1
function H.invalidateRoundCache()
    H.roundCacheAt=-1
end
function H.liveStatus(value)
    if typeof(value)=='boolean' then return value end
    if typeof(value)=='string' then
        local state=value:lower():gsub('[%s_%-%./]','')
        if state=='active' or state=='inround' or state=='playing'
            or state=='ingame' or state=='inprogress'
            or state=='roundactive' or state=='matchactive'
            or state=='roundstarted' or state=='matchstarted' then return true end
        if state=='lobby' or state=='intermission' or state=='waiting'
            or state=='countdown' or state=='pregame' or state=='preparing'
            or state=='loading' or state=='starting' or state=='ended'
            or state=='roundended' or state=='postgame' or state=='results' then
            return false
        end
    end
    return nil
end
function H.vaultRoundActive()
    local now=os.clock()
    if now-(H.roundCacheAt or -1)<.3 then return H.roundCacheValue end
    local map=workspace:FindFirstChild('Map')
    if not map then
        H.roundCacheAt=now;H.roundCacheValue=false
        return false
    end
    local team=Me.Team and Me.Team.Name:lower() or ''
    if team:find('lobby',1,true) or team:find('spectat',1,true)
        or team:find('waiting',1,true) or team:find('intermission',1,true)
        or team:find('neutral',1,true) then
        H.roundCacheAt=now;H.roundCacheValue=false
        return false
    end
    local sources={workspace,Me,H.repStorage}
    for _,node in ipairs({workspace,H.repStorage}) do
        for _,name in ipairs({'GameState','RoundState','GameStatus','RoundStatus'}) do
            local child=node:FindFirstChild(name)
            if child then sources[#sources+1]=child end
        end
    end
    local booleanKeys={'RoundActive','InRound','IsInRound','MatchActive',
        'GameInProgress','MatchStarted','RoundStarted','IsPlaying'}
    local statusKeys={'RoundState','MatchState','GameState','GameStatus',
        'RoundStatus','MatchStatus','Status','Phase'}
    local determined=nil
    for _,source in ipairs(sources) do
        if source then
            for _,key in ipairs(booleanKeys) do
                local value=source:GetAttribute(key)
                if type(value)=='boolean' then determined=value;break end
                local child=source:FindFirstChild(key)
                if child and child:IsA('BoolValue') then determined=child.Value;break end
            end
            if determined~=nil then break end
            for _,key in ipairs(statusKeys) do
                local value=H.liveStatus(source:GetAttribute(key))
                if value~=nil then determined=value;break end
                local child=source:FindFirstChild(key)
                if child and (child:IsA('StringValue') or child:IsA('BoolValue')) then
                    value=H.liveStatus(child.Value)
                    if value~=nil then determined=value;break end
                end
            end
            if determined~=nil then break end
            if source:IsA('StringValue') or source:IsA('BoolValue') then
                determined=H.liveStatus(source.Value)
                if determined~=nil then break end
            end
        end
    end
    if determined==nil then
        -- No explicit round flag is exposed: require an actual assigned match
        -- role, not simply a player standing in the lobby while Map loads.
        local role=Me:GetAttribute('Role') or Me:GetAttribute('PlayerRole')
        local roleName=type(role)=='string' and role:lower() or ''
        local activeRole=(roleName=='killer' or roleName=='survivor'
            or roleName=='runner' or roleName=='hunter'
            or team:find('survivor',1,true)~=nil
            or team:find('killer',1,true)~=nil)
        local character=Me.Character
        local humanoid=character and character:FindFirstChildOfClass('Humanoid')
        determined=activeRole and humanoid~=nil and humanoid.Health>0
    end
    H.roundCacheAt=now
    H.roundCacheValue=(determined==true)
    return H.roundCacheValue
end
function H.vaultInsideMap(root)
    local map=workspace:FindFirstChild('Map')
    return map and root and root:IsDescendantOf(map)
        and H.vaultRoundActive()
end
function H.updateVaults()
    local state=H.vaultState
    local map=workspace:FindFirstChild('Map')
    if unloaded or S.Streamer or not S.Vaults or not map or not H.vaultRoundActive() then
        for root,effect in pairs(state.highlights) do
            if effect then effect.Enabled=false end
            local outline=state.outlines and state.outlines[root]
            if outline then outline.Visible=false end
        end
        state.lastVisible=0
        return
    end
    -- Canonicalize every candidate to its ONE Window model. Each model
    -- can contain TWO VaultTrigger children, but only one Bottom is drawn.
    local canonical={}
    for candidate in pairs(state.candidates) do
        if candidate and candidate:IsDescendantOf(map) then
            local root=H.mapWindowRoot(candidate) or H.vaultRoot(candidate)
            if root and H.vaultUsable(root) and H.windowInteractionPart(root) then
                canonical[root]=true
            end
        end
    end
    state.candidates=canonical
    local chosen={}
    local count=0
    for root in pairs(canonical) do
        local target=H.windowInteractionPart(root)
        if target and target:IsA('BasePart') then
            chosen[root]=true
            count+=1
            local marker=state.highlights[root]
            local outline=state.outlines and state.outlines[root]
            if not (marker and marker.Parent and marker:IsA('BillboardGui')
                and outline and outline.Parent) then
                H.removeVaultMarker(root)
                marker=H.createWindowMarker(root,target)
                outline=state.outlines[root]
                state.highlights[root]=marker
            end
            marker.Adornee=target
            marker.Enabled=true
            if outline then
                outline.Adornee=target
                if outline.Parent~=target then outline.Parent=target end
                outline.Visible=true
            end
        end
    end
    local stale={}
    for root in pairs(state.highlights) do
        if not chosen[root] then stale[#stale+1]=root end
    end
    for _,root in ipairs(stale) do H.removeVaultMarker(root) end
    state.lastVisible=count
end

-- V75: the author's map also has Window models nested inside plain
-- "Model" parents. Scan those folders once in small time-limited batches,
-- rather than depending on Map.Windows / resources.Windows alone.
function H.scanNestedVaultWindows()
    local map=workspace:FindFirstChild('Map')
    if not map or not S.Vaults or not H.vaultRoundActive() then return end
    local state=H.vaultState
    if state.scannedNestedMap==map then return end
    state.scannedNestedMap=map
    state.nestedScanToken=(state.nestedScanToken or 0)+1
    local token=state.nestedScanToken
    task.spawn(function()
        local queue={map}
        local head=1
        local found=0
        while head<=#queue and not unloaded and S.Vaults and
            token==state.nestedScanToken and map.Parent==workspace do
            local count=0
            local deadline=os.clock()+.0018
            while head<=#queue and count<280 and os.clock()<deadline do
                local node=queue[head]
                queue[head]=false
                head+=1
                count+=1
                if node:IsA('Model') and node.Name:lower()=='window'
                    and H.windowInteractionPart(node) then
                    state.candidates[node]=true
                    found+=1
                end
                -- Models and Folders can contain other models. Parts need
                -- not be traversed to find the Window model itself.
                for _,child in ipairs(node:GetChildren()) do
                    if child:IsA('Folder') or child:IsA('Model') then
                        queue[#queue+1]=child
                    end
                end
            end
            if found>0 and (found%8==0 or head>#queue) then
                H.updateVaults()
            end
            task.wait()
        end
        if token==state.nestedScanToken and S.Vaults and not unloaded then
            H.updateVaults()
        end
    end)
end

function H.discoverVaults()
    local state=H.vaultState
    state.scanToken+=1
    state.lastScan=os.clock()
    local map=workspace:FindFirstChild('Map')
    if not map or not H.vaultRoundActive() then return end
    for _,tag in ipairs({'Vault','Vaultable','UsableVault','VaultOpening',
        'VaultInteractable','VaultWindow','VDVault'}) do
        for _,obj in ipairs(CollectionService:GetTagged(tag)) do
            if H.vaultInsideMap(obj) then
                local root=H.vaultRoot(obj)
                if root then state.candidates[root]=true end
            end
        end
    end
    H.scanNestedVaultWindows()
    H.updateVaults()
end

function H.toggleVaults(value)
    local state=H.vaultState
    if value then
        H.discoverVaults()
        H.updateVaults()
    else
        state.scanToken+=1
        state.nestedScanToken=(state.nestedScanToken or 0)+1
        state.scannedNestedMap=nil
        for root in pairs(state.highlights) do H.removeVaultMarker(root) end
        state.candidates={}
        state.lastVisible=0
    end
end

-- ========= V49: EXIT GATE ESP =========
-- The public VD map structures commonly use Map.Gate.ExitLever.Main.
-- Keep opened gates marked: survivors still need their escape locations.
H.gateState={candidates={},highlights={},indicators={},generators={},
    scanToken=0,lastScan=0,maxShown=6}
function H.gateName(name)
    local n=name:lower():gsub('[%s_%-%(%)]+','')
    if n:find('decor',1,true) or n:find('fake',1,true)
        or n:find('spawn',1,true) or n:find('template',1,true) then
        return false
    end
    return n=='gate' or n=='exitgate' or n=='exitlever'
        or n=='escapedoor' or n=='exitdoor' or n=='gatelever'
        or n:match('^exitgate%d+$')~=nil
        or n:match('^escapedoor%d+$')~=nil
        or n:match('^exitlever%d+$')~=nil
        or n=='escapegate' or n=='maingate'
end
function H.gateTagged(root)
    if not root then return false end
    for _,tag in ipairs({'ExitGate','VDExitGate','EscapeGate','ExitLever'}) do
        if CollectionService:HasTag(root,tag) then return true end
    end
    return root:GetAttribute('IsExitGate')==true
        or root:GetAttribute('ExitGate')==true
        or root:GetAttribute('CanEscape')==true
end
function H.gatePrompt(obj)
    if not obj or not obj:IsA('ProximityPrompt') then return false end
    local s=((obj.Name or '')..' '..(obj.ActionText or '')..' '..
        (obj.ObjectText or '')):lower()
    return s:find('exit',1,true)~=nil
        or s:find('escape',1,true)~=nil
        or s:find('open gate',1,true)~=nil
end
function H.gateRoot(o)
    if not o or not o:IsDescendantOf(workspace) then return nil end
    local map=workspace:FindFirstChild('Map')
    if not map or not o:IsDescendantOf(map) then return nil end
    local topGate,closest=nil,nil
    local cur=o
    while cur and cur~=workspace and cur~=map do
        if cur:IsA('Tool') or cur:IsA('Accessory') then return nil end
        if cur:IsA('Model') and Players:GetPlayerFromCharacter(cur) then return nil end
        if H.physical(cur) and H.anyPart(cur) and
            (H.gateName(cur.Name) or H.gateTagged(cur)) then
            closest=closest or cur
            if cur:IsA('Model') then topGate=cur end
        end
        cur=cur.Parent
    end
    -- Nearest actual Gate with an ExitLever wins, not enclosing ESCAPEGATE
    -- models or folders (which would outline the whole building).
    cur=o
    while cur and cur~=workspace and cur~=map do
        if cur:IsA('Model') and cur.Name:lower()=='gate'
            and cur:FindFirstChild('ExitLever',true) then return cur end
        cur=cur.Parent
    end
    return topGate or closest
end

function H.gateTarget(root)
    -- Exit gate ESP should mark the lever assembly from the screenshot.
    local lever=root and root:FindFirstChild('ExitLever',true)
    if lever and H.physical(lever) and H.anyPart(lever) then return lever end
    local main=root and root:FindFirstChild('Main',true)
    if main and main:IsA('BasePart') then return main end
    return root
end
function H.gateOpen(root)
    local nodes={root}
    local lever=root:FindFirstChild('ExitLever',true)
    local main=root:FindFirstChild('Main',true)
    local door=root:FindFirstChild('Door',true)
    if door then nodes[#nodes+1]=door end
    if lever then nodes[#nodes+1]=lever end
    if main then nodes[#nodes+1]=main end
    for _,obj in ipairs(nodes) do
        if obj then
            for _,attr in ipairs({'Open','Opened','IsOpen','GateOpened',
                'ExitOpen','DoorOpen'}) do
                if obj:GetAttribute(attr)==true then return true end
            end
            local state=obj:GetAttribute('State') or obj:GetAttribute('GateState')
            if type(state)=='string' then
                local n=state:lower()
                if n=='open' or n=='opened' or n=='escaped' then return true end
            end
        end
    end
    return false
end
-- Separate indicator readiness from lever discovery. The gate highlight
-- can exist before power; the pink ! appears only once open or unlocked.
-- V65: a gate's pink ! means THAT gate has reached 100% power and
-- still needs activation. Finishing generators is not the same thing.
function H.gateReady(root,allDone)
    if not root or H.gateOpen(root) then return false end
    local lever=root:FindFirstChild('ExitLever',true)
    local nodes={root,lever}
    if lever then
        local main=lever:FindFirstChild('Main',true)
        if main then nodes[#nodes+1]=main end
    end
    for _,node in ipairs(nodes) do
        if node then
            -- A numeric gate-specific 100% charge is the strongest evidence.
            for _,key in ipairs({'GatePower','GatePowerPercent','PowerPercent',
                'PoweredPercent','ChargePercent','PowerProgress','GateProgress',
                'ExitProgress','ActivationProgress','Progress','Power','Charge'}) do
                local v=node:GetAttribute(key)
                if v==nil then
                    local child=node:FindFirstChild(key)
                    if child and (child:IsA('NumberValue') or child:IsA('IntValue')) then
                        v=child.Value
                    end
                end
                if type(v)=='number' then
                    if v>=99.999 then return true end
                    -- Explicit normalized fraction values use 0..1.
                    if (key=='PowerFraction' or key=='PowerRatio') and v>=.999 then
                        return true
                    end
                end
            end
            for _,key in ipairs({'PowerFraction','PowerRatio'}) do
                local v=node:GetAttribute(key)
                if type(v)=='number' and v>=.999 then return true end
            end
            for _,key in ipairs({'Powered','IsPowered','GatePowered',
                'FullyPowered','ReadyToActivate','ReadyForActivation'}) do
                if node:GetAttribute(key)==true then return true end
                local child=node:FindFirstChild(key)
                if child and child:IsA('BoolValue') and child.Value then return true end
            end
            local status=node:GetAttribute('GateState') or node:GetAttribute('PowerState')
            if type(status)=='string' then
                status=status:lower():gsub('[%s_%-%./]','')
                if status=='fullypowered' or status=='powered'
                    or status=='readytoactivate' then return true end
            end
        end
    end
    return false
end

function H.gateGeneratorComplete(gen)
    local p=gen:GetAttribute('RepairProgress')
    return (type(p)=='number' and p>=100)
        or gen:GetAttribute('Completed')==true
        or gen:GetAttribute('IsCompleted')==true
        or gen:GetAttribute('Repaired')==true
end
function H.gateUnlocked()
    local found=false
    local active=false
    for gen in pairs(H.gateState.generators) do
        if not gen:IsDescendantOf(workspace) then
            H.gateState.generators[gen]=nil
        else
            found=true
            if not H.gateGeneratorComplete(gen) then active=true end
        end
    end
    return found and not active
end
function H.gateUsable(root,allDone)
    if not root or not H.anyPart(root) or not H.vaultInsideMap(root) then
        return false
    end
    -- Show the actual exit lever's location, even before gens are repaired.
    -- ExitLever is canonical gameplay structure, not a generic Gate prop.
    local lever=root:FindFirstChild('ExitLever',true)
    if lever and H.physical(lever) and H.anyPart(lever) then return true end
    -- Keep gates visible after opening even if lever stops accepting input.
    if H.gateOpen(root) then return true end
    if allDone then return true end
    local map=workspace:FindFirstChild('Map')
    for _,container in ipairs({root,map or root,workspace}) do
        for _,attr in ipairs({'GatesPowered','ExitGatesPowered',
            'ExitGatesUnlocked','AllGeneratorsComplete','AllGensRepaired'}) do
            if container:GetAttribute(attr)==true then return true end
        end
    end
    for _,obj in ipairs({root,root:FindFirstChild('ExitLever',true)}) do
        if obj then
            for _,attr in ipairs({'Powered','IsPowered','Unlocked','IsUnlocked',
                'CanOpen','Active','CanEscape'}) do
                if obj:GetAttribute(attr)==true then return true end
            end
        end
    end
    -- A custom game may have gates but not mirror generator progress to clients.
    -- Check native interaction as fallback instead of hiding every known gate.
    for _,obj in ipairs(root:GetDescendants()) do
        if obj:IsA('ProximityPrompt') and obj.Enabled and H.gatePrompt(obj) then
            return true
        end
    end
    return false
end

function H.removeGate(root)
    local st=H.gateState
    if st.highlights[root] then st.highlights[root]:Destroy(); st.highlights[root]=nil end
    if st.indicators[root] then st.indicators[root]:Destroy(); st.indicators[root]=nil end
end
function H.updateGates()
    if unloaded or S.Streamer or not S.ExitGates or not H.vaultRoundActive() then return end
    local st=H.gateState
    local allDone=H.gateUnlocked()
    local chosen={}
    local count=0
    for root in pairs(st.candidates) do
        if not root:IsDescendantOf(workspace) then
            st.candidates[root]=nil
            H.removeGate(root)
        elseif count<st.maxShown and H.gateUsable(root,allDone) then
            local target=H.gateTarget(root)
            count+=1
            chosen[root]=true
            if not st.highlights[root] or not st.highlights[root].Parent then
                if st.highlights[root] then st.highlights[root]:Destroy() end
                local h=H.addHighlight(target,C.light,C.lightEdge)
                h.Name='OronaExitGateESP'
                h.Parent=workspace
                st.highlights[root]=h
            end
            st.highlights[root].Enabled=true
            if H.gateReady(root,allDone) then
                if not st.indicators[root] or not st.indicators[root].Parent then
                    if st.indicators[root] then st.indicators[root]:Destroy() end
                    local b=H.new('BillboardGui',{
                        Name='OronaOpenedExit',Adornee=H.anyPart(target),
                        Size=UDim2.fromOffset(48,66),
                        StudsOffsetWorldSpace=Vector3.new(0,4.7,0),
                        AlwaysOnTop=true,MaxDistance=1000,LightInfluence=0
                    },PG)
                    local mark=H.label(b,'!',46,C.hot,
                        UDim2.fromScale(0,0),UDim2.fromScale(1,1))
                    mark.TextStrokeColor3=C.white
                    mark.TextStrokeTransparency=.1
                    local scale=H.new('UIScale',{Scale=1},mark)
                    TS:Create(scale,TweenInfo.new(.65,Enum.EasingStyle.Sine,
                        Enum.EasingDirection.InOut,-1,true),{Scale=1.38}):Play()
                    st.indicators[root]=b
                end
            elseif st.indicators[root] then
                st.indicators[root]:Destroy()
                st.indicators[root]=nil
            end
        end
    end
    for root in pairs(st.highlights) do
        if not chosen[root] then H.removeGate(root) end
    end
end
function H.discoverGates()
    local st=H.gateState
    st.scanToken+=1
    st.lastScan=os.clock()
    local map=workspace:FindFirstChild('Map')
    if not map or not H.vaultRoundActive() then return end
    for _,tag in ipairs({'ExitGate','VDExitGate','EscapeGate','ExitLever'}) do
        for _,o in ipairs(CollectionService:GetTagged(tag)) do
            if o:IsDescendantOf(map) then
                local root=H.gateRoot(o)
                if root then st.candidates[root]=true end
            end
        end
    end
    if H.scheduleFullScan then H.scheduleFullScan() end
    H.updateGates()
end

function H.toggleGates(value)
    local st=H.gateState
    if value then
        H.discoverGates()
    else
        st.scanToken+=1
        for root in pairs(st.highlights) do H.removeGate(root) end
        st.candidates={}
        st.generators={}
    end
end

-- ======== V47: HALLOWEEN SMASHABLE PUMPKINS =========
-- Detection is conservative: prefer smash prompts, tags and explicit state.
-- No update runs when the toggle is off, and each map is scanned once.
H.pumpkinState={candidates={},highlights={},labels={},scanToken=0,lastScan=0,maxShown=24,lastUpdate=0}
function H.pumpkinName(name)
    local n=name:lower():gsub('[%s_%-%(%)]+','')
    if n:find('decoration',1,true) or n:find('decor',1,true)
       or n:find('fake',1,true) or n:find('preview',1,true)
       or n:find('smashfx',1,true) or n:find('shard',1,true)
       or n:find('debris',1,true) or n:find('particle',1,true)
       or n:find('pumpkinpatch',1,true) or n:find('pumpkinfield',1,true) then
        return false
    end
    return n:find('pumpkin',1,true)~=nil
       or n:find('jackolantern',1,true)~=nil
       or n:find('halloweenlantern',1,true)~=nil
end
function H.pumpkinPrompt(p)
    if not p or not p:IsA('ProximityPrompt') then return false end
    local t=((p.ActionText or '')..' '..(p.ObjectText or '')..' '..p.Name):lower()
    return t:find('pumpkin',1,true)~=nil or t:find('smash',1,true)~=nil
        or t:find('jack o',1,true)~=nil
end
function H.pumpkinRoot(o)
    if not o or not o:IsDescendantOf(workspace) then return nil end
    local firstPart=nil
    local cur=o
    while cur and cur~=workspace do
        if cur:IsA('Tool') or cur:IsA('Accessory') then return nil end
        if cur:IsA('Model') and Players:GetPlayerFromCharacter(cur) then return nil end
        if cur:IsA('BasePart') and not firstPart then firstPart=cur end
        if H.physical(cur) and H.pumpkinName(cur.Name) and H.anyPart(cur) then
            -- Prefer the root Model, but not unrelated containing buildings.
            if cur:IsA('BasePart') and cur.Parent:IsA('Model')
                and H.pumpkinName(cur.Parent.Name) then
                return cur.Parent
            end
            return cur
        end
        if H.physical(cur) and H.anyPart(cur)
            and (cur:GetAttribute('SmashablePumpkin')==true
                or cur:GetAttribute('IsPumpkin')==true
                or CollectionService:HasTag(cur,'SmashablePumpkin')
                or CollectionService:HasTag(cur,'HalloweenPumpkin')) then
            return cur
        end
        cur=cur.Parent
    end
    return nil
end
function H.pumpkinActive(root)
    if not root or not root:IsDescendantOf(workspace) or not H.anyPart(root) then
        return false
    end
    local n=root.Name:lower()
    for _,bad in ipairs({'broken','destroyed','smashed','collected','used','decor','fake'}) do
        if n:find(bad,1,true) then return false end
    end
    for _,attr in ipairs({'Smashed','IsSmashed','Destroyed','IsDestroyed',
       'Collected','IsCollected','Broken','IsBroken','Used','IsUsed'}) do
        if root:GetAttribute(attr)==true then return false end
    end
    for _,attr in ipairs({'CanSmash','Smashable','IsActive','Available'}) do
        if root:GetAttribute(attr)==false then return false end
    end
    local state=root:GetAttribute('State') or root:GetAttribute('PumpkinState')
    if type(state)=='string' then
        local st=state:lower()
        if st:find('smash',1,true) or st:find('break',1,true)
            or st:find('collect',1,true) or st:find('destroy',1,true) then
            return false
        end
    end
    local p=root:FindFirstChildWhichIsA('ProximityPrompt',true)
    if p and H.pumpkinPrompt(p) then return true end
    -- Custom event UIs often use a pumpkin Model without a native prompt.
    return H.pumpkinName(root.Name)
        or CollectionService:HasTag(root,'HalloweenPumpkin')
        or root:GetAttribute('SmashablePumpkin')==true
end
function H.removePumpkin(root)
    local p=H.pumpkinState
    if p.highlights[root] then p.highlights[root]:Destroy();p.highlights[root]=nil end
    if p.labels[root] then p.labels[root]:Destroy();p.labels[root]=nil end
end
function H.updatePumpkins()
    local state=H.pumpkinState
    if S.Streamer or not S.Pumpkins or unloaded or not H.vaultRoundActive() then return end
    local char=Me.Character
    local rootPart=char and char:FindFirstChild('HumanoidRootPart')
    local camera=workspace.CurrentCamera
    local position=rootPart and rootPart.Position or (camera and camera.CFrame.Position)
    local eligible={}
    for root in pairs(state.candidates) do
        if not root:IsDescendantOf(workspace) then
            state.candidates[root]=nil
            H.removePumpkin(root)
        elseif H.pumpkinActive(root) and H.safeObjectiveTarget(root,root,'Pumpkins') then
            local part=H.anyPart(root)
            eligible[#eligible+1]={root=root,
                distance=(part and position) and (part.Position-position).Magnitude or 0}
        end
    end
    table.sort(eligible,function(a,b)
        return a.root:GetFullName()<b.root:GetFullName()
    end)
    local chosen={}
    for i=1,math.min(state.maxShown,#eligible) do
        local root=eligible[i].root
        chosen[root]=true
        local h=state.highlights[root]
        if not h or not h.Parent then
            if h then h:Destroy() end
            h=H.addHighlight(root,C.light,C.lightEdge)
            h.Name='OronaPumpkinESP'
            h.Parent=workspace
            state.highlights[root]=h
        end
        h.Enabled=true
        if not state.labels[root] or not state.labels[root].Parent then
            if state.labels[root] then state.labels[root]:Destroy() end
            state.labels[root]=H.objectiveCaption(root,'PUMPKIN',2)
        end
    end
    for root in pairs(state.highlights) do
        if not chosen[root] then H.removePumpkin(root) end
    end
end
function H.discoverPumpkins()
    local st=H.pumpkinState
    st.scanToken+=1
    st.lastScan=os.clock()
    for _,tag in ipairs({'SmashablePumpkin','HalloweenPumpkin'}) do
        for _,o in ipairs(CollectionService:GetTagged(tag)) do
            if o:IsDescendantOf(workspace) then
                local root=H.pumpkinRoot(o)
                if root then st.candidates[root]=true end
            end
        end
    end
    if H.scheduleFullScan then H.scheduleFullScan() end
    H.updatePumpkins()
end

function H.togglePumpkins(value)
    local st=H.pumpkinState
    if value then
        H.discoverPumpkins()
    else
        st.scanToken+=1
        for root in pairs(st.highlights) do H.removePumpkin(root) end
        st.candidates={}
    end
end

local function trapName(n)
n=n:lower():gsub('[%s_%-]','')
return n=='beartrap' or n=='steeltrap' or n=='placedtrap'
or n=='trap' or n:match('^beartrap%d+$')~=nil
end
local function isTrapCandidate(o)
return H.physical(o) and trapName(o.Name)
end
local function trapRoot(o)
local candidate=nil
local cur=o
while cur and cur~=workspace do
if cur:IsA('Tool') or cur:IsA('Accessory') then return nil end
if cur:IsA('Model') and Players:GetPlayerFromCharacter(cur) then
return nil
end
if isTrapCandidate(cur) then candidate=cur end
cur=cur.Parent
end
if not candidate then return nil end
local state=candidate:GetAttribute('State')
if candidate:GetAttribute('Triggered')==true
or candidate:GetAttribute('Disarmed')==true
or candidate:GetAttribute('IsActive')==false
or (type(state)=='string' and
(state:lower()=='disarmed' or state:lower()=='inactive')) then
return nil
end
return candidate
end
local colors={
Hooks={C.light,C.lightEdge},
Generators={C.light,C.lightEdge},
Traps={C.light,C.lightEdge}
}
local genBars={}
local removeObject
local function generatorComplete(root)
    if not root or not root:IsDescendantOf(workspace) then return true end
    local progress=root:GetAttribute('RepairProgress')
    local completed=(type(progress)=='number' and progress>=100)
        or root:GetAttribute('Completed')==true
        or root:GetAttribute('IsCompleted')==true
        or root:GetAttribute('Repaired')==true
        or root:GetAttribute('IsRepaired')==true
        or root:GetAttribute('IsFinished')==true
    -- Reject demonstrably completed generators, not temporary interaction
    -- flags such as Disabled/Usable=false on an otherwise intact model.
    if H.generatorKnownMap(root) then return completed end
    return completed or H.objectiveDisabled(root,'Generators')
end
local function destroyGenBar(root)
    local b=genBars[root]
    if b then
        if b.progressConnection then b.progressConnection:Disconnect() end
        b.gui:Destroy()
        genBars[root]=nil
    end
end
local function refreshGenBar(root)
local b=genBars[root]
if not b then return end
if not root:IsDescendantOf(workspace) or not S.Generators then
    destroyGenBar(root)
    return
end
local raw=root:GetAttribute('RepairProgress')
local pct=type(raw)=='number' and math.clamp(raw,0,100) or nil
local caption=pct and string.format('%.0f%%',pct) or '--%'
if b.text.Text~=caption then b.text.Text=caption end
b.gui.Enabled=true
end
local function ensureGenBar(root)
if generatorComplete(root) or genBars[root] or not S.Generators then return end
local anchor=root:FindFirstChild('GeneratorBody',true)
    or root:FindFirstChild('RootPart',true) or H.anyPart(root)
if not anchor or not anchor:IsA('BasePart') then anchor=H.anyPart(root) end
if not anchor then return end
local b=H.new('BillboardGui',{
    Name='OronaRepairPercent',Adornee=anchor,
    Size=UDim2.fromOffset(60,23),
    StudsOffsetWorldSpace=Vector3.new(0,3.3,0),
    AlwaysOnTop=true,LightInfluence=0,MaxDistance=850,
    Enabled=true},PG)
local txt=H.label(b,'--%',12,C.hot,
    UDim2.fromScale(0,0),UDim2.fromScale(1,1))
local outline=H.new('UIStroke',{
    Color=C.dark,Thickness=.8,Transparency=.25},txt)
genBars[root]={gui=b,text=txt}
-- Hide completed generators immediately as the repair attribute changes.
genBars[root].progressConnection=root:GetAttributeChangedSignal('RepairProgress'):Connect(function()
    if unloaded then return end
    if generatorComplete(root) then
        removeObject(root)
    else
        refreshGenBar(root)
    end
end)
refreshGenBar(root)
end
removeObject=function(root)
local r=objectFX[root]
if not r then return end
r.effect:Destroy()
if r.caption then r.caption:Destroy() end
objectFX[root]=nil
objectCount=math.max(0,objectCount-1)
kindCount[r.kind]=math.max(0,(kindCount[r.kind] or 1)-1)
if r.kind=='Generators' then destroyGenBar(root) end
end
local function mark(root,kind,target)
if (kind=='Generators' and generatorComplete(root))
    or ((kind=='Hooks' or kind=='Generators')
        and not H.confirmedObjective(root,kind)) then
    if objectFX[root] then removeObject(root) end
    return
end
if unloaded or S.Streamer or not enabled or not S[kind] or not root or
not H.vaultRoundActive() or not root:IsDescendantOf(workspace) then return end
target=target or root
if not H.physical(target) or not H.safeObjectiveTarget(root,target,kind) then
    if objectFX[root] then removeObject(root) end
    return
end
local old=objectFX[root]
if old then
if old.kind==kind and old.target==target and old.effect.Parent then
if kind=='Generators' then ensureGenBar(root) end
return
end
removeObject(root)
end
if objectCount>=MAX_OBJECTS
or (kindCount[kind] or 0)>=(kindLimit[kind] or 30) then return end
local c=colors[kind]
objectFX[root]={kind=kind,target=target,
effect=H.addHighlight(target,c[1],c[2]),
caption=kind=='Traps' and H.objectiveCaption(root,'BEAR TRAP',.75) or nil}
objectCount+=1
kindCount[kind]=(kindCount[kind] or 0)+1
if kind=='Generators' then ensureGenBar(root) end
end
local function inspect(o)
    if unloaded or S.Streamer or not H.vaultRoundActive() then return end
    if o:IsA('ProximityPrompt') then
        H.inspectObjectivePrompt(o)
        if S.Pumpkins and H.pumpkinPrompt(o) then
            local pr=H.pumpkinRoot(o)
            if pr then H.pumpkinState.candidates[pr]=true end
        end
        if S.Vaults and H.vaultPrompt(o) then
            local vr=H.vaultRoot(o)
            if vr then H.vaultState.candidates[vr]=true end
        end
        if S.ExitGates and H.gatePrompt(o) then
            local gr=H.gateRoot(o)
            if gr then H.gateState.candidates[gr]=true end
        end
        -- A new interactive prompt can make a previously rejected hook/gen
        -- valid without needing to rerun a full map scan.
        local h=H.hookRoot(o)
        local g=H.generatorRoot(o)
        if S.Hooks and h and H.confirmedObjective(h,'Hooks') then mark(h,'Hooks') end
        if S.Generators and g and H.confirmedObjective(g,'Generators') then
            mark(g,'Generators',g)
        end
        return
    end
    if not H.physical(o) then return end
    if workspace.CurrentCamera and o:IsDescendantOf(workspace.CurrentCamera) then return end
    for _,p in ipairs(Players:GetPlayers()) do
        if p.Character and o:IsDescendantOf(p.Character) then return end
    end
    if S.Hooks and H.contains(o.Name,'hook') then
        local root=H.hookRoot(o)
        if root then
            objectiveCandidates.Hooks[root]=true
            if H.confirmedObjective(root,'Hooks') then mark(root,'Hooks') end
        end
    end
    if S.Generators and H.isGenerator(o) then
        local root=H.generatorRoot(o)
        if root then
            objectiveCandidates.Generators[root]=true
            if H.confirmedObjective(root,'Generators') then
                mark(root,'Generators',root)
            end
        end
    end
    if S.Pallets and (H.contains(o.Name,'pallet')
        or (o.Parent and o.Parent.Name=='Pallets'
            and (o.Parent.Parent==workspace:FindFirstChild('Map')
                or (o.Parent.Parent and o.Parent.Parent.Name=='resources'
                    and o.Parent.Parent.Parent==workspace:FindFirstChild('Map'))))) then
        local root=H.getPalletModel(o)
        if root and H.anyPart(root) then
            palletCandidates[root]=true
            H.palletRefreshRequested=true
        end
    end
    if S.ExitGates and H.physical(o) then
        if H.gateName(o.Name) or H.gateTagged(o) then
            local gt=H.gateRoot(o)
            if gt then H.gateState.candidates[gt]=true end
        end
        if H.isGenerator(o) then
            local gr=H.generatorRoot(o)
            if gr then H.gateState.generators[gr]=true end
        end
    end
    if S.Pumpkins and H.pumpkinName(o.Name) then
        local pr=H.pumpkinRoot(o)
        if pr then H.pumpkinState.candidates[pr]=true end
    end
    if S.Vaults and (H.vaultName(o.Name) or H.vaultTagged(o) or
        (o:IsA('BasePart') and (
            (o.Parent and H.vaultName(o.Parent.Name)) or
            o.Name:lower()=='bottom' or o.Name:lower()=='bottompart' or
            o.Name:lower()=='windowbottom' or o.Name:lower()=='vaulttrigger'))) then
        local vr=H.vaultRoot(o)
        if vr then H.vaultState.candidates[vr]=true end
    end
    if S.Traps and isTrapCandidate(o) then
        local root=trapRoot(o)
        if root then mark(root,'Traps') end
    end
end

-- V60 instantaneous candidate discovery from verified map folders.
-- Called on toggle and deferred on new map objects; no whole-map walk.
function H.fastIndexKnown()
    if unloaded or S.Streamer or not H.vaultRoundActive() then return end
    local map=workspace:FindFirstChild('Map')
    if not map then return end
    local resources=map:FindFirstChild('resources')
    local function collect(folder,callback)
        if not folder then return end
        for _,child in ipairs(folder:GetChildren()) do callback(child) end
    end
    if S.Generators or S.ExitGates then
        local function gen(child)
            if child:IsA('Model') and H.generatorKnownMap(child) then
                if S.Generators then
                    objectiveCandidates.Generators[child]=true
                    mark(child,'Generators',child)
                end
                if S.ExitGates then H.gateState.generators[child]=true end
            end
        end
        collect(map:FindFirstChild('newGenerators'),gen)
        collect(map:FindFirstChild('Generators'),gen)
        if resources then collect(resources:FindFirstChild('Generators'),gen) end
    end
    if S.Hooks then
        local function hook(child)
            if child:IsA('Model') and H.isHookName(child.Name)
                and H.anyPart(child) then
                objectiveCandidates.Hooks[child]=true
                mark(child,'Hooks')
            end
        end
        collect(map:FindFirstChild('Hooks'),hook)
        if resources then collect(resources:FindFirstChild('Hooks'),hook) end
        for _,child in ipairs(map:GetChildren()) do
            if child:IsA('Model') and H.isHookName(child.Name) then hook(child) end
        end
    end
    if S.Pallets then
        local function pallet(child)
            if child:IsA('Model') and H.anyPart(child)
                and not H.excludedObjectiveName(child.Name) then
                local root=H.getPalletModel(child) or child
                if H.palletModelName(root.Name)
                    or H.mapPalletRoot(root)==root
                    or H.trackablePallet(root) then
                    palletCandidates[root]=true
                end
            end
        end
        collect(map:FindFirstChild('Pallets'),pallet)
        if resources then collect(resources:FindFirstChild('Pallets'),pallet) end
        updatePallets()
    end
    if S.Vaults then
        local function window(child)
            if child:IsA('Model') and H.windowInteractionPart(child) then
                H.vaultState.candidates[child]=true
            end
        end
        collect(map:FindFirstChild('Windows'),window)
        if resources then collect(resources:FindFirstChild('Windows'),window) end
        H.scanNestedVaultWindows()
        H.updateVaults()
    end
    if S.ExitGates then
        -- ExitGate models sometimes sit several levels inside ESCAPEGATE.
        local function gateGroup(group,depth)
            if depth<=0 then return end
            for _,child in ipairs(group:GetChildren()) do
                if child:IsA('Model') and H.gateName(child.Name) then
                    local root=H.gateRoot(child)
                    if root and root:FindFirstChild('ExitLever',true) then
                        H.gateState.candidates[root]=true
                    end
                end
                local name=child.Name:lower()
                if name=='escapegate' or name=='gate' or name=='exits'
                    or name=='gates' or name=='barriers' then
                    gateGroup(child,depth-1)
                end
            end
        end
        gateGroup(map,4)
        H.updateGates()
    end
    if H.indexEntireMapOnce then H.indexEntireMapOnce() end
end

-- V76: pre-index known objectives ONCE per loaded map, not by proximity.
-- Folder names in different maps vary; scan only Folder/Model branches.
-- This is budgeted on initial discovery and never sorts objectives by distance.
H.globalObjectiveIndex={map=nil,token=0,running=false}
function H.indexEntireMapOnce(force)
    local map=workspace:FindFirstChild('Map')
    if not map or unloaded or S.Streamer or not H.vaultRoundActive() then return end
    local index=H.globalObjectiveIndex
    if index.map==map and not force then return end
    index.map=map
    index.token+=1
    local token=index.token
    index.running=true
    task.spawn(function()
        local queue={map}
        local head=1
        while head<=#queue and not unloaded and index.token==token
            and map.Parent==workspace do
            local deadline=os.clock()+.002
            local batch=0
            while head<=#queue and batch<240 and os.clock()<deadline do
                local node=queue[head]
                queue[head]=false
                head+=1
                batch+=1
                if node:IsA('Model') then
                    local name=node.Name:lower()
                    if name=='generator' or name:find('generator',1,true) then
                        local root=H.generatorRoot(node)
                        if root then
                            objectiveCandidates.Generators[root]=true
                            if S.Generators then mark(root,'Generators',root) end
                        end
                    elseif name=='hook' or H.isHookName(node.Name) then
                        local root=H.hookRoot(node)
                        if root then
                            objectiveCandidates.Hooks[root]=true
                            if S.Hooks then mark(root,'Hooks',root) end
                        end
                    elseif S.Pallets and (
                        name:find('pallet',1,true)~=nil
                        or name=='intact'
                        or (node.Parent and node.Parent.Name:lower()=='pallets')
                        or node:FindFirstChild('Intact')) then
                        local root=H.getPalletModel(node)
                        if root and H.anyPart(root) then palletCandidates[root]=true end
                    end
                end
                for _,child in ipairs(node:GetChildren()) do
                    if child:IsA('Folder') or child:IsA('Model') then
                        queue[#queue+1]=child
                    end
                end
            end
            task.wait()
        end
        if index.token==token then
            index.running=false
            if S.Pallets then updatePallets() end
        end
    end)
end

local function clearESP()
for p in pairs(playerFX) do H.clearPlayer(p) end
H.clearAllNPCs()
local roots={}
for root in pairs(objectFX) do roots[#roots+1]=root end
for _,root in ipairs(roots) do removeObject(root) end
for root in pairs(palletHighlights) do removePalletMarker(root) end
for root in pairs(H.vaultState.highlights) do H.removeVaultMarker(root) end
H.vaultState.candidates={}
for root in pairs(H.gateState.highlights) do H.removeGate(root) end
H.gateState.candidates={}; H.gateState.generators={}
for root in pairs(H.pumpkinState.highlights) do H.removePumpkin(root) end
H.pumpkinState.candidates={}
palletCandidates={};palletPromptRoots={}
objectiveCandidates={Hooks={},Generators={}}
for root in pairs(genBars) do destroyGenBar(root) end
end
local scanQueue, scanHead, scanTail, queued = {},1,0,{}
local function enqueue(o)
if unloaded or not o or queued[o] then return end
queued[o]=true
scanTail+=1
scanQueue[scanTail]=o
end
local lastSharedScanAt=-100
local function scan()
    if not H.vaultRoundActive() then return end
    -- Known objective folders use H.fastIndexKnown() directly. A costly
    -- full-map fallback is reserved for uncategorized traps/pumpkins.
    if H.fastIndexKnown then H.fastIndexKnown() end
    if not (S.Traps or S.Pumpkins) then
        -- Clear any old broad scan queued by another version/toggle.
        scanQueue,scanHead,scanTail,queued={},1,0,{}
        return
    end
    local map=workspace:FindFirstChild('Map')
    if not map or (scanHead<=scanTail and os.clock()-lastSharedScanAt<1) then return end
    lastSharedScanAt=os.clock()
    enqueue(map)
end
H.scheduleFullScan=scan
local function processQueue()
if not H.vaultRoundActive() then return end
if not (S.Hooks or S.Generators or S.Pallets or S.Vaults or S.ExitGates or S.Traps or S.Pumpkins) then return end
-- Many small batches are smoother than one giant GetDescendants().
-- Budget by both count AND actual elapsed time to protect low-end PCs.
local budget=100
local deadline=os.clock()+.0015
local inspectedAnything=false
while budget>0 and scanHead<=scanTail do
if os.clock()>deadline then break end
local o=scanQueue[scanHead]
scanQueue[scanHead]=nil
scanHead+=1
budget-=1
queued[o]=nil
if o and (o==workspace or o:IsDescendantOf(workspace)) then
-- Most map geometry is unrelated to objectives. Avoid the expensive
-- character/attribute checks on plain scenery while retaining tagged objects.
local name=o.Name:lower()
local relevant=name:find('hook',1,true) or name:find('gen',1,true)
    or name:find('pallet',1,true)
    or (S.Pallets and o.Parent and o.Parent.Name=='Pallets'
        and (o.Parent.Parent==workspace:FindFirstChild('Map')
            or (o.Parent.Parent and o.Parent.Parent.Name=='resources'
                and o.Parent.Parent.Parent==workspace:FindFirstChild('Map'))))
    or name:find('window',1,true)
    or name:find('vault',1,true) or name:find('gate',1,true)
    or name:find('lever',1,true) or name:find('trap',1,true)
    or name:find('pumpkin',1,true) or name:find('bottom',1,true)
    or o:IsA('ProximityPrompt')
if relevant and (H.physical(o) or o:IsA('ProximityPrompt')) then
    inspect(o)
    inspectedAnything=true
end
for _,child in ipairs(o:GetChildren()) do enqueue(child) end
end
end
if scanHead>scanTail then
scanQueue,scanHead,scanTail,queued={},1,0,{}
end
if H.palletRefreshRequested and S.Pallets
    and os.clock()-(H.lastFastPalletUpdate or 0)>.22 then
    H.lastFastPalletUpdate=os.clock()
    H.palletRefreshRequested=false
    updatePallets()
end
if inspectedAnything and os.clock()-(H.lastFastOtherUpdate or 0)>.5 then
    H.lastFastOtherUpdate=os.clock()
    if S.Vaults then H.updateVaults() end
    if S.ExitGates then H.updateGates() end
    if S.Pumpkins then H.updatePumpkins() end
end
end
local function toggleObjectiveCategory(key,value)
if value and not H.vaultRoundActive() then return end
if key=='Vaults' then
    H.toggleVaults(value)
    return
end
if key=='ExitGates' then
    H.toggleGates(value)
    return
end
if key=='Pumpkins' then
    H.togglePumpkins(value)
    return
end
if key=='Pallets' then
if value then
    palletLastVisible=-1
    discoverPallets()
    if H.indexEntireMapOnce then H.indexEntireMapOnce(true) end
    updatePallets()
else
    palletScanToken+=1 -- cancel an in-progress discovery scan
    setPalletPoolVisible(false)
    for root in pairs(palletHighlights) do removePalletMarker(root) end
    palletCandidates={};palletPromptRoots={}
    palletLastVisible=-1
end
return
end
if (key=='Hooks' or key=='Generators') and not value then
    objectiveCandidates[key]={}
end
if not value then
local roots={}
for root,r in pairs(objectFX) do
if r.kind==key then roots[#roots+1]=root end
end
for _,root in ipairs(roots) do removeObject(root) end
else
    if H.fastIndexKnown then H.fastIndexKnown() end
    if (key=='Hooks' or key=='Generators' or key=='Pallets')
        and H.indexEntireMapOnce then H.indexEntireMapOnce(true) end
    if key=='Traps' or key=='Pumpkins' then scan() end
end
end
local function findSkillCheck()
local prompt=PG:FindFirstChild("SkillCheckPromptGui")
if not prompt then return end
local check=prompt:FindFirstChild("Check",true)
if not check or not check:IsA("GuiObject") then return end
local line=check:FindFirstChild("Line",true)
local gr=check:FindFirstChild("Goal",true)
if line and gr and line:IsA("GuiObject") and gr:IsA("GuiObject") then
return check,line,gr
end
end
-- V68: Chat-safe skill-check input. The previous SendKeyEvent path could
-- report success while chat still swallowed Space; prioritize real input
-- capable backends and restore chat only AFTER keyup. No double taps.
local spaceInFlight=false
local function sendSpace()
    if spaceInFlight or unloaded then return false end
    local focused=UIS:GetFocusedTextBox()
    local hadChat=focused~=nil and focused.Parent~=nil
    local preservedText=hadChat and focused:IsA('TextBox') and focused.Text or nil
    local function restoreChat()
        if unloaded or not hadChat or not focused.Parent then return end
        if UIS:GetFocusedTextBox()==nil then
            pcall(function()
                if preservedText~=nil and focused.Text~=preservedText then
                    focused.Text=preservedText
                end
                focused:CaptureFocus()
            end)
        end
    end
    if hadChat then
        pcall(function() focused:ReleaseFocus(false) end)
    end
    -- In your own Roblox game, let the existing skill-check LocalScript
    -- register this callback and use its normal success-validation path.
    -- Unlike a keyboard injection this callback also works out of focus.
    if type(env.__OronaSkillCheckActivate)=='function' then
        local ok,didFire=pcall(env.__OronaSkillCheckActivate)
        if ok and didFire~=false then
            if hadChat then task.defer(restoreChat) end
            return true
        end
    end
    local event=PG:FindFirstChild('OronaSkillCheckAction')
    if not event and H.repStorage then
        event=H.repStorage:FindFirstChild('OronaSkillCheckAction')
    end
    if event and event:IsA('BindableEvent') then
        local ok=pcall(function() event:Fire() end)
        if ok then
            if hadChat then task.defer(restoreChat) end
            return true
        end
    end
    local pressed,release=false,nil
    -- When Roblox loses focus, OS-level keypress targets another app.
    -- Prefer Roblox-directed VIM even in the background; only use a raw
    -- system key event while Roblox is the focused window.
    local function tryRobloxInput()
        local ok,vim=pcall(function()
            return game:GetService('VirtualInputManager')
        end)
        if not ok or not vim then return false end
        local success=pcall(function()
            vim:SendKeyEvent(true,Enum.KeyCode.Space,false,game)
        end)
        if success then
            release=function()
                pcall(function()
                    vim:SendKeyEvent(false,Enum.KeyCode.Space,false,game)
                end)
            end
        end
        return success
    end
    if not robloxHasFocus then pressed=tryRobloxInput() end
    if not pressed and robloxHasFocus
        and type(keypress)=='function' and type(keyrelease)=='function' then
        pressed=pcall(function() keypress(0x20) end)
        if pressed then
            release=function() pcall(function() keyrelease(0x20) end) end
        end
    end
    if not pressed and robloxHasFocus then pressed=tryRobloxInput() end
    if not pressed then
        if hadChat then task.defer(restoreChat) end
        return false
    end
    spaceInFlight=true
    task.delay(.038,function()
        if release then release() end
        spaceInFlight=false
        -- Longer than the old 45ms focus hand-back: do not let chat
        -- recapture Space during the skill-check's key-release frame.
        if hadChat then task.delay(.09,restoreChat) end
    end)
    return true
end

local lastSkillPress=0
local skillArmed=true
local previousGoal=nil
local lastSkillFrameAt=nil
-- V48: detect trap context without affecting heal/generator timing.
H.trapSkill={visibleSince=0,lastVisible=false,stableFrames=0,previousAngle=nil,
    trapLatched=false,observedOutside=false,movementFrames=0,lowAngle=false}
function H.trapCheckContext()
    local char=Me.Character
    local flags={'Trapped','IsTrapped','InTrap','CaughtInTrap','BearTrapped',
        'IsCaught','InBearTrap','IsInTrap','InBeartrap'}
    for _,obj in ipairs({Me,char}) do
        if obj then
            for _,flag in ipairs(flags) do
                if obj:GetAttribute(flag)==true then return true end
            end
            local state=obj:GetAttribute('State') or obj:GetAttribute('Status')
            if type(state)=='string' then
                local n=state:lower()
                if n:find('trap',1,true) or n:find('snare',1,true) then return true end
            end
        end
    end
    -- Some variants use a separate trap-themed skillcheck GUI.
    if skillCheck then
        local gui=skillCheck:FindFirstAncestorOfClass('ScreenGui')
        if gui and (gui.Name:lower():find('trap',1,true)) then return true end
        local context=skillCheck:GetAttribute('Type') or skillCheck:GetAttribute('Action')
        if type(context)=='string' and context:lower():find('trap',1,true) then
            return true
        end
    end
    -- Many trap-escape checks don't expose a named GUI or character flag.
    -- As a fallback, inspect nearby trap geometry only while a check is
    -- visible and movement is restricted. Cache for 0.18s to avoid lag.
    if char then
        local hum=char:FindFirstChildOfClass('Humanoid')
        local root=char:FindFirstChild('HumanoidRootPart')
        if hum and root then
            local ts=H.trapSkill
            local now=os.clock()
            if not ts.nearChecked or now-ts.nearChecked>.35 then
                ts.nearChecked=now
                ts.nearTrap=false
                local ok,parts=pcall(function()
                    return workspace:GetPartBoundsInRadius(root.Position,5.5)
                end)
                if ok then
                    for _,part in ipairs(parts) do
                        local node=part
                        for _=1,4 do
                            if not node or node==workspace then break end
                            local name=node.Name:lower():gsub('[%s_%-]','')
                            if name:find('beartrap',1,true)
                                or name:find('steeltrap',1,true)
                                or name=='placedtrap' or name=='trap' then
                                ts.nearTrap=true
                                break
                            end
                            node=node.Parent
                        end
                        if ts.nearTrap then break end
                    end
                end
            end
            if ts.nearTrap then return true end
        end
    end
    return false
end
local function autoFrame()
if unloaded or not S.AutoGen then return end
if not skillCheck or not skillCheck:IsDescendantOf(PG)
or not needle or not goal then
if os.clock()>=autoSearchAt then
autoSearchAt=os.clock()+.25
skillCheck,needle,goal=findSkillCheck()
previousSkillAngle=nil
previousGoal=nil
skillArmed=true
end
return
end
local prompt=skillCheck:FindFirstAncestorOfClass('ScreenGui')
local visible=skillCheck.Visible and (not prompt or prompt.Enabled)
if not visible then
skillArmed=true; previousSkillAngle=nil; previousGoal=nil
lastSkillFrameAt=nil
H.trapSkill.lastVisible=false
H.trapSkill.stableFrames=0
H.trapSkill.previousAngle=nil
H.trapSkill.trapLatched=false
H.trapSkill.observedOutside=false
H.trapSkill.movementFrames=0
H.trapSkill.lowAngle=false
return
end
local role=Me.Team
if role and H.contains(role.Name,'killer') then return end
local angle=(needle.Rotation-goal.Rotation)%360
local goalRot=goal.Rotation
local now=os.clock()
local sampleGap=lastSkillFrameAt and math.min(0.35,now-lastSkillFrameAt) or .016
lastSkillFrameAt=now
local trapState=H.trapSkill
if not trapState.lastVisible then
    trapState.visibleSince=now
    trapState.lastVisible=true
    trapState.stableFrames=0
    trapState.previousAngle=nil
    trapState.trapLatched=false
    trapState.observedOutside=false
    trapState.movementFrames=0
    trapState.lowAngle=false
end
if previousGoal and math.abs(goalRot-previousGoal)>4 then
skillArmed=true; previousSkillAngle=nil
end
previousGoal=goalRot
if not skillArmed and (angle<93 or angle>125)
and now-lastSkillPress>.12 then
skillArmed=true
end
local crossed=previousSkillAngle~=nil
and previousSkillAngle<109 and angle>=109
and (angle-previousSkillAngle)<math.max(30,math.min(95,sampleGap*420))
local center=angle>=106 and angle<=112
previousSkillAngle=angle
-- Trap checks can use a different visible needle motion. Never use the
-- long crossing shortcut on traps: a rotation jump may falsely count as
-- crossing the white region before the needle actually gets there.
local trapCheck=H.trapCheckContext()
if trapCheck then trapState.trapLatched=true end
local shouldPress=center or crossed
if trapState.trapLatched then
    -- A trap often opens at a needle angle that looks like the generator
    -- white zone during its entrance animation. Do not send input until a
    -- genuine clockwise sweep FROM OUTSIDE the zone has been observed.
    local prior=trapState.previousAngle
    local advancing=prior~=nil and angle>prior and angle-prior<=18
    if angle<96 or angle>127 then trapState.observedOutside=true end
    if angle<96 then trapState.lowAngle=true end
    trapState.movementFrames=advancing and trapState.movementFrames+1 or 0
    local inWhite=(angle>=107 and angle<=114)
    trapState.stableFrames=(inWhite and advancing)
        and (trapState.stableFrames+1) or 0
    shouldPress=trapState.observedOutside and trapState.lowAngle
        and trapState.movementFrames>=2 and trapState.stableFrames>=2
        and now-trapState.visibleSince>=.30
else
    trapState.stableFrames=0
end
trapState.previousAngle=angle
if skillArmed and shouldPress
and now-lastSkillPress>.14 then
skillArmed=false
lastSkillPress=now
if not sendSpace() and not lastAutoFailure then
warn('Orona Auto Skill Check: Roblox-directed input is unavailable; out-of-focus presses require a game-side skill-check event')
lastAutoFailure=true
end
end
end
local function setAutoGen(value)
S.AutoGen=value
autoFired=false
previousSkillAngle=nil
previousGoal=nil
lastSkillFrameAt=nil
skillArmed=true
H.trapSkill.lastVisible=false
H.trapSkill.stableFrames=0
H.trapSkill.previousAngle=nil
H.trapSkill.trapLatched=false
H.trapSkill.observedOutside=false
H.trapSkill.movementFrames=0
H.trapSkill.lowAngle=false
lastAutoFailure=false
if autoConnection then autoConnection:Disconnect(); autoConnection=nil end
if value and not unloaded then
skillCheck,needle,goal=findSkillCheck()
-- Heartbeat continues to run when graphics rendering is not foreground.
-- Roblox may still throttle a minimized client; background VIM support is
-- executor/client-dependent, so this is best-effort rather than a guarantee.
autoConnection=RS.Heartbeat:Connect(autoFrame)
end
end

-- V66: Integrated standalone V4 body-turn A/D Moonwalk; all Kitty UI stays intact.
-- Hold Middle Mouse (rebindable in the existing Orona menu).
-- A 55ms / 5ms gap / D 55ms / 5ms gap, 36 degree rotation, 65% side movement.
-- Backward travel follows the camera yaw while keeping the 36-degree body sway; scripted flashlight aiming does not steal the heading.
-- Do not make a second GUI or install a second movement script alongside this one.
local moonKey=Enum.UserInputType.MouseButton3
local choosingMoonKey=false
local moonHeld=false
local aimHeld=false
local moonHum=nil
H.mw={
    aTime=.055, gapA=.005, dTime=.055, gapD=.005,
    bodyTurnDegrees=36, sideWeight=.65, backwardWeight=1,
    turnResponse=55, cameraFollow=true, cameraFollowResponse=17,
    renderName='OronaMoonwalkV67',
    token=0, baseFacing=nil, lastCameraYaw=nil,
    cameraYawOffset=nil, aimWasDrivingCamera=false, startedAt=0,
    originalAutoRotate=nil, startingSpeed=nil, sprintTarget=nil,
    speedChanged=false, observedWalkSpeed=nil, observedSprintSpeed=nil,
    observedSprintHum=nil, observedSprintAt=0,
    sprintBackend=nil, shiftInjected=false, pulseKey=nil
}

local function mwFlatYaw(vector)
    local flat=Vector3.new(vector.X,0,vector.Z)
    if flat.Magnitude < .001 then return nil end
    return math.atan2(-flat.X,-flat.Z)
end
local function mwAngleDelta(angle)
    return math.atan2(math.sin(angle),math.cos(angle))
end

-- Synthetic keys are optional: ordinary Roblox LocalScripts cannot send physical
-- keyboard events. The body-turn and movement work using Humanoid:Move regardless.
function H.mwPulseRelease()
    if H.mw.pulseKey and type(keyrelease)=='function' then
        pcall(keyrelease,H.mw.pulseKey)
    end
    H.mw.pulseKey=nil
end
function H.mwSprintInput(pressed,force)
    if pressed then
        if H.mw.shiftInjected and not force then return end
        if UIS:IsKeyDown(Enum.KeyCode.LeftShift) and not force then return end
        local ok=pcall(function()
            game:GetService('VirtualInputManager'):SendKeyEvent(
                true,Enum.KeyCode.LeftShift,false,game)
        end)
        if ok then
            H.mw.shiftInjected=true
            H.mw.sprintBackend='vim'
            return
        end
        if type(keypress)=='function' then
            local sent=pcall(keypress,0xA0)
            if sent then
                H.mw.shiftInjected=true
                H.mw.sprintBackend='key'
            end
        end
    elseif H.mw.shiftInjected then
        if H.mw.sprintBackend=='vim' then
            pcall(function()
                game:GetService('VirtualInputManager'):SendKeyEvent(
                    false,Enum.KeyCode.LeftShift,false,game)
            end)
        elseif H.mw.sprintBackend=='key' and type(keyrelease)=='function' then
            pcall(keyrelease,0xA0)
        end
        H.mw.shiftInjected=false
        H.mw.sprintBackend=nil
    end
end
function H.mwSendPulses(token)
    if type(keypress)~='function' or type(keyrelease)~='function' then return end
    task.spawn(function()
        while not unloaded and moonHeld and H.mw.token==token do
            H.mw.pulseKey=0x41
            pcall(keypress,0x41)
            task.wait(H.mw.aTime)
            if unloaded or not moonHeld or H.mw.token~=token then break end
            H.mwPulseRelease()
            task.wait(H.mw.gapA)
            if unloaded or not moonHeld or H.mw.token~=token then break end
            H.mw.pulseKey=0x44
            pcall(keypress,0x44)
            task.wait(H.mw.dTime)
            if unloaded or not moonHeld or H.mw.token~=token then break end
            H.mwPulseRelease()
            task.wait(H.mw.gapD)
        end
        if H.mw.token==token then H.mwPulseRelease() end
    end)
end
local function finishMoonwalk()
    H.mw.token+=1 -- cancels any ongoing A/D pulse coroutine
    H.mwPulseRelease()
    H.mwSprintInput(false)
    if moonHum and moonHum.Parent then
        pcall(function() moonHum:Move(Vector3.zero,false) end)
        if H.mw.originalAutoRotate~=nil then
            moonHum.AutoRotate=H.mw.originalAutoRotate
        end
        if H.mw.speedChanged and H.mw.sprintTarget and H.mw.startingSpeed
           and math.abs(moonHum.WalkSpeed-H.mw.sprintTarget)<.2
           and not UIS:IsKeyDown(Enum.KeyCode.LeftShift) then
            moonHum.WalkSpeed=H.mw.startingSpeed
        end
    end
    moonHeld=false
    moonHum=nil
    H.mw.baseFacing=nil
    H.mw.lastCameraYaw=nil
    H.mw.cameraYawOffset=nil
    H.mw.aimWasDrivingCamera=false
    H.mw.originalAutoRotate=nil
    H.mw.sprintTarget=nil
    H.mw.startingSpeed=nil
    H.mw.speedChanged=false
end
local function moonInputDown()
    if not moonKey or typeof(moonKey)~='EnumItem' then return false end
    if moonKey.EnumType==Enum.KeyCode then
        return UIS:IsKeyDown(moonKey)
    elseif moonKey.EnumType==Enum.UserInputType then
        if moonKey==Enum.UserInputType.MouseButton1
          or moonKey==Enum.UserInputType.MouseButton2
          or moonKey==Enum.UserInputType.MouseButton3 then
            return UIS:IsMouseButtonPressed(moonKey)
        end
    end
    return false
end
local function startMoonwalk(hum,root,camera)
    if moonHeld and moonHum==hum then return end
    finishMoonwalk()
    moonHeld=true
    moonHum=hum
    H.mw.originalAutoRotate=hum.AutoRotate
    H.mw.startingSpeed=hum.WalkSpeed
    local look=root.CFrame.LookVector
    local horizontal=Vector3.new(look.X,0,look.Z)
    H.mw.baseFacing=horizontal.Magnitude>.001 and horizontal.Unit or Vector3.new(0,0,-1)
    H.mw.lastCameraYaw=mwFlatYaw(camera.CFrame.LookVector)
    -- Keep the same camera-to-body facing offset when Moonwalk starts. Turning
    -- the camera then redirects the backward movement without snapping your body.
    local initialFacingYaw=mwFlatYaw(H.mw.baseFacing) or 0
    H.mw.cameraYawOffset=H.mw.lastCameraYaw
        and mwAngleDelta(initialFacingYaw-H.mw.lastCameraYaw) or 0
    H.mw.aimWasDrivingCamera=false
    H.mw.startedAt=os.clock()
    local recentlyObserved=(H.mw.observedSprintHum==hum
         and os.clock()-H.mw.observedSprintAt<15)
    if recentlyObserved and H.mw.observedSprintSpeed
         and H.mw.observedSprintSpeed>H.mw.startingSpeed+.05 then
        H.mw.sprintTarget=H.mw.observedSprintSpeed
    elseif UIS:IsKeyDown(Enum.KeyCode.LeftShift) then
        -- Already sprinting: treat this current speed as the upper bound.
        H.mw.sprintTarget=hum.WalkSpeed
    else
        H.mw.sprintTarget=nil -- Never invent a faster WalkSpeed.
    end
    H.mw.speedChanged=false
    hum.AutoRotate=false
    H.mw.token+=1
    H.mwSendPulses(H.mw.token)
    H.mwSprintInput(true)
end
-- Physical Shift released during a moonwalk must not cancel synthetic Shift.
H.con(UIS.InputEnded,function(input)
    if input.KeyCode==Enum.KeyCode.LeftShift and moonHeld and S.Moonwalk then
        task.defer(function()
            if not unloaded and moonHeld and S.Moonwalk then
                H.mwSprintInput(true,true)
            end
        end)
    end
end)

-- Flashlight: detect the *equipped* item in the character, rather
-- than any flashlight left in the Backpack. Game items can be Tools,
-- character Models, or attached parts with light emitters.
local function hasFlashlight()
    local char=Me.Character
    if not char then return false end
    local function flashlightMarker(obj)
        local n=obj.Name:lower():gsub('[%s_%-]','')
        return n:find('flashlight',1,true)~=nil
            or n:find('torch',1,true)~=nil
            or obj:GetAttribute('IsFlashlight')==true
            or obj:GetAttribute('EquippedFlashlight')==true
    end
    for _,obj in ipairs(char:GetChildren()) do
        if (obj:IsA('Tool') or obj:IsA('Model') or obj:IsA('BasePart'))
            and (flashlightMarker(obj)
                or (obj:IsA('Tool') and (
                    obj:FindFirstChildWhichIsA('SpotLight',true)
                    or obj:FindFirstChildWhichIsA('SurfaceLight',true)))) then
            return true
        end
    end
    if char:GetAttribute('FlashlightEquipped')==true then return true end
    return false
end
-- The dark-kitty icon and aim assist share the same H.isKiller() check.
-- V39: assist only when you are already LOOKING toward the killer.
local AIM_RANGE=75                -- studs, no across-the-map locking
local AIM_ACQUIRE_ANGLE=7         -- degrees from actual camera forward
local AIM_KEEP_ANGLE=10          -- a little tolerance while tracking
local AIM_SCREEN_FRACTION=.13    -- target near screen center, any resolution
local AIM_SMOOTH_SPEED=13        -- natural eased correction, not instant snap
-- Flashlight origin: where the actual light comes from.  Third-person
-- cameras are offset from the character, so camera-at-head can miss.
local function flashlightOrigin()
    local char=Me.Character
    if not char then return nil end
    for _,obj in ipairs(char:GetChildren()) do
        if obj:IsA('Tool') or obj:IsA('Model') then
            local n=obj.Name:lower():gsub('[%s_%-]','')
            local marked=n:find('flashlight',1,true)~=nil
                or n:find('torch',1,true)~=nil
                or obj:GetAttribute('IsFlashlight')==true
            local light=obj:FindFirstChildWhichIsA('SpotLight',true)
            if marked or light then
                if light then
                    local par=light.Parent
                    if par:IsA('Attachment') then
                        return par.WorldPosition
                    elseif par:IsA('BasePart') then
                        return par.Position
                    end
                end
                local handle=obj:FindFirstChild('Handle',true)
                if handle and handle:IsA('BasePart') then
                    return handle.Position
                end
            end
        end
    end
    local hand=char:FindFirstChild('RightHand') or char:FindFirstChild('Right Arm')
    return hand and hand:IsA('BasePart') and hand.Position or nil
end

local function faceAimPoint(head)
    -- The flashlight must shine at the FRONT of the killer's face.
    -- Head forward is face direction on ordinary Roblox rigs.
    local face=head:FindFirstChild("FaceFrontAttachment")
    if face and face:IsA("Attachment") then
        return face.WorldPosition
    end
    return head.Position + head.CFrame.LookVector * math.min(.35,head.Size.Z*.28)
end

local function flashlightAimPoint(cam,head)
    local target=faceAimPoint(head)
    local origin=flashlightOrigin()
    if not origin then return target end
    -- Compensate only for screen-plane camera/flashlight parallax.
    -- Including the full camera-behind-player distance overcorrects.
    local difference=cam.CFrame.Position-origin
    local lateral=cam.CFrame.RightVector*difference:Dot(cam.CFrame.RightVector)
        + cam.CFrame.UpVector*difference:Dot(cam.CFrame.UpVector)
    if lateral.Magnitude>3 then
        lateral=lateral.Unit*3
    end
    return target+lateral
end

local lockedHead=nil
-- The flashlight cannot target a player behind scenery or well outside the
-- part of the screen you are pointing at. Ignore only our character and the
-- target character during the raycast (so we test the actual intervening map).
local aimRayParams=RaycastParams.new()
aimRayParams.FilterType=Enum.RaycastFilterType.Exclude
aimRayParams.IgnoreWater=true
local function flashlightClearSight(head,cam)
    local origin=flashlightOrigin() or cam.CFrame.Position
    local target=faceAimPoint(head)
    local direction=target-origin
    if direction.Magnitude<.01 then return false end
    local ignore={}
    if Me.Character then table.insert(ignore,Me.Character) end
    if head.Parent then table.insert(ignore,head.Parent) end
    aimRayParams.FilterDescendantsInstances=ignore
    return workspace:Raycast(origin,direction,aimRayParams)==nil
end

local function validKillerHead(head,cam,acquiring)
    if not head or not head:IsA('BasePart')
        or not head:IsDescendantOf(workspace) then return false end
    local p=Players:GetPlayerFromCharacter(head.Parent)
    if not p or p==Me or not H.isKiller(p) then return false end
    local target=faceAimPoint(head)
    local delta=target-cam.CFrame.Position
    local distance=delta.Magnitude
    if distance>AIM_RANGE or distance<.1 then return false end

    -- Check the ACTUAL current direction, not merely that the killer is
    -- somewhere on-screen. A very wide FOV must not enable side targets.
    local cone=acquiring and AIM_ACQUIRE_ANGLE or AIM_KEEP_ANGLE
    if cam.CFrame.LookVector:Dot(delta.Unit)<math.cos(math.rad(cone)) then
        return false
    end
    local pixel,onScreen=cam:WorldToViewportPoint(target)
    if not onScreen or pixel.Z<=0 then return false end
    local center=cam.ViewportSize*.5
    local offset=(Vector2.new(pixel.X,pixel.Y)-center).Magnitude
    if offset>math.min(cam.ViewportSize.X,cam.ViewportSize.Y)*AIM_SCREEN_FRACTION then
        return false
    end
    if not flashlightClearSight(head,cam) then return false end
    return true
end

local function nearestKillerHead(cam)
    local center=cam.ViewportSize*.5
    local target=nil
    local closest=math.huge
    for _,p in ipairs(Players:GetPlayers()) do
        if p~=Me and H.isKiller(p) and p.Character then
            local head=p.Character:FindFirstChild('Head')
            if validKillerHead(head,cam,true) then
                local point=cam:WorldToViewportPoint(faceAimPoint(head))
                local distance=(Vector2.new(point.X,point.Y)-center).Magnitude
                if distance<closest then closest=distance;target=head end
            end
        end
    end
    return target
end
-- V47 firearm assist: aim at the torso (NOT the head), when a gun is equipped.
-- This follows the same hold-right-mouse and forward-cone approach as the flashlight.
function H.hasEquippedGun()
    local char=Me.Character
    if not char then return false end
    if char:GetAttribute('GunEquipped')==true or Me:GetAttribute('GunEquipped')==true then
        return true
    end
    for _,obj in ipairs(char:GetChildren()) do
        if obj:IsA('Tool') or obj:IsA('Model') then
            local name=obj.Name:lower():gsub('[%s_%-%(%)]','')
            if not name:find('flashlight',1,true) and not name:find('torch',1,true) then
                local gunName=name:find('gun',1,true) or name:find('pistol',1,true)
                    or name:find('rifle',1,true) or name:find('revolver',1,true)
                    or name:find('shotgun',1,true) or name:find('smg',1,true)
                    or name:find('musket',1,true) or name:find('blaster',1,true)
                    or name:find('handcannon',1,true)
                local attr=(obj:GetAttribute('IsGun')==true
                    or obj:GetAttribute('Firearm')==true
                    or obj:GetAttribute('Ammo')~=nil
                    or obj:GetAttribute('Magazine')~=nil
                    or obj:GetAttribute('Bullets')~=nil)
                if gunName or attr then return true end
            end
        end
    end
    return false
end
H.GUN_RANGE=145
H.GUN_ACQUIRE_ANGLE=7
H.GUN_KEEP_ANGLE=11
H.gunLockedTorso=nil
H.gunRayParams=RaycastParams.new()
H.gunRayParams.FilterType=Enum.RaycastFilterType.Exclude
 H.gunRayParams.IgnoreWater=true
function H.torsoOfKiller(p)
    if p==Me or not H.isKiller(p) or not p.Character then return nil end
    local char=p.Character
    return char:FindFirstChild('UpperTorso') or char:FindFirstChild('Torso')
        or char:FindFirstChild('HumanoidRootPart')
end
function H.validGunTorso(part,cam,acquiring)
    if not part or not part:IsA('BasePart') or not part:IsDescendantOf(workspace) then return false end
    local character=part.Parent
    local player=Players:GetPlayerFromCharacter(character)
    if not player or player==Me or not H.isKiller(player) then return false end
    local delta=part.Position-cam.CFrame.Position
    local d=delta.Magnitude
    if d<.15 or d>H.GUN_RANGE then return false end
    local angle=acquiring and H.GUN_ACQUIRE_ANGLE or H.GUN_KEEP_ANGLE
    if cam.CFrame.LookVector:Dot(delta.Unit)<math.cos(math.rad(angle)) then return false end
    local pixel,onScreen=cam:WorldToViewportPoint(part.Position)
    if not onScreen or pixel.Z<=0 then return false end
    local center=cam.ViewportSize*.5
    if (Vector2.new(pixel.X,pixel.Y)-center).Magnitude>math.min(center.X,center.Y)*.24 then
        return false
    end
    local ignore={}
    if Me.Character then ignore[#ignore+1]=Me.Character end
    ignore[#ignore+1]=character
    H.gunRayParams.FilterDescendantsInstances=ignore
    return workspace:Raycast(cam.CFrame.Position,delta,H.gunRayParams)==nil
end
function H.nearestGunTorso(cam)
    local closest=nil
    local best=math.huge
    local center=cam.ViewportSize*.5
    for _,p in ipairs(Players:GetPlayers()) do
        local torso=H.torsoOfKiller(p)
        if torso and H.validGunTorso(torso,cam,true) then
            local screen=cam:WorldToViewportPoint(torso.Position)
            local dist=(Vector2.new(screen.X,screen.Y)-center).Magnitude
            if dist<best then best=dist;closest=torso end
        end
    end
    return closest
end

-- ===== V74: AUTO PARRY (NEED DAGGER) =====
-- A local, evidence-based detector; the killer's raw mouse input is not replicated.
-- Uses replicated attack animations, their hit/release markers, and/or explicit
-- attack-state attributes. Only acts with a Parry Dagger actually equipped.
-- Your own game can provide AttackActive / IsCharging / IsLunging attributes
-- or name/tag its attack animations to improve timing and coverage.
H.parry = {
    attackers={}, attacks={}, activeStates={}, seenTracks=setmetatable({},{__mode='k'}),
    trackWatches=setmetatable({},{__mode='k'}), active=false, clock=0,
    watchClock=0, lastParry=0, warnedInput=false, nextSequence=0,
    debug=true,
    -- Add animation IDs from your own killer animations if their names are generic.
    animationIds={},
    range=7.0, lungeRange=10.5, cooldown=0.80
}

function H.parry.weaponName(obj)
    if not obj then return false end
    if obj:GetAttribute('IsParryDagger')==true
        or obj:GetAttribute('CanParry')==true
        or obj:GetAttribute('ParryEnabled')==true then return true end
    local n=obj.Name:lower():gsub('[%s_%-%(%)]','')
    return n=='parrydagger' or n=='daggerparry' or n=='dagger'
        or n=='weapons' or n=='weapon' or n=='parryingdagger'
end
function H.parry.dagger()
    local char=Me.Character
    if not char then return nil end
    -- Must actually be equipped or mounted in Character, not Backpack.
    for _,obj in ipairs(char:GetChildren()) do
        if (obj:IsA('Tool') or obj:IsA('Model')) and
            H.parry.weaponName(obj) then return obj end
        if (obj:IsA('Folder') or obj:IsA('Model')) and
            obj.Name:lower():find('weapon',1,true) then
            for _,item in ipairs(obj:GetChildren()) do
                if (item:IsA('Tool') or item:IsA('Model'))
                    and H.parry.weaponName(item) then return item end
            end
        end
    end
    return nil
end

function H.parry.killer(p)
    if p==Me or not p.Character then return false end
    if H.isKiller(p) then return true end
    local char=p.Character
    local role=char:GetAttribute('Role')
    if char:GetAttribute('IsKiller')==true or
        (type(role)=='string' and role:lower()=='killer') then return true end
    if Me.Team and p.Team and p.Team==Me.Team then return false end
    -- Some games do not replicate the role attribute. Still observe attack
    -- tracks for opposing players, but only react to actual attack evidence.
    local theirRole=p:GetAttribute('Role') or char:GetAttribute('Role')
    if type(theirRole)=='string' and
        (theirRole:lower()=='survivor' or theirRole:lower()=='runner') then
        return false
    end
    return true
end

function H.parry.attribute(obj,name)
    if not obj then return nil end
    local val=obj:GetAttribute(name)
    if val~=nil then return val end
    local child=obj:FindFirstChild(name)
    if child and child:IsA('ValueBase') then return child.Value end
    return nil
end

function H.parry.readAttackState(p)
    local char=p.Character
    local active,charging,lunge=false,false,false
    local sources={p,char}
    if char then
        for _,child in ipairs(char:GetChildren()) do
            if child:IsA('Tool') or (child:IsA('Model')
                and (child.Name:lower():find('weapon',1,true)
                    or child.Name:lower():find('knife',1,true))) then
                sources[#sources+1]=child
            end
        end
    end
    for _,node in ipairs(sources) do
        if node then
            for _,key in ipairs({'Swinging','IsSwinging','AttackActive',
                'IsAttacking','Attacking','HitActive','IsHitting','AttackReleased'}) do
                if H.parry.attribute(node,key)==true then active=true end
            end
            for _,key in ipairs({'Charging','IsCharging','ChargeHeld',
                'HoldingAttack','WindingUp','IsWindingUp'}) do
                if H.parry.attribute(node,key)==true then charging=true end
            end
            for _,key in ipairs({'IsLunging','Lunging','LungeActive'}) do
                if H.parry.attribute(node,key)==true then lunge=true;active=true end
            end
            local state=H.parry.attribute(node,'AttackState')
                or H.parry.attribute(node,'CombatState')
            if type(state)=='string' then
                state=state:lower()
                if state:find('charge',1,true) or state:find('windup',1,true)
                    or state:find('hold',1,true) then charging=true end
                if state:find('swing',1,true) or state:find('strike',1,true)
                    or state:find('release',1,true) or state:find('lunge',1,true)
                    or state:find('hit',1,true) then active=true end
                if state:find('lunge',1,true) then lunge=true end
            end
        end
    end
    return active,charging,lunge
end

function H.parry.attackName(track)
    local label=track.Name or ''
    local anim=track.Animation
    if anim then label=label..' '..anim.Name end
    label=label:lower():gsub('[%s_%-%(%)]','')
    local id=anim and tostring(anim.AnimationId):match('%d+')
    if id and H.parry.animationIds[id] then return true, label:find('lunge',1,true)~=nil end
    if label:find('parry',1,true) or label:find('block',1,true)
        or label:find('idle',1,true) or label:find('walk',1,true) then
        return false,false
    end
    local attackWords={'attack','swing','slash','stab','strike','lunge',
        'lightm1','heavym1','melee','basicm1','primaryattack','m1attack', 'basicattack','knife','weaponhit','hit1','heavyattack'}
    for _,word in ipairs(attackWords) do
        if label:find(word,1,true) then
            return true,label:find('lunge',1,true)~=nil
                or label:find('heavy',1,true)~=nil
        end
    end
    -- Some projects label their attack track simply M1 / M1_1.
    local trackName=(track.Name or ''):lower():gsub('[%s_%-%(%)]','')
    local animName=(anim and anim.Name or ''):lower():gsub('[%s_%-%(%)]','')
    if trackName:match('^m1%d*$') or animName:match('^m1%d*$') then
        return true,false
    end
    -- Some games replicate killer swings as generically named
    -- "Animation" tracks. Action-priority tracks are a conservative
    -- additional signal, but proximity/facing checks still apply.
    local priority=track.Priority
    if priority and priority.Value>=Enum.AnimationPriority.Action.Value
        and (trackName=='animation' or animName=='animation'
            or trackName=='anim') then
        return true,false
    end
    return false,false
end

function H.parry.newAttack(p,lunging,source)
    H.parry.nextSequence+=1
    local now=os.clock()
    local item={sequence=H.parry.nextSequence,started=now,
        expires=now+(lunging and 2.1 or 1.25),
        lunging=lunging==true,source=source,parried=false}
    H.parry.attacks[p]=item
    return item
end

function H.parry.confirmMarker(p,lunge)
    if not H.parry.active or not H.parry.killer(p) then return end
    local prior=H.parry.attacks[p]
    if prior and not prior.parried and os.clock()<prior.expires then
        prior.expires=math.max(prior.expires,os.clock()+0.45)
        prior.confirmed=true
        prior.released=true
        prior.lunging=prior.lunging or lunge
    else
        local attack=H.parry.newAttack(p,lunge,'marker')
        attack.confirmed=true
        attack.released=true
    end
    H.parry.evaluate(p)
end

function H.parry.onTrack(p,track)
    if not H.parry.active or not track or H.parry.seenTracks[track] then return end
    H.parry.seenTracks[track]=true
    local isAttack,lunging=H.parry.attackName(track)
    if not isAttack then
        return
    end
    local attack=H.parry.newAttack(p,lunging,'animation')
    attack.confirmed=true
    if H.parry.debug then
        print('[Orona Parry] Swing detected:',p.Name,track.Name)
    end
    -- On a held/charged attack, wait for its release/strike state or marker.
    local _,charging=H.parry.readAttackState(p)
    local name=(track.Name..' '..(track.Animation and track.Animation.Name or '')):lower()
    attack.chargeStarted=charging or name:find('charge',1,true)~=nil
        or name:find('windup',1,true)~=nil or name:find('hold',1,true)~=nil
    attack.awaitingRelease=attack.chargeStarted
    local markerCons={}
    local trackWatch={connections=markerCons}
    H.parry.trackWatches[track]=trackWatch
    for _,marker in ipairs({'Hit','Swing','Strike','Release','Damage'}) do
        local ok,signal=pcall(function()
            return track:GetMarkerReachedSignal(marker)
        end)
        if ok and signal then
            markerCons[#markerCons+1]=signal:Connect(function()
                H.parry.confirmMarker(p,lunging)
            end)
        end
    end
    local stopped
    stopped=track.Stopped:Connect(function()
        if H.parry.attacks[p]==attack and not attack.parried then
            attack.expires=math.min(attack.expires,os.clock()+0.20)
        end
        for _,con in ipairs(trackWatch.connections) do con:Disconnect() end
        H.parry.trackWatches[track]=nil
        -- Reused AnimationTracks may represent a later new LMB swing.
        H.parry.seenTracks[track]=nil
    end)
    trackWatch.connections[#trackWatch.connections+1]=stopped
    H.parry.evaluate(p)
end

function H.parry.watch(p)
    if not H.parry.killer(p) then return end
    local char=p.Character
    local hum=char:FindFirstChildOfClass('Humanoid')
    local animator=(hum and hum:FindFirstChildOfClass('Animator'))
        or char:FindFirstChild('Animator',true)
    local previous=H.parry.attackers[p]
    if previous and previous.character==char and previous.animator==animator then return end
    if previous and previous.connection then previous.connection:Disconnect() end
    local info={character=char,animator=animator}
    H.parry.attackers[p]=info
    if animator and animator:IsA('Animator') then
        info.connection=animator.AnimationPlayed:Connect(function(track)
            H.parry.onTrack(p,track)
        end)
        -- Catch attacks already playing when enabled mid-round.
        for _,track in ipairs(animator:GetPlayingAnimationTracks()) do
            H.parry.onTrack(p,track)
        end
    end
end

function H.parry.rightClick()
    -- In an owned game's Studio LocalScript, use your own parry ability
    -- callback: _G.OronaParryDaggerRightClick = function() ... end
    local dagger=H.parry.dagger()
    -- This event is installed inside the Parry Dagger by its actual
    -- controller, which invokes the SAME parry action used by RMB.
    local request=dagger and dagger:FindFirstChild('OronaAutoParryRequest',true)
    if not request and Me.Character then
        request=Me.Character:FindFirstChild('OronaAutoParryRequest',true)
    end
    if not request and PG then
        request=PG:FindFirstChild('OronaAutoParryRequest',true)
    end
    if request and request:IsA('BindableEvent') then
        local ok=pcall(function() request:Fire() end)
        if ok then return true end
    end
    if type(env.OronaParryDaggerRightClick)=='function' then
        local ok,result=pcall(env.OronaParryDaggerRightClick)
        return ok and result~=false
    end
    local click=type(mouse2click)=='function' and mouse2click
        or (type(env.mouse2click)=='function' and env.mouse2click)
    local press=type(mouse2press)=='function' and mouse2press
        or (type(env.mouse2press)=='function' and env.mouse2press)
    local release=type(mouse2release)=='function' and mouse2release
        or (type(env.mouse2release)=='function' and env.mouse2release)
    if click then return pcall(click) end
    if press and release then
        local ok=pcall(press)
        if ok then
            task.delay(.055,function() pcall(release) end)
            return true
        end
    end
    local ok,vim=pcall(function()
        return game:GetService('VirtualInputManager')
    end)
    if ok and vim then
        local pos=UIS:GetMouseLocation()
        local pressed=pcall(function()
            vim:SendMouseButtonEvent(pos.X,pos.Y,1,true,game,0)
        end)
        if pressed then
            task.delay(.055,function()
                pcall(function()
                    vim:SendMouseButtonEvent(pos.X,pos.Y,1,false,game,0)
                end)
            end)
            return true
        end
    end
    return false
end

function H.parry.evaluate(p)
    if not H.parry.active or unloaded or menuOpen or not S.AutoParry
        or not H.vaultRoundActive() then return end
    if Me.Character==nil or not H.parry.dagger() or H.isKiller(Me) then return end
    local now=os.clock()
    local attack=H.parry.attacks[p]
    if not attack or attack.parried or now>attack.expires then return end
    if now-H.parry.lastParry<H.parry.cooldown then return end
    local own=Me.Character
    local target=p.Character
    if not target then return end
    local ourHum=own:FindFirstChildOfClass('Humanoid')
    local theirHum=target:FindFirstChildOfClass('Humanoid')
    local ourRoot=own:FindFirstChild('HumanoidRootPart')
    local theirRoot=target:FindFirstChild('HumanoidRootPart')
    if not ourHum or ourHum.Health<=0 or not theirHum or theirHum.Health<=0
        or not ourRoot or not theirRoot then return end
    local active,charging,lunging=H.parry.readAttackState(p)
    if charging and not active then return end
    local delta=ourRoot.Position-theirRoot.Position
    if math.abs(delta.Y)>7.5 then return end
    local flat=Vector3.new(delta.X,0,delta.Z)
    local dist=flat.Magnitude
    if dist<.05 then return end
    -- The killer must be oriented towards us (not merely close).
    local fwd=theirRoot.CFrame.LookVector
    local facing=Vector3.new(fwd.X,0,fwd.Z)
    if facing.Magnitude>.01 and dist>3.25
        and facing.Unit:Dot(flat.Unit)<0.18 then return end
    local relative=theirRoot.AssemblyLinearVelocity-ourRoot.AssemblyLinearVelocity
    local closing=relative:Dot(flat.Unit)
    local isLunge=attack.lunging or lunging
    local maxRange=(isLunge and closing>7) and H.parry.lungeRange or H.parry.range
    if dist>maxRange then return end
    -- A held lunge isn't a swing until the release/strike is observed.
    if charging and not attack.confirmed then return end
    -- If a named attack started during a charge, wait for charge to end.
    if attack.awaitingRelease and not attack.released then
        if charging then return end
        -- The charging state ended. This is the best available client
        -- release edge when the attacker has no animation marker.
        if not active and now-attack.started<.12 then return end
        attack.released=true
    end
    if attack.chargeStarted and charging and not attack.released then return end
    local fired=H.parry.rightClick()
    if H.parry.debug then
        print('[Orona Parry] Attempted right-click:',p.Name,
            'distance:',math.floor(dist*10)/10,'dispatched:',fired)
    end
    if fired then
        attack.parried=true
        H.parry.lastParry=now
    elseif not H.parry.warnedInput then
        H.parry.warnedInput=true
        warn('Orona Auto Parry: detected a threat but the equipped weapon has no supported right-click action. Connect OronaAutoParryRequest inside the dagger controller or provide OronaParryDaggerRightClick.')
    end
end

function H.parry.step(dt)
    if not H.parry.active or unloaded or not S.AutoParry then return end
    if not H.vaultRoundActive() then return end
    H.parry.clock+=math.min(dt,.1)
    H.parry.watchClock+=math.min(dt,.1)
    if H.parry.watchClock>=.48 then
        H.parry.watchClock=0
        for _,p in ipairs(Players:GetPlayers()) do H.parry.watch(p) end
        for p,info in pairs(H.parry.attackers) do
            if not p.Parent or p.Character~=info.character then
                if info.connection then info.connection:Disconnect() end
                H.parry.attackers[p]=nil
                H.parry.attacks[p]=nil
                H.parry.activeStates[p]=nil
            end
        end
    end
    if H.parry.clock<.016 then return end
    H.parry.clock=0
    if not H.parry.dagger() or menuOpen then return end
    for _,p in ipairs(Players:GetPlayers()) do
        if H.parry.killer(p) then
            local active,charging,lunging=H.parry.readAttackState(p)
            if active and not charging then
                if not H.parry.activeStates[p] then
                    local atk=H.parry.attacks[p]
                    if not atk or atk.parried or os.clock()>atk.expires then
                        H.parry.newAttack(p,lunging,'state')
                    else
                        atk.confirmed=true
                        atk.lunging=atk.lunging or lunging
                        if atk.chargeStarted and not charging then atk.released=true end
                    end
                end
            end
            H.parry.activeStates[p]=active and not charging
            H.parry.evaluate(p)
        end
    end
end

function H.parry.setEnabled(value)
    H.parry.active=value==true
    if not H.parry.active then
        if H.parry.heartbeat then H.parry.heartbeat:Disconnect();H.parry.heartbeat=nil end
        for _,entry in pairs(H.parry.attackers) do
            if entry.connection then entry.connection:Disconnect() end
        end
        for _,entry in pairs(H.parry.trackWatches) do
            for _,con in ipairs(entry.connections) do con:Disconnect() end
        end
        H.parry.trackWatches=setmetatable({},{__mode='k'})
        table.clear(H.parry.attackers)
        table.clear(H.parry.attacks)
        table.clear(H.parry.activeStates)
        H.parry.seenTracks=setmetatable({},{__mode='k'})
        return
    end
    H.parry.clock=0;H.parry.watchClock=.5
    H.parry.warnedInput=false
    H.parry.lastAttackDiagnostic=0
    local dagger=H.parry.dagger()
    if not dagger then
        warn('Orona Auto Parry: equip a Tool or Model named Weapon, Weapons, Dagger or Parry Dagger (in Character, not Backpack).')
    elseif not dagger:FindFirstChild('OronaAutoParryRequest',true)
        and type(env.OronaParryDaggerRightClick)~='function'
        and type(mouse2click)~='function'
        and type(mouse2press)~='function' then
        warn('Orona Auto Parry: weapon found, but no parry-action bridge. Connect a BindableEvent named OronaAutoParryRequest in the dagger controller to its existing RMB parry function.')
    end
    if not H.vaultRoundActive() then
        warn('Orona Auto Parry: waiting for a replicated active-round state or survivor role.')
    end
    if not H.parry.heartbeat then
        H.parry.heartbeat=RS.Heartbeat:Connect(H.parry.step)
    end
end
-- V76 diagnostics: F7 deliberately tests the equipped weapon's RMB path.
-- This cannot confirm the ability executed, but separates input problems
-- from swing-detection problems in Roblox Studio Output.
H.con(UIS.InputBegan,function(input,processed)
    if processed or unloaded or menuOpen or not S.AutoParry then return end
    if input.KeyCode==Enum.KeyCode.F7 then
        local weapon=H.parry.dagger()
        if not weapon then
            warn('[Orona Parry Test] No equipped Weapon / Weapons / Dagger / Parry Dagger in Character.')
        else
            local dispatched=H.parry.rightClick()
            warn('[Orona Parry Test] Weapon:',weapon.Name,
                'RMB dispatched:',dispatched,
                '(does not guarantee the game parried; use the weapon controller bridge if nothing happens).')
        end
    end
end)
-- ===== END V74 AUTO PARRY =====

-- Camera and FOV blocks are constructed separately; this reference lets
-- the aim step assert the user's selected FOV immediately after steering.
local reapplySelectedFOV=function() end
local lastAimFrameAt=os.clock()
local function doMovementAndAim()
    if unloaded or menuOpen then
        lockedHead=nil
        H.gunLockedTorso=nil
        if moonHeld then finishMoonwalk() end
        return
    end
    local camera=workspace.CurrentCamera
    if not camera then return end
    -- Observe real sprint speed outside Moonwalk. The game decides the speed;
    -- this script never applies a guessed multiplier or acceleration.
    if not moonHeld then
        local character=Me.Character
        local observed=character and character:FindFirstChildOfClass('Humanoid')
        if observed and observed.Health>0 and observed.WalkSpeed>0 then
            if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then
                if H.mw.observedWalkSpeed and
                     observed.WalkSpeed>H.mw.observedWalkSpeed+.1 then
                    H.mw.observedSprintSpeed=observed.WalkSpeed
                    H.mw.observedSprintHum=observed
                    H.mw.observedSprintAt=os.clock()
                end
            else
                H.mw.observedWalkSpeed=observed.WalkSpeed
            end
        end
    end
    if moonHeld and (not S.Moonwalk or not moonInputDown()) then
        finishMoonwalk()
    end
    -- RMB only activates assist when the flashlight is EQUIPPED and the
    -- killer is already within a tight forward cone. Do not grab distant or
    -- off-center targets; stop tracking when you intentionally look away.
    local now=os.clock()
    local dt=math.clamp(now-lastAimFrameAt,0,.1)
    lastAimFrameAt=now
    local rightMouseHeld=UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
    if rightMouseHeld and S.GunAimlock and H.hasEquippedGun() then
        lockedHead=nil
        if not H.validGunTorso(H.gunLockedTorso,camera,false) then
            H.gunLockedTorso=H.nearestGunTorso(camera)
        end
        if H.gunLockedTorso then
            local desired=CFrame.lookAt(camera.CFrame.Position,H.gunLockedTorso.Position)
            camera.CFrame=camera.CFrame:Lerp(desired,
                math.clamp(1-math.exp(-11*dt),0,1))
            reapplySelectedFOV()
        end
    elseif rightMouseHeld and S.Aimlock and hasFlashlight() then
        H.gunLockedTorso=nil
        if not validKillerHead(lockedHead,camera,false) then
            lockedHead=nearestKillerHead(camera)
        end
        if lockedHead then
            local desired=CFrame.lookAt(camera.CFrame.Position,
                flashlightAimPoint(camera,lockedHead))
            local alpha=math.clamp(1-math.exp(-AIM_SMOOTH_SPEED*dt),0,1)
            camera.CFrame=camera.CFrame:Lerp(desired,alpha)
            reapplySelectedFOV()
        end
    else
        lockedHead=nil
        H.gunLockedTorso=nil
    end
end
-- V66 runs after Kitty's flashlight/camera aiming. Aiming may steer the
-- camera, but cannot overwrite our body's backward-facing A/D turns.
function H.mwUpdate(dt)
    if unloaded or not S.Moonwalk or not moonHeld or menuOpen then return end
    if not moonInputDown() then finishMoonwalk(); return end
    local character=Me.Character
    local hum=character and character:FindFirstChildOfClass('Humanoid')
    local root=character and character:FindFirstChild('HumanoidRootPart')
    if not hum or hum.Health<=0 or not root or hum~=moonHum then
        finishMoonwalk()
        return
    end
    local camera=workspace.CurrentCamera
    if not camera then return end
    if hum.AutoRotate then hum.AutoRotate=false end
    H.mwSprintInput(true)
    -- Maintain only the *previously observed* normal sprint speed if the
    -- game drops back to walking when physical Shift is released.
    local speed=H.mw.sprintTarget
    if speed and speed>0 and hum.WalkSpeed<speed-.15 then
        hum.WalkSpeed=speed
        H.mw.speedChanged=true
    end
    -- V67 camera follow: TRACK AN ABSOLUTE TARGET, not only a fraction of
    -- each frame's camera delta. Otherwise the unprocessed angle is lost and
    -- the character slowly stops following when the camera stops moving.
    -- Keep the initial camera/body offset, so the back-facing movement remains
    -- consistent as the user looks around. 36-degree A/D turns layer on top.
    local cameraYaw=mwFlatYaw(camera.CFrame.LookVector)
    local rmb=UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
    -- Kitty's own flashlight/gun aimlock can steer the camera. Do not treat
    -- that automatic steering as a user-initiated body turn. Normal RMB camera
    -- dragging STILL follows if no aimlock target is being driven.
    local scriptedAimSteering=rmb and
        ((S.Aimlock and lockedHead~=nil)
            or (S.GunAimlock and H.gunLockedTorso~=nil))
    if H.mw.cameraFollow and cameraYaw and H.mw.baseFacing then
        if scriptedAimSteering then
            H.mw.aimWasDrivingCamera=true
        else
            if H.mw.aimWasDrivingCamera then
                -- Rebase after the flashlight releases its camera aim, so the
                -- body doesn't jump to the last automatic aiming direction.
                local anchorYaw=mwFlatYaw(H.mw.baseFacing) or cameraYaw
                H.mw.cameraYawOffset=mwAngleDelta(anchorYaw-cameraYaw)
                H.mw.aimWasDrivingCamera=false
            end
            local desiredYaw=cameraYaw+(H.mw.cameraYawOffset or 0)
            local facingYaw=mwFlatYaw(H.mw.baseFacing) or desiredYaw
            local difference=mwAngleDelta(desiredYaw-facingYaw)
            local alpha=math.clamp(1-math.exp(
                -H.mw.cameraFollowResponse*math.max(dt,0)),0,1)
            local nextYaw=facingYaw+difference*alpha
            H.mw.baseFacing=CFrame.Angles(0,nextYaw,0).LookVector
        end
    end
    H.mw.lastCameraYaw=cameraYaw
    local cycle=H.mw.aTime+H.mw.gapA+H.mw.dTime+H.mw.gapD
    local phase=(os.clock()-H.mw.startedAt)%cycle
    local pulse=0
    if phase<H.mw.aTime then pulse=-1
    elseif phase>=H.mw.aTime+H.mw.gapA and
        phase<H.mw.aTime+H.mw.gapA+H.mw.dTime then pulse=1 end
    -- V4 whole-body 36-degree turns on the original 55ms A/D cadence.
    local anchor=CFrame.lookAt(Vector3.zero,H.mw.baseFacing)
    local targetForward=(anchor*CFrame.Angles(0,-pulse*math.rad(H.mw.bodyTurnDegrees),0)).LookVector
    local target=CFrame.lookAt(root.Position,root.Position+targetForward)
    local turnAlpha=math.clamp(1-math.exp(-H.mw.turnResponse*math.max(dt,0)),0,1)
    root.CFrame=root.CFrame:Lerp(target,turnAlpha)
    local backward=-root.CFrame.LookVector
    local right=root.CFrame.RightVector
    local travel=Vector3.new(backward.X*H.mw.backwardWeight+right.X*pulse*H.mw.sideWeight,
        0,backward.Z*H.mw.backwardWeight+right.Z*pulse*H.mw.sideWeight)
    if travel.Magnitude>.001 then
        hum:Move(travel.Unit,false) -- unit vector preserves normal sprint speed
    end
end
local motionRenderName='OronaMotionV48'
RS:BindToRenderStep(motionRenderName,
    Enum.RenderPriority.Last.Value+200,doMovementAndAim)
RS:BindToRenderStep(H.mw.renderName,
    Enum.RenderPriority.Last.Value+350,H.mwUpdate)

-- Prefer the persistent executor UI container when it is available;
-- otherwise a non-resetting PlayerGui ScreenGui is used in Studio.
local uiParent=PG
if type(gethui)=="function" then
    local ok,hui=pcall(gethui)
    if ok and typeof(hui)=="Instance" then uiParent=hui end
end
-- A CoreGui fallback also survives games that clear PlayerGui between rounds.
if uiParent==PG then
    local ok,core=pcall(function()
        local coreGui=game:GetService('CoreGui')
        local probe=Instance.new('Folder')
        probe.Parent=coreGui
        probe:Destroy()
        return coreGui
    end)
    if ok and core then uiParent=core end
end
for _,previousName in ipairs({"OronaV53","OronaV52","OronaV51","OronaV50","OronaV49","OronaV48","OronaV47","OronaV46","OronaV45","OronaV44","OronaV43","OronaV42","OronaV41","OronaV39"}) do
    local old=uiParent:FindFirstChild(previousName)
    if old then old:Destroy() end
end
