-- ======== V47: PEEKING ANIME CATGIRL / INTERACTIVE KITTY TOOLS ========
-- The illustrated transparent PNG is bundled into this script for injectors
-- that support writefile + getcustomasset/getsynasset. In Roblox Studio,
-- upload Orona_Catgirl_Asset.png and set the image ID below instead.
local ORONA_CATGIRL_IMAGE_ID = '' -- Optional: 'rbxassetid://YOUR_IMAGE_ASSET_ID'
local ORONA_CATGIRL_FILE = 'Orona_Catgirl_V48.png'
local function decodeOronaBase64(s)
    local chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local n={}
    for i=1,#chars do n[chars:sub(i,i)]=i-1 end
    s=s:gsub('%s','')
    local pieces={}
    for i=1,#s,4 do
        local a=n[s:sub(i,i)] or 0
        local b=n[s:sub(i+1,i+1)] or 0
        local c=n[s:sub(i+2,i+2)] or 0
        local d=n[s:sub(i+3,i+3)] or 0
        local packed=a*262144+b*4096+c*64+d
        local padding=s:sub(i+2,i+3)
        if padding:sub(1,1)=='=' then
            pieces[#pieces+1]=string.char(math.floor(packed/65536)%256)
        elseif padding:sub(2,2)=='=' then
            pieces[#pieces+1]=string.char(math.floor(packed/65536)%256,
                math.floor(packed/256)%256)
        else
            pieces[#pieces+1]=string.char(math.floor(packed/65536)%256,
                math.floor(packed/256)%256,packed%256)
        end
    end
    return table.concat(pieces)
end
