-- V49 lightweight transparent cutouts for peeking ears and the status face.
function H.v49Art(file,base64Text)
    local loader=(type(getcustomasset)=='function' and getcustomasset)
        or (type(getsynasset)=='function' and getsynasset)
    if not loader or type(writefile)~='function' then return nil end
    local ok,result=pcall(function()
        if type(isfile)~='function' or not isfile(file) then
            writefile(file,decodeOronaBase64(base64Text))
        end
        return loader(file)
    end)
    return (ok and type(result)=='string') and result or nil
end
