-- V47 peeking catgirl: the closed clip shows ears/hair/eyes only.
-- Clicking unfolds her detailed full portrait, and opens Kitty Tools.
local catgirlButton=H.new('ImageButton',{
    Name='OronaCatgirlPeek',BackgroundTransparency=1,
    Size=UDim2.fromOffset(116,150),Position=UDim2.new(1,-8,0,98),
    ClipsDescendants=true,Image='',AutoButtonColor=false,ZIndex=45
},main)
-- V65: no square border around the peeking character. The clickable
-- ImageButton stays rectangular as a hitbox, but the visible hover halo
-- follows the transparent PNG's character silhouette instead.
H.peekGlowImages={}
local function setPeekGlow(hover)
    for _,image in ipairs(H.peekGlowImages) do
        H.tween(image,{ImageTransparency=hover and .37 or 1},.16)
    end
end
H.con(catgirlButton.MouseEnter,function()
    if not sideOpen and not unloaded then setPeekGlow(true) end
end)
H.con(catgirlButton.MouseLeave,function() setPeekGlow(false) end)
local catgirlImage=getOronaCatgirlImage()
local catgirlPortrait
if catgirlImage then
    catgirlPortrait=H.new('ImageLabel',{
        Name='CatgirlPortrait',BackgroundTransparency=1,
        Size=UDim2.fromOffset(194,194),
        Position=UDim2.fromOffset(-14,-6),
        Image=catgirlImage,ScaleType=Enum.ScaleType.Fit,ZIndex=46
    },catgirlButton)
else
    -- Self-contained fallback still works in ordinary Studio LocalScripts.
    local hair=H.new('Frame',{
        Size=UDim2.fromOffset(108,112),Position=UDim2.fromOffset(-7,22),
        BackgroundColor3=C.hair,BorderSizePixel=0,ZIndex=47
    },catgirlButton)
    H.round(hair,48);H.stroke(hair,C.hot,2)
    for _,x in ipairs({9,74}) do
        local ear=H.new('Frame',{
            Size=UDim2.fromOffset(28,35),Position=UDim2.fromOffset(x,2),
            Rotation=x==9 and -21 or 21,
            BackgroundColor3=C.hair,BorderSizePixel=0,ZIndex=48
        },catgirlButton)
        H.round(ear,8)
        H.new('Frame',{Position=UDim2.fromOffset(8,8),
            Size=UDim2.fromOffset(12,16),BackgroundColor3=C.soft,
            BorderSizePixel=0,ZIndex=49},ear)
    end
    local face=H.new('Frame',{
        Size=UDim2.fromOffset(87,86),Position=UDim2.fromOffset(5,41),
        BackgroundColor3=C.skin,BorderSizePixel=0,ZIndex=48
    },catgirlButton)
    H.round(face,40)
    for _,x in ipairs({26,64}) do
        local eye=H.new('Frame',{
            Size=UDim2.fromOffset(12,18),Position=UDim2.fromOffset(x,70),
            BackgroundColor3=C.iris,BorderSizePixel=0,ZIndex=50
        },catgirlButton)
        H.round(eye,7)
    end
    local bow=H.label(catgirlButton,'♡',26,C.hot,
        UDim2.fromOffset(65,13),UDim2.fromOffset(40,38))
    bow.ZIndex=51
end
