if H.v56Peek then H.v55Peek=H.v56Peek end
if H.v56Full then H.fullbodyImage=H.v56Full end

-- More faithful peek: ears/eyes/hair cutout, no cropped rectangular portrait.
H.v49Peek=nil
if H.v55Peek or H.v50PeekArt or H.peekArtV49 then
    if catgirlPortrait then catgirlPortrait.Visible=false end
    H.v49Peek=H.new('ImageLabel',{
        Name='OronaEarEyePeek',BackgroundTransparency=1,
        Size=UDim2.fromOffset(132,178),
        Position=UDim2.fromOffset(-7,-4),Image=H.v55Peek or H.v50PeekArt or H.peekArtV49,
        ScaleType=Enum.ScaleType.Fit,ZIndex=49
    },catgirlButton)
    -- Eight low-opacity copies sit behind the art, offset a few pixels;
    -- transparency in the original image makes a contour, not a square.
    for _,delta in ipairs({{-3,0},{3,0},{0,-3},{0,3},
        {-2,-2},{2,-2},{-2,2},{2,2}}) do
        local halo=H.new('ImageLabel',{
            Name='OronaCatgirlSilhouetteGlow',BackgroundTransparency=1,
            Size=UDim2.fromOffset(132,178),
            Position=UDim2.fromOffset(-7+delta[1],-4+delta[2]),
            Image=H.v55Peek or H.v50PeekArt or H.peekArtV49,
            ImageColor3=C.hot,ImageTransparency=1,
            ScaleType=Enum.ScaleType.Fit,ZIndex=48
        },catgirlButton)
        H.peekGlowImages[#H.peekGlowImages+1]=halo
    end
end
-- The transparent art itself includes both hands gripping the edge.
-- Do not draw extra rectangular hands over the catgirl's own fingers.
-- Expanded portrait is separate from the small peeking-head portrait.

-- Since it sits immediately to the right of Kitty Tools, it never blocks toggles.
H.fullbodyPortrait=nil
if H.fullbodyImage then
    H.fullbodyPortrait=H.new('ImageLabel',{
        Name='OronaExpandedAnimeGirl',BackgroundTransparency=1,
        Size=UDim2.fromOffset(246,640),Position=UDim2.new(1,313,0,111),
        Image=H.fullbodyImage,ScaleType=Enum.ScaleType.Fit,
        Visible=false,Active=false,Selectable=false,ZIndex=34
    },main)
    -- Soft-lace drape makes the illustration fade naturally into the menu
    -- instead of ending at an abruptly cropped stocking edge.
    H.fullbodyBottomCharm=H.label(main,'♡   ♡   ♡',16,C.hot,
        UDim2.new(1,335,0,737),UDim2.fromOffset(196,20))
    H.fullbodyBottomCharm.ZIndex=53
    H.fullbodyBottomCharm.Visible=false
end
-- Sparkly ribbon shows this edge is clickable even with most art hidden.
local peekHeart=H.label(catgirlButton,'♡',18,C.hot,
    UDim2.fromOffset(35,113),UDim2.fromOffset(25,22))
peekHeart.ZIndex=52
H.peekPaw=H.label(catgirlButton,'♡',13,C.dark,
    UDim2.fromOffset(1,67),UDim2.fromOffset(24,22))
H.peekPaw.ZIndex=53
H.peekRibbon=H.label(catgirlButton,'♡',15,C.hot,
    UDim2.fromOffset(41,96),UDim2.fromOffset(26,25))
H.peekRibbon.ZIndex=52
-- V55 fullbody remains non-clickable. The small peeking tab alone opens
-- Kitty Tools, and the actual X button alone closes it. No giant hitbox.
local function setSideMenu(show)
    if unloaded then return end
    if show and H.setConfigMenu then H.setConfigMenu(false) end
    sideOpen=show
    setPeekGlow(false)
    if show then
        sidePanel.Visible=true
        sidePanel.Position=UDim2.new(1,0,0,193)
        H.tween(sidePanel,{Position=UDim2.new(1,13,0,193)},.22)
        catgirlButton.Visible=false
        if H.fullbodyPortrait then H.fullbodyPortrait.Visible=true end
        if H.fullbodyBottomCharm then H.fullbodyBottomCharm.Visible=true end
        peekHeart.Visible=false
        H.peekPaw.Visible=false
        H.peekRibbon.Visible=false
    else
        if H.fullbodyPortrait then H.fullbodyPortrait.Visible=false end
        if H.fullbodyBottomCharm then H.fullbodyBottomCharm.Visible=false end
        sidePanel.Visible=false
        catgirlButton.Visible=true
        catgirlButton.Position=UDim2.new(1,-8,0,98)
        catgirlButton.Size=UDim2.fromOffset(116,150)
        catgirlButton.ClipsDescendants=true
        if H.v49Peek then H.v49Peek.Visible=true end
        if catgirlPortrait then catgirlPortrait.Visible=not H.v49Peek end
        peekHeart.Visible=false
        H.peekPaw.Visible=false
        H.peekRibbon.Visible=false
    end
    if H.fitMenuToScreen then H.fitMenuToScreen() end
end

H.openKittyTools=setSideMenu
H.con(catgirlButton.MouseButton1Click,function()
    setSideMenu(not sideOpen)
end)
H.con(sideExit.MouseButton1Click,function()
    setSideMenu(false)
end)
-- ======== END V47 CATGIRL ========

function H.fitMenuToScreen()
    if unloaded or not H.menuUIScale.Parent then return end
    local camera=workspace.CurrentCamera
    if not camera then return end
    local v=camera.ViewportSize
    if v.X<100 or v.Y<100 then return end
    local scale=math.min(1,(v.Y-32)/735,(v.X-32)/((sideOpen and (H.fullbodyImage and 1000 or 850) or 405) + (H.configOpen and 325 or 0)))
    H.menuUIScale.Scale=math.clamp(scale,.55,1)
    if H.configOpen then
        local leftEdge=main.AbsolutePosition.X-335*H.menuUIScale.Scale
        if leftEdge<9 then
            local shift=9-leftEdge
            main.Position=UDim2.new(main.Position.X.Scale,
                main.Position.X.Offset+shift,
                main.Position.Y.Scale,main.Position.Y.Offset)
        end
    end
    if sideOpen then
        -- The right edge of Kitty Tools is main-right + panel width.
        local rightEdge=(main.AbsolutePosition.X+main.AbsoluteSize.X
            + ((H.fullbodyImage and 595 or 546)*H.menuUIScale.Scale))
        local overflow=rightEdge-(v.X-10)
        if overflow>0 and overflow<v.X then
            main.Position=UDim2.new(main.Position.X.Scale,
                main.Position.X.Offset-overflow,
                main.Position.Y.Scale,main.Position.Y.Offset)
        end
    end
end
function H.watchMenuViewport()
    if H.menuSizeConnection then H.menuSizeConnection:Disconnect() end
    local camera=workspace.CurrentCamera
    if camera then
        H.menuSizeConnection=H.con(
            camera:GetPropertyChangedSignal('ViewportSize'),H.fitMenuToScreen)
    end
    H.fitMenuToScreen()
end
H.con(workspace:GetPropertyChangedSignal('CurrentCamera'),H.watchMenuViewport)
H.watchMenuViewport()
local bg=H.new("Frame",{Size=UDim2.new(1,-12,1,-12),
Position=UDim2.fromOffset(6,6),BackgroundColor3=C.pale,
BorderSizePixel=0,ZIndex=3},main)
H.round(bg,19)
H.new("UIGradient",{Rotation=90,
Color=ColorSequence.new(C.cream,C.pale)},bg)
-- V51 couture trim: lightweight static heart jewels along the main border.
for _,y in ipairs({116,191,535,622,688}) do
    for _,left in ipairs({true,false}) do
        local jewel=H.label(main,(y==191 or y==622) and '✦' or '♡',
            11,C.hot,UDim2.fromOffset(left and 1 or 339,y),
            UDim2.fromOffset(15,16))
        jewel.ZIndex=8
        jewel.TextTransparency=.20
    end
end
-- V52 static lace: one decorative image reused (no RenderStepped effects).
if H.v52Lace then
    local topTrim=H.new('ImageLabel',{
        Position=UDim2.fromOffset(18,103),Size=UDim2.fromOffset(319,20),
        BackgroundTransparency=1,Image=H.v52Lace,ScaleType=Enum.ScaleType.Stretch,
        ZIndex=14},main)
    local sideTrim=H.new('ImageLabel',{
        Position=UDim2.fromOffset(15,435),Size=UDim2.fromOffset(297,20),
        BackgroundTransparency=1,Image=H.v52Lace,ScaleType=Enum.ScaleType.Stretch,
        ZIndex=22},sidePanel)
end
local rainLayer=H.new("Frame",{Size=UDim2.fromScale(1,1),
ClipsDescendants=true,BackgroundTransparency=1,ZIndex=4},main)
local particles=0
local function spawnRain()
if unloaded or not menuOpen or not S.Rain or particles>=7 then return end
particles+=1
local size=RNG:NextInteger(15,22)
local x=RNG:NextInteger(9,310)
local drop=H.new("Frame",{Size=UDim2.fromOffset(size,size),
Position=UDim2.fromOffset(x,-30),
BackgroundTransparency=1,ZIndex=4},rainLayer)
if RNG:NextNumber()<.33 then
H.kitty(drop,size,UDim2.fromOffset(0,0),false,false)
else
local sym={"♡","✦","✧","✿"}
local star=H.label(drop,sym[RNG:NextInteger(1,#sym)],size,C.pink,
UDim2.fromScale(0,0),UDim2.fromScale(1,1))
star.ZIndex=4
end
local fall=H.tween(drop,{Position=UDim2.fromOffset(
math.clamp(x+RNG:NextInteger(-35,35),5,315),640),
Rotation=RNG:NextInteger(-25,25)},RNG:NextNumber(4,6))
fall.Completed:Once(function()
if drop.Parent then drop:Destroy() end
particles=math.max(0,particles-1)
end)
end
task.spawn(function()
while not unloaded and gui.Parent do
spawnRain();task.wait(.8)
end
end)
do
