BackgroundColor3=S[key] and C.pink or C.soft,
Text="",AutoButtonColor=false,ZIndex=z+1},row)
H.round(button,15)
H.stroke(button,C.white,.9)
local buttonGradient=H.new('UIGradient',{Rotation=0,
    Color=ColorSequence.new(S[key] and C.pink or C.pale,
        S[key] and C.hot or C.soft)},button)
local dot=H.new("Frame",{Size=UDim2.fromOffset(17,17),
Position=S[key] and UDim2.fromOffset(26,3) or UDim2.fromOffset(3,3),
BackgroundColor3=C.white,BorderSizePixel=0,ZIndex=z+2},button)
H.round(dot,12)
local function flip()
if unloaded then return end
local value=not S[key]
S[key]=value
buttonGradient.Color=ColorSequence.new(value and C.pink or C.pale,
    value and C.hot or C.soft)
H.tween(button,{BackgroundColor3=value and C.pink or C.soft})
H.tween(dot,{Position=value and UDim2.fromOffset(26,3)
or UDim2.fromOffset(3,3)})
if key=='AutoGen' then
setAutoGen(value)
elseif key=='AutoParry' then
H.parry.setEnabled(value)
elseif key=='Moonwalk' then
if not value then finishMoonwalk() end
elseif key=='Aimlock' or key=='GunAimlock' then
if not value then aimHeld=false;lockedHead=nil;H.gunLockedTorso=nil end
elseif key=='Streamer' then
setIntegratedStreamer(value)
elseif key=='Rain' then
rainLayer.Visible=value
elseif key=='Players' or key=='Kitties' then
for _,p in ipairs(Players:GetPlayers()) do H.updatePlayer(p) end
if key=='Players' then H.onPlayerESPToggled() end
else
toggleObjectiveCategory(key,value)
end
updateStatus()
end
H.con(button.MouseButton1Click,flip)
H.con(row.MouseButton1Click,flip)
-- Configs must use the feature callback, not only mutate the UI switch.
H.optionSetters[key]=function(value)
    if type(value)=='boolean' and S[key]~=value then flip() end
end
end
