H.firstCamera=workspace.CurrentCamera
H.startingFOV=H.firstCamera and H.firstCamera.FieldOfView or 70
H.minFOV=math.min(40,math.floor(H.startingFOV))
H.maxFOV=120
H.chosenFOV=math.clamp(H.startingFOV,H.minFOV,H.maxFOV)
H.fovCustomized=false
H.fovDragging=false
H.fovRenderName = 'OronaFOVV48'
H.fovBound = false
H.fovCameraConnection=nil
H.fovWriting=false
function H.applyFovOverride()
    if unloaded or not H.fovCustomized or H.fovWriting then return end
    local camera=workspace.CurrentCamera
    if camera and math.abs(camera.FieldOfView-H.chosenFOV)>.025 then
        H.fovWriting=true
        camera.FieldOfView=H.chosenFOV
        H.fovWriting=false
    end
end
reapplySelectedFOV=H.applyFovOverride
-- Catch game zoom/tween changes as soon as the Camera FOV property changes;
-- this handles RMB flashlight aiming even before the next render step.
function H.connectFovCamera()
    if H.fovCameraConnection then
        H.fovCameraConnection:Disconnect()
        H.fovCameraConnection=nil
    end
    local camera=workspace.CurrentCamera
    if camera then
        H.fovCameraConnection=camera:GetPropertyChangedSignal('FieldOfView'):Connect(function()
            H.applyFovOverride()
        end)
    end
end
function H.startFovOverride()
    if H.fovBound then return end
    H.fovBound=true
    -- The flashlight steering step is at Last+200. FOV runs after ALL
    -- Orona camera motion, keeping the selected value on the final frame.
    RS:BindToRenderStep(H.fovRenderName,
        Enum.RenderPriority.Last.Value+1000,H.applyFovOverride)
end
function H.stopFovOverride()
    if H.fovBound then
        RS:UnbindFromRenderStep(H.fovRenderName)
        H.fovBound=false
    end
    if H.fovCameraConnection then
        H.fovCameraConnection:Disconnect()
        H.fovCameraConnection=nil
    end
end
