function H.updateFovVisual()
local pct=(H.chosenFOV-H.minFOV)/math.max(1,H.maxFOV-H.minFOV)
pct=math.clamp(pct,0,1)
H.trackFill.Size=UDim2.new(pct,0,1,0)
H.catKnob.Position=UDim2.new(pct,0,.5,0)
H.fovValue.Text=tostring(math.floor(H.chosenFOV+.5)).."° / 120°"
end
function H.setFovFromMouse(x)
if unloaded then return end
local width=math.max(1,H.track.AbsoluteSize.X)
local pct=math.clamp((x-H.track.AbsolutePosition.X)/width,0,1)
H.chosenFOV=math.floor(H.minFOV+(H.maxFOV-H.minFOV)*pct+.5)
H.fovCustomized=true
H.startFovOverride()
H.applyFovOverride()
H.updateFovVisual()
end
function H.startFovDrag(input)
if input.UserInputType~=Enum.UserInputType.MouseButton1 then return end
H.fovDragging=true
H.setFovFromMouse(input.Position.X)
end
H.con(H.track.InputBegan,H.startFovDrag)
H.con(H.catKnob.InputBegan,H.startFovDrag)
H.con(UIS.InputChanged,function(input)
if H.fovDragging and input.UserInputType==Enum.UserInputType.MouseMovement then
H.setFovFromMouse(input.Position.X)
end
end)
H.con(UIS.InputEnded,function(input)
if input.UserInputType==Enum.UserInputType.MouseButton1 then
H.fovDragging=false
end
end)
H.con(workspace:GetPropertyChangedSignal("CurrentCamera"),function()
local camera=workspace.CurrentCamera
if unloaded then return end
H.connectFovCamera()
if not camera then return end
if H.fovCustomized then
H.applyFovOverride()
else
H.startingFOV=camera.FieldOfView
H.minFOV=math.min(40,math.floor(H.startingFOV))
H.chosenFOV=math.clamp(H.startingFOV,H.minFOV,H.maxFOV)
H.updateFovVisual()
end
end)
H.connectFovCamera()
H.updateFovVisual()
