local function drawNativeKittyEars(parent, width)
    -- No custom-asset API? Use a lightweight built-in ear-and-bow fallback.
    for _,entry in ipairs({{18,-18},{width-49,18}}) do
        local holder=H.new('Frame',{
            Name='NativeCatEar',Size=UDim2.fromOffset(33,37),
            Position=UDim2.fromOffset(entry[1],-26),Rotation=entry[2],
            BackgroundColor3=C.soft,BorderSizePixel=0,ZIndex=28},parent)
        H.round(holder,8);H.stroke(holder,C.white,1.8)
        local pink=H.new('Frame',{Size=UDim2.fromOffset(18,21),
            Position=UDim2.fromOffset(7,7),BackgroundColor3=C.pink,
            BorderSizePixel=0,ZIndex=29},holder)
        H.round(pink,6)
    end
    H.makeBow(parent,math.floor(width/2)-18,-25,28)
end
if coutureMain then
    H.new('ImageLabel',{Name='OronaV53MainRibbons',
        Position=UDim2.fromOffset(-8,-42),Size=UDim2.fromOffset(371,793),
        BackgroundTransparency=1,Image=coutureMain,
        ScaleType=Enum.ScaleType.Stretch,Active=false,ZIndex=30},main)
else
    drawNativeKittyEars(main,355)
end
if coutureTools then
    H.new('ImageLabel',{Name='OronaV53KittyToolsRibbons',
        Position=UDim2.fromOffset(-8,-42),Size=UDim2.fromOffset(344,603),
        BackgroundTransparency=1,Image=coutureTools,
        ScaleType=Enum.ScaleType.Stretch,Active=false,ZIndex=31},sidePanel)
else
    drawNativeKittyEars(sidePanel,328)
end
-- End couture. Static art adds no Heartbeat / RenderStepped overhead.

end
updateStatus=function()
local active=false
for key,value in pairs(S) do
if key~='Streamer' and value then active=true; break end
end
girlAwake(active)
status.Text=active and '♡ Orona Effect Is Active ♡'
or '♡ Orona Effect Is Eeping ♡'
status.TextColor3=active and C.hot or C.dark
end
updateStatus()
-- V52: a single non-overlapping ornament below the footer, not text
-- drawn over the bottom controls.
-- Footer edge is now ornamented by the actual V53 ribbon frame.
-- ===== V71 : CONFIG KITTY (two DISTINCT cutouts; closed pink / open plum, transparent) =====
do
    H.config={names={},selected=nil,autoload=nil,open=false}
    H.configOpen=false
    H.config.memory=env.__OronaConfigMemory or {saved={},names={},autoload=nil}
    env.__OronaConfigMemory=H.config.memory
    H.config.canPersist=(type(readfile)=='function' and type(writefile)=='function')
    H.config.http=game:GetService('HttpService')
    H.config.indexPath='Orona_Config_Index.json'

    function H.config.normalize(name)
        if type(name)~='string' then return nil end
        local clean=name:gsub('[^%w%-%_ ]',''):gsub('^%s+',''):gsub('%s+$','')
        clean=clean:gsub('%s+',' '):sub(1,28)
        return clean~='' and clean or nil
    end
    function H.config.path(name)
        return 'Orona_Config_'..name:gsub(' ','_')..'.json'
    end
    function H.config.tryRead(path)
        if not H.config.canPersist then return nil end
        local ok,raw=pcall(readfile,path)
        if not ok or type(raw)~='string' then return nil end
        local success,data=pcall(function() return H.config.http:JSONDecode(raw) end)
        return success and type(data)=='table' and data or nil
    end
    function H.config.tryWrite(path,data)
        if not H.config.canPersist then return false end
        local ok,encoded=pcall(function() return H.config.http:JSONEncode(data) end)
        if not ok then return false end
        local success=pcall(writefile,path,encoded)
        return success
    end
    function H.config.indexSave()
        H.config.memory.names=H.config.names
        H.config.memory.autoload=H.config.autoload
        H.config.tryWrite(H.config.indexPath,{
            names=H.config.names,autoload=H.config.autoload
        })
    end
    do
        local index=H.config.tryRead(H.config.indexPath)
        if index then
            if type(index.names)=='table' then
                for _,name in ipairs(index.names) do
                    local n=H.config.normalize(name)
                    if n then table.insert(H.config.names,n) end
                end
            end
            H.config.autoload=H.config.normalize(index.autoload)
        else
            for _,name in ipairs(H.config.memory.names or {}) do
                local n=H.config.normalize(name)
                if n then table.insert(H.config.names,n) end
            end
            H.config.autoload=H.config.memory.autoload
        end
    end
    function H.config.capture()
        local switches={}
        for k,v in pairs(S) do switches[k]=v==true end
        return {
            version=1,switches=switches,
            moonKey=moonKey and tostring(moonKey) or 'Unbound',
            fov=H.chosenFOV,fovCustomized=H.fovCustomized,
            moon={bodyTurnDegrees=H.mw.bodyTurnDegrees,
                sideWeight=H.mw.sideWeight,backwardWeight=H.mw.backwardWeight,
                cameraFollow=H.mw.cameraFollow}
        }
    end
    function H.config.save(name)
        name=H.config.normalize(name)
        if not name then return false,'Enter a config name.' end
        local data=H.config.capture()
        H.config.memory.saved[name]=data
        local persisted=H.config.tryWrite(H.config.path(name),data)
        if not table.find(H.config.names,name) then table.insert(H.config.names,name) end
        H.config.selected=name
        H.config.indexSave()
        return true,persisted and 'Saved ♡ '..name or
            'Saved for this session ♡ (file saving unavailable)'
    end
    function H.config.apply(data)
        if type(data)~='table' then return false end
        local key=data.moonKey
        if type(key)=='string' then
            local kind,item=key:match('^Enum%.([%w_]+)%.([%w_]+)$')
            if key=='Unbound' then moonKey=nil
            elseif kind=='KeyCode' and Enum.KeyCode[item] then moonKey=Enum.KeyCode[item]
            elseif kind=='UserInputType' and Enum.UserInputType[item] then
                moonKey=Enum.UserInputType[item]
            end
            local t=moonKey and (moonKey==Enum.UserInputType.MouseButton3 and 'Mouse 3' or moonKey.Name) or 'Unbound'
            bindButton.Text=t
        end
        if type(data.moon)=='table' then
            local m=data.moon
            if type(m.bodyTurnDegrees)=='number' then
                H.mw.bodyTurnDegrees=math.clamp(m.bodyTurnDegrees,0,80)
            end
            if type(m.sideWeight)=='number' then
                H.mw.sideWeight=math.clamp(m.sideWeight,0,1)
            end
            if type(m.backwardWeight)=='number' then
                H.mw.backwardWeight=math.clamp(m.backwardWeight,0,1)
            end
            if type(m.cameraFollow)=='boolean' then H.mw.cameraFollow=m.cameraFollow end
        end
        if type(data.fov)=='number' and data.fovCustomized then
            H.chosenFOV=math.clamp(data.fov,H.minFOV,H.maxFOV)
            H.fovCustomized=true
            H.startFovOverride()
            H.applyFovOverride()
            H.updateFovVisual()
        elseif data.fovCustomized==false then
            H.fovCustomized=false
            H.stopFovOverride()
            H.chosenFOV=math.clamp(H.startingFOV,H.minFOV,H.maxFOV)
            if workspace.CurrentCamera then
                workspace.CurrentCamera.FieldOfView=H.startingFOV
            end
            H.updateFovVisual()
        end
        if type(data.switches)=='table' then
            for key,desired in pairs(data.switches) do
                if type(desired)=='boolean' and H.optionSetters[key] then
                    H.optionSetters[key](desired)
                end
            end
        end
        return true
    end
    function H.config.load(name)
        name=H.config.normalize(name)
        if not name then return false,'Select a saved config.' end
        local data=H.config.tryRead(H.config.path(name)) or
            H.config.memory.saved[name]
        if not data then return false,'Config could not be found.' end
        if not H.config.apply(data) then return false,'Invalid config.' end
        H.config.selected=name
        return true,'Loaded ♡ '..name
    end
    function H.config.delete(name)
        name=H.config.normalize(name)
        if not name then return false,'Select a config to delete.' end
        for i=#H.config.names,1,-1 do
            if H.config.names[i]==name then table.remove(H.config.names,i) end
        end
        H.config.memory.saved[name]=nil
        if H.config.autoload==name then H.config.autoload=nil end
        if H.config.selected==name then H.config.selected=nil end
        if H.config.canPersist and type(delfile)=='function' then
            pcall(delfile,H.config.path(name))
        end
        H.config.indexSave()
        return true,'Removed ♡ '..name
    end

    local panel=H.new('Frame',{
        Name='OronaConfigsMenu',Size=UDim2.fromOffset(325,515),
        Position=UDim2.fromOffset(-339,174),Visible=false,
        BackgroundColor3=C.cream,BorderSizePixel=0,ZIndex=54,
        ClipsDescendants=false
    },main)
    H.config.panel=panel
    H.round(panel,22)
    H.stroke(panel,C.hot,3)
    H.new('UIStroke',{Color=C.lightEdge,Thickness=5,Transparency=.8},panel)
    H.new('UIGradient',{Rotation=90,Color=ColorSequence.new(C.cream,C.pale)},panel)
    local interior=H.new('Frame',{
        Position=UDim2.fromOffset(7,7),Size=UDim2.new(1,-14,1,-14),
        BackgroundColor3=C.white,BorderSizePixel=0,ZIndex=55
    },panel)
    H.round(interior,17)
    H.new('UIGradient',{Rotation=90,Color=ColorSequence.new(C.cream,C.pale)},interior)
    local ribbon=H.new('Frame',{
        Position=UDim2.fromOffset(13,13),Size=UDim2.new(1,-26,0,47),
        BackgroundColor3=C.soft,BorderSizePixel=0,ZIndex=57
    },panel)
    H.round(ribbon,13)
    H.stroke(ribbon,C.hot,1.3)
    local title=H.label(ribbon,'♡  KITTY CONFIGS  ♡',17,C.hot,
        UDim2.fromOffset(0,0),UDim2.fromScale(1,1))
    title.ZIndex=58
    local close=H.new('TextButton',{
        Position=UDim2.new(1,-45,0,17),Size=UDim2.fromOffset(32,32),
        Text='×',TextSize=23,Font=Enum.Font.GothamBold,
        TextColor3=C.hot,BackgroundColor3=C.white,
        AutoButtonColor=false,BorderSizePixel=0,ZIndex=60
    },panel)
    H.round(close,9)
    H.stroke(close,C.pink,1.4)
    local nameLabel=H.label(panel,'✿ Config name',13,C.dark,
        UDim2.fromOffset(24,72),UDim2.fromOffset(270,23))
    nameLabel.TextXAlignment=Enum.TextXAlignment.Left
    nameLabel.ZIndex=58
    local nameBox=H.new('TextBox',{
        Name='ConfigName',Position=UDim2.fromOffset(20,100),
        Size=UDim2.fromOffset(285,37),
        Text='',PlaceholderText='Name your preset ♡',
        ClearTextOnFocus=false,TextColor3=C.dark,
        PlaceholderColor3=C.dark,TextSize=14,
        Font=Enum.Font.Gotham,BackgroundColor3=C.white,
        BorderSizePixel=0,ZIndex=58
    },panel)
    H.round(nameBox,12)
    H.stroke(nameBox,C.pink,1.4)
    local function makeButton(label,x,y,w)
        local b=H.new('TextButton',{
            Size=UDim2.fromOffset(w,37),Position=UDim2.fromOffset(x,y),
            BackgroundColor3=C.soft,Text=label,TextColor3=C.dark,
            Font=Enum.Font.GothamBold,TextSize=13,
            AutoButtonColor=false,BorderSizePixel=0,ZIndex=58
        },panel)
        H.round(b,11)
        H.stroke(b,C.hot,1.1)
        H.con(b.MouseEnter,function()
            H.tween(b,{BackgroundColor3=C.pink,TextColor3=C.white},.12)
        end)
        H.con(b.MouseLeave,function()
            H.tween(b,{BackgroundColor3=C.soft,TextColor3=C.dark},.12)
        end)
        return b
    end
    local save=makeButton('♡ SAVE',20,147,137)
    local load=makeButton('✿ LOAD',168,147,137)
    local delete=makeButton('× DELETE',20,192,285)
    local autoButton=makeButton('AUTO LOAD : OFF',20,238,285)
    local listCaption=H.label(panel,'♡ YOUR SAVED CONFIGS ♡',12,C.hot,
        UDim2.fromOffset(24,290),UDim2.fromOffset(275,22))
    listCaption.ZIndex=58
    local list=H.new('ScrollingFrame',{
        Name='SavedConfigsList',Position=UDim2.fromOffset(20,315),
        Size=UDim2.fromOffset(285,135),BackgroundColor3=C.pale,
        BorderSizePixel=0,ScrollBarThickness=4,
        CanvasSize=UDim2.fromOffset(0,0),ZIndex=58
    },panel)
    H.round(list,12)
    H.stroke(list,C.soft,1)
    local layout=H.new('UIListLayout',{
        Padding=UDim.new(0,4),SortOrder=Enum.SortOrder.LayoutOrder
    },list)
    H.new('UIPadding',{
        PaddingTop=UDim.new(0,6),PaddingLeft=UDim.new(0,7),
        PaddingRight=UDim.new(0,7),PaddingBottom=UDim.new(0,7)
    },list)
    local status=H.label(panel,'♡ Save your favorite Kitty settings ♡',11,C.dark,
        UDim2.fromOffset(18,462),UDim2.fromOffset(291,40))
    status.ZIndex=58
    status.TextWrapped=true
    local function report(message)
        status.Text=message
    end
    local function updateAuto()
        autoButton.Text=H.config.autoload and
            ('AUTO LOAD : ON ♡ '..H.config.autoload) or 'AUTO LOAD : OFF'
    end
    local function refresh()
        for _,child in ipairs(list:GetChildren()) do
            if child:IsA('TextButton') then child:Destroy() end
        end
        table.sort(H.config.names)
        for n,name in ipairs(H.config.names) do
            local selected=H.config.selected==name
            local b=H.new('TextButton',{
                Name='Config_'..name,Size=UDim2.new(1,-15,0,29),
                Text=(selected and '♡  ' or '✿  ')..name,
                BackgroundColor3=selected and C.pink or C.white,
                TextColor3=selected and C.white or C.dark,
                Font=Enum.Font.GothamBold,TextSize=12,
                TextXAlignment=Enum.TextXAlignment.Left,
                AutoButtonColor=false,BorderSizePixel=0,
                LayoutOrder=n,ZIndex=60
            },list)
            H.round(b,8)
            b.MouseButton1Click:Connect(function()
                H.config.selected=name
                nameBox.Text=name
                refresh()
            end)
        end
        list.CanvasSize=UDim2.fromOffset(0,#H.config.names*34+12)
        updateAuto()
    end
    H.con(save.MouseButton1Click,function()
        local ok,message=H.config.save(nameBox.Text)
        report(message)
        if ok then refresh() end
    end)
    H.con(load.MouseButton1Click,function()
        local ok,message=H.config.load(nameBox.Text~='' and nameBox.Text or H.config.selected)
        report(message)
        if ok then refresh() end
    end)
    H.con(delete.MouseButton1Click,function()
        local _,message=H.config.delete(H.config.selected or nameBox.Text)
        report(message)
        refresh()
    end)
    H.con(autoButton.MouseButton1Click,function()
        local candidate=H.config.normalize(nameBox.Text) or H.config.selected
        if H.config.autoload then
            H.config.autoload=nil
            report('Auto Load disabled ♡')
        elseif candidate and table.find(H.config.names,candidate) then
            H.config.autoload=candidate
            report('Auto Load enabled ♡ '..candidate)
        else
            report('Save or select a config first ♡')
        end
        H.config.indexSave()
        updateAuto()
    end)
