    -- V72: mirrored dark-haired catgirl for OPEN Configs menu on the outside-left edge.
    -- Pink-haired original remains the CLOSED peeking tab art.
    local openGirlAsset=H.v49Art('Orona_V72_Open_Config_Girl_Mirrored.png',[===[

]===])
    local girl=H.new('ImageButton',{
        Name='OronaConfigCatgirlPeek',Size=UDim2.fromOffset(126,172),
        Position=UDim2.fromOffset(-114,88),
        BackgroundTransparency=1,Image='',AutoButtonColor=false,
        ClipsDescendants=false,ZIndex=65
    },main)
    -- The outline is made of tinted image copies, so it follows the art's
    -- transparent silhouette instead of showing a rectangular stroke.
    local closedGlows={}
    local panelGirl
    if girlAsset then
        for _,offset in ipairs({{-3,0},{3,0},{0,-3},{0,3},
            {-2,-2},{2,-2},{-2,2},{2,2}}) do
            local glow=H.new('ImageLabel',{
                Size=UDim2.fromOffset(126,172),
                Position=UDim2.fromOffset(offset[1],offset[2]),
                Image=girlAsset,ImageColor3=C.hot,
                ImageTransparency=1,BackgroundTransparency=1,
                ScaleType=Enum.ScaleType.Fit,ZIndex=65
            },girl)
            closedGlows[#closedGlows+1]=glow
        end
        H.new('ImageLabel',{
            Name='ConfigGirlCutout',Size=UDim2.fromScale(1,1),
            Image=girlAsset,ImageColor3=Color3.new(1,1,1),
            BackgroundTransparency=1,
            ScaleType=Enum.ScaleType.Fit,ZIndex=66
        },girl)
        panelGirl=H.new('ImageLabel',{
            Name='ConfigGirlOpenCutout',Size=UDim2.fromOffset(150,224),
            Position=UDim2.fromOffset(-104,-18),Visible=false,
            Image=openGirlAsset or girlAsset,
            ImageColor3=Color3.new(1,1,1),
            BackgroundTransparency=1,ScaleType=Enum.ScaleType.Fit,
            ZIndex=66
        },panel)
        H.con(girl.MouseEnter,function()
            if H.configOpen then return end
            for _,glow in ipairs(closedGlows) do
                H.tween(glow,{ImageTransparency=.28},.16)
            end
        end)
        H.con(girl.MouseLeave,function()
            for _,glow in ipairs(closedGlows) do
                H.tween(glow,{ImageTransparency=1},.16)
            end
        end)
    else
        local bow=H.label(girl,'♡  CONFIGS  ♡',13,C.hot,
            UDim2.fromOffset(6,40),UDim2.fromOffset(118,40))
        bow.ZIndex=66
        H.makeBow(girl,43,15,66)
    end
    function H.setConfigMenu(show)
        if unloaded then return end
        H.configOpen=show
        H.config.open=show
        girl.Visible=not show
        girl.Active=not show
        if panelGirl then panelGirl.Visible=show end
        for _,glow in ipairs(closedGlows) do
            glow.ImageTransparency=1
        end
        if show and H.openKittyTools then H.openKittyTools(false) end
        panel.Visible=show
        if show then
            panel.Position=UDim2.fromOffset(-316,174)
            H.tween(panel,{Position=UDim2.fromOffset(-339,174)},.2)
            refresh()
        end
        if H.fitMenuToScreen then H.fitMenuToScreen() end
    end
    H.con(girl.MouseButton1Click,function()
        H.setConfigMenu(not H.configOpen)
    end)
    H.con(close.MouseButton1Click,function()
        H.setConfigMenu(false)
    end)
    H.config.refresh=refresh
    H.config.status=report
    H.config.tryAutoload=function()
        if unloaded or not H.config.autoload then return end
        local ok,message=H.config.load(H.config.autoload)
        report(ok and ('Auto-loaded ♡ '..H.config.autoload) or message)
        refresh()
    end
    refresh()
end
-- ===== END V68 CONFIG KITTY =====

-- Capture the game mouse intent when the menu opens. Unlike V35,
-- do not reuse a lobby Default mouse state after the character/camera changes.
local savedMouse=UIS.MouseBehavior
local savedIcon=UIS.MouseIconEnabled
local menuCharacter=Me.Character
local menuCamera=workspace.CurrentCamera
local gameRequestedLock=nil
local gameLockCharacter=nil
local mouseStepName='OronaMouseV48'
local mouseProbeName='OronaMouseProbeV48'
local mouseBound=false
local mouseProbeBound=false

local function stopMenuMouseOverride()
    if mouseBound then
        RS:UnbindFromRenderStep(mouseStepName)
        mouseBound=false
    end
    if mouseProbeBound then
        RS:UnbindFromRenderStep(mouseProbeName)
        mouseProbeBound=false
    end
    modal.Visible=false
    modal.Modal=false
end

local function restoreGameMouse()
    stopMenuMouseOverride()
    -- First-person camera always wins over an old lobby mouse snapshot.
    local forceFirstPerson=Me.CameraMode==Enum.CameraMode.LockFirstPerson
    local transitioned=(menuCharacter~=Me.Character or
        menuCamera~=workspace.CurrentCamera)
    if forceFirstPerson then
        UIS.MouseBehavior=Enum.MouseBehavior.LockCenter
        UIS.MouseIconEnabled=false
    elseif gameRequestedLock and (not transitioned or
        gameLockCharacter==Me.Character) then
        UIS.MouseBehavior=gameRequestedLock
        UIS.MouseIconEnabled=false
    elseif not transitioned then
        UIS.MouseBehavior=savedMouse
        UIS.MouseIconEnabled=savedIcon
    else
        -- Round/lobby changed while the menu was open. Let the game camera
        -- decide instead of forcing the old third-person lobby mode.
        UIS.MouseBehavior=Enum.MouseBehavior.Default
        UIS.MouseIconEnabled=true
    end
end

local function restoreMouse()
    -- Never restore an old lobby snapshot if the menu was already closed;
    -- the camera state may have changed since that menu session.
    if menuOpen then restoreGameMouse()
    else stopMenuMouseOverride() end
end

local function setMenu(value)
    if unloaded then return end
    if value then finishMoonwalk();aimHeld=false end
    if value and not menuOpen then
        savedMouse=UIS.MouseBehavior
        savedIcon=UIS.MouseIconEnabled
        menuCharacter=Me.Character
        menuCamera=workspace.CurrentCamera
        gameRequestedLock=nil
        gameLockCharacter=nil
    end
    menuOpen=value
    main.Visible=value
    reopenButton.Visible=not value
    if value then
        modal.Visible=true
        modal.Modal=true
        -- The Roblox/game camera may request LockCenter when a round starts
        -- while the menu is open. Sample it after camera update BEFORE
        -- Orona releases the cursor later in the same frame.
        if not mouseProbeBound then
            mouseProbeBound=true
            RS:BindToRenderStep(mouseProbeName,
                Enum.RenderPriority.Camera.Value+30,function()
                    if unloaded or not menuOpen then return end
                    local current=UIS.MouseBehavior
                    if current==Enum.MouseBehavior.LockCenter or
                       current==Enum.MouseBehavior.LockCurrentPosition then
                        gameRequestedLock=current
                        gameLockCharacter=Me.Character
                    end
                end)
        end
        if not mouseBound then
            mouseBound=true
            RS:BindToRenderStep(mouseStepName,
                Enum.RenderPriority.Last.Value+10,function()
                    if unloaded or not menuOpen then return end
                    UIS.MouseBehavior=Enum.MouseBehavior.Default
                    UIS.MouseIconEnabled=true
                end)
        end
        UIS.MouseBehavior=Enum.MouseBehavior.Default
        UIS.MouseIconEnabled=true
    else
        restoreGameMouse()
    end
end

-- Right Shift works even when the game consumes normal InputBegan events.
-- Both this binding and the ordinary input fallback use a debounce, so one
-- press never opens then instantly closes the menu.
local menuActionName='OronaMenuActionV48'
local lastMenuPress=-100
local function requestMenuToggle()
    if unloaded or choosingMoonKey or UIS:GetFocusedTextBox() then return end
    local now=os.clock()
    if now-lastMenuPress<.2 then return end
    lastMenuPress=now
    setMenu(not menuOpen)
end
CAS:BindActionAtPriority(menuActionName,function(_,inputState)
    if inputState==Enum.UserInputState.Begin then
        requestMenuToggle()
    end
    -- Do not steal the game's own camera/shift-lock input binding.
    return Enum.ContextActionResult.Pass
end,false,3000,Enum.KeyCode.RightShift)
H.con(reopenButton.MouseButton1Click,requestMenuToggle)

local dragging=false
local dragStart,startPosition
H.con(header.InputBegan,function(input)
if input.UserInputType==Enum.UserInputType.MouseButton1 then
dragging=true
dragStart=input.Position
startPosition=main.Position
end
end)
H.con(UIS.InputChanged,function(input)
if dragging and input.UserInputType==Enum.UserInputType.MouseMovement then
local d=input.Position-dragStart
main.Position=UDim2.new(startPosition.X.Scale,
startPosition.X.Offset+d.X,
startPosition.Y.Scale,startPosition.Y.Offset+d.Y)
end
end)
H.con(UIS.InputEnded,function(input)
if input.UserInputType==Enum.UserInputType.MouseButton1 then
dragging=false
end
end)
