if unloaded then return end
restoreMouse()
CAS:UnbindAction(menuActionName)
unloaded=true
enabled=false
finishMoonwalk()
RS:UnbindFromRenderStep(motionRenderName)
RS:UnbindFromRenderStep(H.mw.renderName)
H.stopFovOverride()
if H.fovCustomized and workspace.CurrentCamera then
workspace.CurrentCamera.FieldOfView=H.startingFOV
end
setAutoGen(false)
if H.parry then H.parry.setEnabled(false) end
if S.Streamer then
    S.Streamer=false
    H.setStreamerPrivacy(false)
end
clearESP()
for _,c in ipairs(connections) do c:Disconnect() end
for _,c in pairs(playerConnections) do c:Disconnect() end
gui:Destroy()
if env.__OronaCleanup==unload then env.__OronaCleanup=nil end
table.clear(connections)
table.clear(playerConnections)
print("♡ Kitty Vision Orona V66 unloaded ♡")
end
H.con(H.unloadButton.MouseButton1Click,unload)
env.__OronaCleanup=unload
local function isMoonInput(input)
    if moonKey==nil then return false end
    if typeof(moonKey)=="EnumItem" then
        if moonKey.EnumType==Enum.KeyCode then
            return input.KeyCode==moonKey
        elseif moonKey.EnumType==Enum.UserInputType then
            return input.UserInputType==moonKey
        end
    end
    return false
end
local function keyDisplay(key)
    if not key then return 'Unbound' end
    local names={
        [Enum.UserInputType.MouseButton1]='Mouse 1',
        [Enum.UserInputType.MouseButton2]='Mouse 2',
        [Enum.UserInputType.MouseButton3]='Mouse 3',
    }
    return names[key] or key.Name
end
H.con(UIS.InputBegan,function(input,processed)
    if unloaded then return end
    if choosingMoonKey then
        if input.KeyCode==Enum.KeyCode.Escape then
            choosingMoonKey=false
            bindButton.Text=keyDisplay(moonKey)
            return
        end
        if input.UserInputType.Name:match('^MouseButton[1-3]$') then
            moonKey=input.UserInputType
            choosingMoonKey=false
            bindButton.Text=keyDisplay(moonKey)
        elseif input.KeyCode~=Enum.KeyCode.Unknown
            and input.KeyCode~=Enum.KeyCode.RightShift then
            moonKey=input.KeyCode
            choosingMoonKey=false
            bindButton.Text=keyDisplay(moonKey)
        end
        return
    end
    if input.KeyCode==Enum.KeyCode.RightControl then
        if not UIS:GetFocusedTextBox() and H.optionSetters.Streamer then
            H.optionSetters.Streamer(not S.Streamer)
        end
        return
    end
    if input.KeyCode==Enum.KeyCode.RightShift then
        requestMenuToggle() -- backup for experiences that consume CAS bindings
        return
    end
    -- Middle Mouse can be game-processed for camera pan; still honor the hold.
    if (not processed or input.UserInputType==Enum.UserInputType.MouseButton3)
        and not menuOpen and not UIS:GetFocusedTextBox()
        and isMoonInput(input) and S.Moonwalk then
        local c=workspace.CurrentCamera
        local char=Me.Character
        local hum=char and char:FindFirstChildOfClass('Humanoid')
        if c and hum and hum.Health>0 then
            local root=char:FindFirstChild('HumanoidRootPart')
            if root then startMoonwalk(hum,root,c) end
        end
    end
    if input.UserInputType==Enum.UserInputType.MouseButton2 then
        aimHeld=true
        lockedHead=nil
    end
end)
H.con(UIS.InputEnded,function(input)
    if isMoonInput(input) then finishMoonwalk() end
    if input.UserInputType==Enum.UserInputType.MouseButton2 then
        aimHeld=false
        lockedHead=nil
        H.gunLockedTorso=nil
    end
end)
H.con(UIS.WindowFocusReleased,finishMoonwalk)

-- On local respawn/round transition, release the modal mouse override;
-- the old lobby snapshot must not trap the new round in a free cursor view.
H.con(Me.CharacterAdded,function(char)
    if unloaded then return end
    if S.Streamer then task.spawn(H.hideStreamerNames,char) end
    H.invalidateRoundCache()
    finishMoonwalk()
    lockedHead=nil
    H.gunLockedTorso=nil
    if menuOpen then setMenu(false) end
    task.defer(function()
        if unloaded or menuOpen then return end
        if Me.CameraMode==Enum.CameraMode.LockFirstPerson then
            UIS.MouseBehavior=Enum.MouseBehavior.LockCenter
            UIS.MouseIconEnabled=false
        end
    end)
end)
H.con(Me:GetPropertyChangedSignal('CameraMode'),function()
    if unloaded or menuOpen then return end
    if Me.CameraMode==Enum.CameraMode.LockFirstPerson then
        UIS.MouseBehavior=Enum.MouseBehavior.LockCenter
        UIS.MouseIconEnabled=false
    end
end)

-- Camera replacement and character appearance loading may invalidate
-- existing highlights even if a player stays in the match.
H.con(workspace:GetPropertyChangedSignal('CurrentCamera'),function()
    if unloaded or not S.Players then return end
    task.defer(function()
        if unloaded or not S.Players then return end
        for _,p in ipairs(Players:GetPlayers()) do H.updatePlayer(p) end
    end)
end)
local function watchPlayer(p)
if p==Me or playerConnections[p] then return end
playerConnections[p]=p.CharacterAdded:Connect(function(char)
char:WaitForChild("Head",10)
if S.Streamer then task.spawn(H.hideStreamerNames,char) end
if not unloaded and enabled then H.updatePlayer(p) end
end)
if S.Streamer and p.Character then task.spawn(H.hideStreamerNames,p.Character) end
if enabled then H.updatePlayer(p) end
end
for _,p in ipairs(Players:GetPlayers()) do watchPlayer(p) end
H.con(Players.PlayerAdded,watchPlayer)
H.con(Players.PlayerRemoving,function(p)
H.clearPlayer(p)
if playerConnections[p] then
playerConnections[p]:Disconnect()
playerConnections[p]=nil
end
end)
-- Native prompts may be added/enabled dynamically as a round starts.
-- A changed prompt does not require recomputing the entire map.
H.con(workspace.DescendantAdded,function(o)
    if unloaded or not H.vaultRoundActive() then return end
    if S.Players then
        local model=o:IsA('Model') and o
            or (o:IsA('Humanoid') and o.Parent and o.Parent:IsA('Model') and o.Parent)
        if model then H.considerNPC(model) end
    end
    if not (S.Hooks or S.Generators or S.Pallets or S.Vaults or S.ExitGates or S.Traps or S.Pumpkins) then return end
    if H.physical(o) or o:IsA('ProximityPrompt') then
        local map=workspace:FindFirstChild('Map')
        if (not map or o:IsDescendantOf(map)) and
            not (Me.Character and o:IsDescendantOf(Me.Character)) then
            local n=o.Name:lower()
            local objectiveName=n:find('pallet',1,true) or n=='intact'
                or n=='standingpallet' or n=='droppablepallet'
                or n:find('hook',1,true) or n:find('generator',1,true)
                or n:find('window',1,true) or n:find('vault',1,true)
                or n:find('gate',1,true) or n:find('trap',1,true)
                or n:find('pumpkin',1,true) or n=='bottom' or n=='inviswall'
            if objectiveName or o:IsA('ProximityPrompt') then enqueue(o) end
            if S.Vaults and (n=='window' or n=='bottom' or
                n=='vaulttrigger' or n=='inviswall') then
                task.defer(function()
                    if unloaded or not S.Vaults or not H.vaultRoundActive() then return end
                    local root=H.vaultRoot(o)
                    if root and H.windowInteractionPart(root) then
                        H.vaultState.candidates[root]=true
                        H.updateVaults()
                    end
                end)
            end
            if n=='window' or n=='newpallet' or n=='pallet' or n=='intact'
                or n:find('pallet',1,true)
                or n=='generator' or n=='hook' or n=='gate' or n=='exitlever' then
                if not H.quickIndexQueued then
                    H.quickIndexQueued=true
                    task.defer(function()
                        H.quickIndexQueued=false
                        if not unloaded and H.fastIndexKnown then H.fastIndexKnown() end
                    end)
                end
            end
        end
    end
end)
-- Studio-authored Vaultable tags give reliable coverage even when the
-- map has a custom VAULT prompt instead of a native ProximityPrompt.
for _,tag in ipairs({'Vault','Vaultable','UsableVault','VaultOpening',
    'VaultInteractable','VaultWindow','VDVault'}) do
    H.con(CollectionService:GetInstanceAddedSignal(tag),function(node)
        if unloaded or not S.Vaults or not H.vaultInsideMap(node) then return end
        local root=H.vaultRoot(node)
        if root then H.vaultState.candidates[root]=true end
    end)
end
H.con(PPS.PromptShown,function(prompt)
    if not unloaded and H.vaultRoundActive() and (S.Hooks or S.Generators or S.Pallets or S.Vaults or S.ExitGates or S.Pumpkins) then
        enqueue(prompt)
    end
end)
H.con(PPS.PromptTriggered,function(prompt)
    if not unloaded and H.vaultRoundActive() and (S.Hooks or S.Generators or S.Pallets or S.Vaults or S.ExitGates or S.Pumpkins) then
        enqueue(prompt)
    end
end)
-- V55 new gate tags may arrive after map discovery (StreamingEnabled).
for _,tag in ipairs({'ExitGate','VDExitGate','EscapeGate','ExitLever'}) do
    H.con(CollectionService:GetInstanceAddedSignal(tag),function(node)
        if unloaded or not S.ExitGates or not H.vaultInsideMap(node) then return end
        local root=H.gateRoot(node)
        if root then H.gateState.candidates[root]=true;H.updateGates() end
    end)
end
H.con(workspace.DescendantRemoving,function(o)
    if H.npcFX[o] then H.clearNPC(o) end
    H.npcCandidates[o]=nil
    if objectFX[o] then removeObject(o) end
    if palletCandidates[o] then palletCandidates[o]=nil end
    H.palletEvidenceCache[o]=nil
    H.palletEverValid[o]=nil
    if H.vaultState.candidates[o] then H.vaultState.candidates[o]=nil end
    if H.gateState.candidates[o] then H.gateState.candidates[o]=nil end
    if H.gateState.generators[o] then H.gateState.generators[o]=nil end
    if H.gateState.highlights[o] then H.removeGate(o) end
    if H.vaultState.highlights[o] then H.removeVaultMarker(o) end
    if H.pumpkinState.candidates[o] then H.pumpkinState.candidates[o]=nil end
    if H.pumpkinState.highlights[o] then H.removePumpkin(o) end
    if objectiveCandidates.Hooks[o] then objectiveCandidates.Hooks[o]=nil end
    if objectiveCandidates.Generators[o] then objectiveCandidates.Generators[o]=nil end
end)
-- V64 round watcher. Turning a toggle ON in the lobby only remembers the
-- preference; nothing is rendered until the match begins.
H.wasRoundActive=H.vaultRoundActive()
H.roundWatchClock=0
H.scanFrameClock=0
H.con(RS.Heartbeat,function(dt)
    if unloaded then return end
    H.roundWatchClock+=math.min(dt,0.1)
    if H.roundWatchClock>=.45 then
        H.roundWatchClock=0
        local live=H.vaultRoundActive()
        if live~=H.wasRoundActive then
            H.wasRoundActive=live
            if not live then
                -- An old match's map can stay present during intermission.
                clearESP()
                scanQueue,scanHead,scanTail,queued={},1,0,{}
            else
                -- Index only once per transition; subsequent spawned objectives
                -- are picked up by DescendantAdded and timed refreshes.
                if H.fastIndexKnown then H.fastIndexKnown() end
                H.indexEntireMapOnce(true)
                if S.Traps or S.Pumpkins then scan() end
                if S.Players or S.Kitties then
                    for _,p in ipairs(Players:GetPlayers()) do H.updatePlayer(p) end
                    if S.Players then H.indexNPCs() end
                end
            end
        end
    end
    if not H.wasRoundActive then return end
    H.scanFrameClock+=math.min(dt,0.1)
    if H.scanFrameClock>=.05 then
        H.scanFrameClock=0
        processQueue()
    end
end)
-- New rounds can replace Map or stream content into it; rediscover once
-- per map change, rather than rescanning all Workspace every few seconds.
local activeMap=workspace:FindFirstChild('Map')
for _,node in ipairs({workspace,Me,H.repStorage}) do
    for _,attribute in ipairs({'RoundActive','InRound','IsInRound',
        'MatchActive','GameInProgress','MatchStarted','RoundStarted',
        'Role','PlayerRole','RoundState','MatchState','GameStatus','Phase'}) do
        H.con(node:GetAttributeChangedSignal(attribute),H.invalidateRoundCache)
    end
end
H.con(Me:GetPropertyChangedSignal('Team'),H.invalidateRoundCache)
H.con(workspace.ChildAdded,function(child)
    if unloaded or child.Name~='Map' then return end
    H.invalidateRoundCache()
    task.defer(function()
        if unloaded then return end
        activeMap=child
        H.globalObjectiveIndex.map=nil
        if S.Vaults then H.vaultState.candidates={};H.discoverVaults() end
        if S.ExitGates then H.gateState.candidates={};H.gateState.generators={};H.discoverGates() end
        if S.Pumpkins then H.pumpkinState.candidates={};H.discoverPumpkins() end
        if S.Pallets then palletCandidates={};discoverPallets() end
        if S.Players then H.indexNPCs() end
        scan()
    end)
end)
H.con(workspace.ChildRemoved,function(child)
    if child~=activeMap then return end
    H.invalidateRoundCache()
    activeMap=nil
    if S.Vaults then H.vaultState.candidates={}
        for root in pairs(H.vaultState.highlights) do H.removeVaultMarker(root) end
    end
    if S.ExitGates then H.gateState.candidates={};H.gateState.generators={}
        for root in pairs(H.gateState.highlights) do H.removeGate(root) end
    end
    if S.Pumpkins then H.pumpkinState.candidates={}
        for root in pairs(H.pumpkinState.highlights) do H.removePumpkin(root) end
    end
end)
-- Refresh usability, not just existence. Prompt.Enabled may change as
-- objectives are used, maps rotate, or the player changes roles.
-- One pass per 0.85 seconds avoids repeatedly scanning Workspace.
task.spawn(function()
    while not unloaded do
        task.wait(PALLET_REFRESH)
        if S.Streamer or not H.vaultRoundActive() then
            -- No geometry scans or ESP allocations while streaming/lobby.
            continue
        end
        if S.Pallets then
            -- Re-index occasionally, not every refresh: active candidates
            -- are already tracked by Workspace.DescendantAdded.
            if os.clock()-(H.lastPalletQuickIndexAt or 0)>5 then
                H.lastPalletQuickIndexAt=os.clock()
                if H.fastIndexKnown then H.fastIndexKnown() end
            else
                updatePallets()
            end
        end
        if S.ExitGates then H.updateGates() end
        if S.Vaults then
            H.updateVaults()
            if H.vaultState.lastVisible==0 and H.fastIndexKnown then
                H.fastIndexKnown()
            end
        end
        if S.Pumpkins and os.clock()-(H.pumpkinState.lastUpdate or 0)>3.5 then
            H.pumpkinState.lastUpdate=os.clock()
            H.updatePumpkins()
        end
        for kind,targets in pairs(objectiveCandidates) do
            if S[kind] then
                local remove={}
                for root in pairs(targets) do
                    if not root:IsDescendantOf(workspace) then
                        remove[#remove+1]=root
                    elseif H.confirmedObjective(root,kind) then
                        if kind=='Generators' then
                            if not generatorComplete(root) then
                                -- Whole-model generator highlight matches Map.newGenerators.Generator.
                                mark(root,kind,root)
                            end
                        else
                            mark(root,kind)
                        end
                    elseif objectFX[root] and objectFX[root].kind==kind then
                        removeObject(root)
                    end
                end
                for _,root in ipairs(remove) do targets[root]=nil end
            end
        end
    end
end)
task.spawn(function()
while not unloaded do
task.wait(2)
if not H.vaultRoundActive() then continue end
for _,p in ipairs(Players:GetPlayers()) do H.updatePlayer(p) end
H.updateNPCs()
local old={}
for root,r in pairs(objectFX) do
if not root:IsDescendantOf(workspace) or not S[r.kind]
or not H.safeObjectiveTarget(root,r.target,r.kind)
or (r.kind=='Traps' and trapRoot(root)==nil)
or ((r.kind=='Hooks' or r.kind=='Generators')
    and not H.confirmedObjective(root,r.kind)) then
old[#old+1]=root
end
end
for _,root in ipairs(old) do removeObject(root) end
for root in pairs(genBars) do
    if generatorComplete(root) then
        removeObject(root)
    else
        refreshGenBar(root)
    end
end
end
end)
